async function pressNavItem(page, name) {
  await page.locator('[data-slot="sidebar"] a', { hasText: name }).first().click();
}
const assert = (condition, message) => { if (!condition) throw new Error(message); };
/** What holds the focus right now, in one short phrase (for a failure message: the actual value, not only "it was not there"). */
const describeFocus = (page) => page.evaluate(() => {
  const a = document.activeElement;
  if (!a) return "nothing (document.activeElement is null)";
  if (a === document.body) return "<body>";
  const label = (a.getAttribute("aria-label") || a.textContent || "").trim().slice(0, 24);
  return `<${a.tagName.toLowerCase()}${a.id ? `#${a.id}` : ""}${a.getAttribute("data-testid") ? ` data-testid=${a.getAttribute("data-testid")}` : ""}${a.getAttribute("role") ? ` role=${a.getAttribute("role")}` : ""}${label ? ` "${label}"` : ""}>`;
});
/**
 * Wait until the focus is on the target, then say so; when it never arrives, say where it really was.
 * Radix hands the focus back to the trigger a tick AFTER the layer has left the page (FocusScope's unmount runs in a setTimeout), so "the layer is detached" does not yet mean "the focus is back":
 * reading `document.activeElement` in the same breath is a sample of one phase.  `target` is a Locator (the element itself) or a CSS selector (what the focused element must match).
 */
async function focusOn(page, target, what, timeout = 5000) {
  const element = typeof target === "string" ? null : await target.elementHandle({ timeout });
  try {
    await page.waitForFunction(([selector, el]) => { const a = document.activeElement; return Boolean(a) && (el ? a === el : a.matches(selector)); }, [typeof target === "string" ? target : null, element], { timeout });
  } catch {
    throw new Error(`${what} (the focus stayed on ${await describeFocus(page)} for ${timeout} ms)`);
  } finally { await element?.dispose(); }
}

// --- checks ----------------------------------------------------------------------------------------------
async function everyPageOpens(ctx) {
  const bad = [];
  for (const def of PAGES) {
    // A page that is about a state of the fake backend (the empty watchlist, a line with a turn that finished while away) opens on that state: its readiness depends on it.
    const view = await newView(ctx.browser, { width: 1440, theme: "light", identity: def.identity ?? "personal", label: def.name, unmatched, ...(typeof def.view === "function" ? def.view() : {}) });
    try {
      await view.page.goto(`${ctx.server.url}${def.hash ?? ""}`, { waitUntil: "load" });
      await waitReady(view.page, def);
      if (view.problems.pageErrors.length) bad.push(`${def.name}: uncaught exception ${view.problems.pageErrors[0].split("\n")[0]}`);
    } catch (error) { bad.push(`${def.name}: ${String(error.message).split("\n")[0]}`); }
    await view.close();
  }
  assert(!bad.length, bad.join("; "));
  return `${PAGES.length} pages ready`;
}

async function sendMessageStreams(ctx) {
  const view = await openChat(ctx, "send-message");
  try {
    const { page } = view;
    await page.locator("#agent-draft").fill(SMOKE_TEXT);
    await page.locator("[data-testid=send]").click();
    await page.locator("[data-testid=message][data-role=user]", { hasText: SMOKE_TEXT }).waitFor({ timeout: 10000 });
    await page.locator("[data-testid=message][data-role=assistant]", { hasText: FAKE_ANSWER }).waitFor({ timeout: 10000 });
    await page.locator("#agent-draft:not([disabled])").waitFor({ timeout: 10000 });
    await page.locator("#agent-draft").fill("再问一句");
    assert((await page.locator("#agent-draft").inputValue()) === "再问一句", "composer did not accept input after the turn");
    return "user message, streamed answer, composer usable again";
  } finally { await view.close(); }
}

async function switchBotAndBack(ctx) {
  const view = await openChat(ctx, "switch-bot");
  try {
    const { page } = view;
    await page.locator("#agent-draft").fill(SMOKE_TEXT);
    await page.locator("[data-testid=send]").click();
    await page.locator("[data-testid=message][data-role=assistant]", { hasText: FAKE_ANSWER }).waitFor({ timeout: 10000 });
    await page.locator("#agent-draft:not([disabled])").waitFor({ timeout: 10000 });
    const before = await page.evaluate(() => location.hash);
    await pressBotRow(page, "NewsBot");
    await page.waitForFunction((id) => location.hash === `#/chat/${id}`, BOT.newsbot, { timeout: 10000 });
    await page.locator("h1", { hasText: "NewsBot" }).waitFor({ timeout: 10000 });
    await pressBotRow(page, "FinBot");
    await page.locator("h1", { hasText: "FinBot" }).waitFor({ timeout: 10000 });
    await page.locator("[data-testid=message][data-role=assistant]", { hasText: FAKE_ANSWER }).waitFor({ timeout: 10000 });
    return `${before || "(empty)"} -> #/chat/<NewsBot> -> back; earlier answer still present`;
  } finally { await view.close(); }
}

