async function replayGenerateBody(ctx) {
  const notes = [];
  const view = await openReplay(ctx, "replay generate", { patch: { replayRunningPolls: 3 } });
  try {
    const { page } = view;
    const form = await page.evaluate(() => ({ date: document.querySelector("[data-testid=replay-date]").value, max: document.querySelector("[data-testid=replay-date]").max, required: document.querySelector("[data-testid=replay-date]").required, symbol: document.querySelector("[data-testid=replay-symbol]").textContent.trim(), button: document.querySelector("[data-testid=replay-generate]").textContent.trim() }));
    assert(form.date === REPLAY_BASE.form.dateValue && form.max === REPLAY_BASE.form.dateMax && form.required === REPLAY_BASE.form.dateRequired, `the date field: ${JSON.stringify(form)} vs ${REPLAY_BASE.form.dateValue} max ${REPLAY_BASE.form.dateMax}`);
    assert(form.symbol === REPLAY_BASE.form.selectedSymbol && form.button.includes(REPLAY_BASE.form.buttonText), `the form: ${JSON.stringify(form)}`);
    const before = await page.locator("[data-testid=replay-row]").count();
    assert(before === REPLAY_BASE.form.listedReplays.length, `${before} replays listed, the old page listed ${REPLAY_BASE.form.listedReplays.length}`);
    await page.locator("[data-testid=replay-generate]").click();
    const sent = await pollFor(page, () => replayPosts(view).length >= 1 && replayPosts(view), 8000);
    assert(sent.length === 1, `${sent.length} requests for one press`);
    assert(sameJson(sent.map((q) => ({ body: q.body, idempotencyKey: q.idempotencyKey })), REPLAY_BASE.bodies.defaults.posts), `the default body changed: ${JSON.stringify(sent)} vs ${JSON.stringify(REPLAY_BASE.bodies.defaults.posts)}`);
    const row = page.locator("[data-slot=task-row]");
    await row.first().waitFor({ timeout: 8000 });
    const rowText = await row.first().innerText();
    assert(rowText.includes("历史回放") && rowText.includes("AAPL") && rowText.includes(REPLAY_BASE.form.dateValue), `the task row: ${rowText}`);
    assert(await page.locator("[data-testid=replay-generate]").isDisabled(), "the button is not waiting for the job (the old one was disabled)");
    await row.first().waitFor({ state: "detached", timeout: 25000 });
    await page.waitForFunction((n) => document.querySelectorAll("[data-testid=replay-row]").length === n + 1, before, { timeout: 15000 });
    await page.waitForFunction((id) => document.querySelector("[data-testid=replay-detail]")?.getAttribute("data-version") === id, REPLAY_ID.created, { timeout: 15000 });
    assert(!(await page.locator("[data-testid=replay-generate]").isDisabled()), "the button stays disabled after the job");
    const trail = view.mock.requests.map((r) => `${r.method} ${r.path}`);
    const at = (needle, from = 0) => trail.findIndex((line, i) => i >= from && line.includes(needle));
    const post = at("POST /v2/historical-replays"), job1 = at("GET /v2/jobs/", post), job2 = at("GET /v2/jobs/", job1 + 1), list = at("GET /v2/evaluations", job2), made = at(`GET /v2/forecast-versions/${REPLAY_ID.created}`, list);
    assert(post >= 0 && job1 > post && job2 > job1 && list > job2 && made > list, `the read order after the press: ${JSON.stringify([post, job1, job2, list, made])}`);
    notes.push("default body, task row, one more replay");
  } finally { await view.close(); }
  const other = await openReplay(ctx, "replay generate tsla");
  try {
    const { page } = other;
    await page.locator("[data-testid=replay-symbol]").click();
    const choices = await page.locator("[data-symbol]").evaluateAll((els) => els.map((e) => e.getAttribute("data-symbol")));
    assert(sameJson(choices, REPLAY_BASE.form.symbols), `the companies: ${choices}`);
    await page.locator("[data-symbol=TSLA]").click();
    await page.locator("[data-testid=replay-date]").fill("2026-09-15");
    await page.locator("[data-testid=replay-generate]").click();
    const sent = await pollFor(page, () => replayPosts(other).length >= 1 && replayPosts(other), 8000);
    assert(sameJson(sent.map((q) => ({ body: q.body, idempotencyKey: q.idempotencyKey })), REPLAY_BASE.bodies.tsla0915), `the TSLA body: ${JSON.stringify(sent)}`);
    notes.push("TSLA + 2026-09-15 body");
  } finally { await other.close(); }
  return `the request body, header and read order equal the old page's recorded ones (${notes.join("; ")}); the company list is the watchlist`;
}

async function replayValidation(ctx) {
  const notes = [];
  for (const [name, c] of Object.entries(REPLAY_BASE.validation)) {
    const view = await openReplay(ctx, `replay validation ${name}`);
    try {
      const { page } = view;
      await page.locator("[data-testid=replay-date]").fill(c.value);
      await page.locator("[data-testid=replay-generate]").click();
      if (c.sent) {
        const sent = await pollFor(page, () => replayPosts(view).length >= 1 && replayPosts(view), 8000);
        assert(sent.length === 1 && sent[0].body === c.posts[0].body, `${name}: the old form sent ${c.posts[0].body}, now ${JSON.stringify(sent.map((q) => q.body))}`);
      } else {
        await page.locator("[data-testid=replay-form-error]").waitFor({ timeout: 5000 });
        assert(replayPosts(view).length === 0, `${name}: sent a request the old form held back`);
        assert(((await page.locator("[data-testid=replay-form-error]").innerText()).trim()).length > 4, `${name}: the field does not say why`);
        assert((await page.locator("[data-testid=replay-date]").getAttribute("aria-invalid")) === "true", `${name}: the field is not marked invalid`);
      }
      notes.push(`${name}:${c.sent ? "sent" : "held"}`);
    } finally { await view.close(); }
  }
  for (const [name, patch] of [["failed-timeout", { replayFail: true, replayRunningPolls: 1, replayError: "forecast_provider_timeout" }], ["failed-unknown-code", { replayFail: true, replayRunningPolls: 1, replayError: "something_new" }], ["blocked-data", { replayFail: "blocked", replayRunningPolls: 1, replayError: "insufficient_price_history" }]]) {
    const base = REPLAY_BASE.failures[name];
    const view = await openReplay(ctx, `replay ${name}`, { patch });
    try {
      const { page } = view;
      await page.locator("[data-testid=replay-generate]").click();
      await page.locator("[data-testid=replay-failure]").waitFor({ timeout: 20000 });
      const text = (await page.locator("[data-testid=replay-failure]").innerText()).replace(/\s+/g, " ");
      const title = base.text.includes("资料不足，回放未生成") ? "资料不足，回放未生成" : "回放任务失败";
      assert(text.includes(title) && text.includes(patch.replayError) && text.includes("未生成回放"), `${name}: ${text}`);
      const after = (text.split("未生成回放：")[1] ?? "").replace("忽略", "").trim();
      if (name === "failed-timeout") assert(after !== patch.replayError && after.length > patch.replayError.length + 6, `${name}: the code stands alone, no sentence: ${text}`);
      if (name === "failed-unknown-code") assert(after === "something_new", `${name}: ${text}`);
      assert((await page.locator("[data-testid=replay-row]").count()) === base.listCount, `${name}: ${await page.locator("[data-testid=replay-row]").count()} replays listed`);
      assert(!(await page.locator("[data-testid=replay-generate]").isDisabled()) === !base.buttonDisabled, `${name}: the button`);
      assert((await page.locator("[data-testid=replay-failure] [data-slot=status-badge]").getAttribute("data-kind")) === "failure", `${name}: the badge kind`);
      await page.locator("[data-testid=replay-failure] button", { hasText: "忽略" }).click();
      await page.locator("[data-testid=replay-failure]").waitFor({ state: "detached", timeout: 3000 });
      notes.push(name);
    } finally { await view.close(); }
  }
  return `the form is held to the old rules (${notes.join(", ")}); an empty or future day is said under the field and nothing is sent; failed / blocked jobs say the status words and the reason`;
}

async function replayPhoneLayer(ctx) {
  const view = await openReplay(ctx, "replay phone layer", { width: 1440 });
  try {
    const { page } = view;
    await page.locator("[data-testid=replay-row]").nth(1).click();
    await page.waitForFunction(() => document.querySelector("[data-testid=replay-detail]")?.getAttribute("data-version") === "f3000000-0000-4000-8000-000000000002", null, { timeout: 15000 });
    await page.locator("[data-testid=brief-toggle]").click();
    assert((await page.locator("[data-testid=brief-toggle]").getAttribute("aria-expanded")) === "false", "the brief did not fold");
    await page.evaluate(() => { document.querySelector("[data-testid=replay-detail]").__marker = "kept"; });
    const state = () => page.evaluate(() => ({ marker: document.querySelector("[data-testid=replay-detail]")?.__marker ?? null, selected: document.querySelector("[data-testid=replay-row][data-selected]")?.getAttribute("data-id"), folded: document.querySelector("[data-testid=brief-toggle]")?.getAttribute("aria-expanded"), dialog: Boolean(document.querySelector("[data-testid=replay-drawer][role=dialog]")) }));
    for (const width of [390, 1440, 390, 1440]) {
      await page.setViewportSize({ width, height: width === 390 ? 844 : 900 });
      await page.waitForFunction((w) => window.innerWidth === w, width);
      await settle(page);
      const now = await state();
      assert(now.marker === "kept" && now.selected === "f3000000-0000-4000-8000-000000000002" && now.folded === "false", `after ${width}: ${JSON.stringify(now)} (the detail element, the choice or the folded brief was lost)`);
      assert(!now.dialog, `after ${width}: a layer without a press`);
    }
    await page.setViewportSize({ width: 390, height: 844 });
    await settle(page);
    await page.locator("[data-testid=replay-row]").nth(1).click();
    const layer = page.locator("[data-testid=replay-drawer]");
    await layer.waitFor({ timeout: 5000 });
    const box = await layer.boundingBox();
    assert(box && box.x === 0 && box.y === 0 && Math.abs(box.width - 390) < 1 && Math.abs(box.height - 844) < 1, `the layer is not the screen: ${JSON.stringify(box)}`);
    assert((await layer.getAttribute("aria-modal")) === "true" && (await layer.getAttribute("role")) === "dialog", "the layer is not a modal dialog");
    assert((await page.evaluate(() => document.body.style.overflow)) === "hidden", "the page behind scrolls");
    const stops = await layer.locator("a[href],button,input,select,textarea,summary").count();
    for (let i = 0; i < stops + 3; i++) {
      await page.keyboard.press("Tab");
      assert(await page.evaluate(() => Boolean(document.activeElement?.closest("[data-testid=replay-drawer]"))), `Tab ${i + 1}: the focus left the layer`);
    }
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.waitForFunction(() => !document.querySelector("[data-testid=replay-drawer]"));
    assert((await state()).marker === "kept", "the detail element was replaced at 1440");
    await page.setViewportSize({ width: 390, height: 844 });
    await layer.waitFor({ timeout: 5000 });
    const back = await state();
    assert(back.marker === "kept" && back.folded === "false", "the detail element or its brief state was lost on the way back");
    await page.locator("[data-testid=replay-drawer-back]").click();
    await layer.waitFor({ state: "detached", timeout: 3000 });
    await focusOn(page, "[data-testid=replay-row][data-selected]", "the focus did not return to the chosen row", 3000);
    assert((await page.evaluate(() => document.body.style.overflow)) !== "hidden" && (await page.locator("[inert]").count()) === 0, "scroll lock or inert left behind");
    await page.locator("[data-testid=replay-row]").nth(1).click();
    await layer.waitFor({ timeout: 5000 });
    await page.keyboard.press("Escape");
    await layer.waitFor({ state: "detached", timeout: 3000 });
    await focusOn(page, "[data-testid=replay-row][data-selected]", "Esc: the focus did not return", 3000);
    const count = await page.locator("[data-slot=opinion-disclaimer]").count();
    assert(count === 1, `${count} disclaimers on the replay page`);
  } finally { await view.close(); }
  return "1440 <-> 390 four times (and once with the layer open): the same detail element, the chosen replay and the folded brief are kept; at 390 the layer is the whole screen and modal, Tab stays inside, 返回列表 / Esc close it and return the focus, scroll lock and inert are undone; one disclaimer on the page";
}

const iconNameOf = (page, selector) => page.evaluate((sel) => { const svg = document.querySelector(`${sel} svg`); return svg ? [...svg.classList].find((c) => c.startsWith("lucide-")) ?? "svg" : null; }, selector);
async function monitorFourStates(ctx) {
  const expect = { healthy: ["success", "lucide-circle-check", "text-success", "监控正常", "最近扫描成功"], delayed: ["action", "lucide-hourglass", "text-action", "监控延迟", "运行延迟"], degraded: ["failure", "lucide-circle-x", "text-danger", "监控异常", "部分失败或降级"], none: ["neutral", null, "text-muted-foreground", "尚无记录", "没有运行记录"] };
  const seen = [];
  for (const [state, [kind, icon, token, chip, headline]] of Object.entries(expect)) {
    const view = await openFresh(ctx, `monitor ${state}`, "#/research/monitor", { patch: state === "healthy" ? {} : { monitor: state }, ready: "[data-testid=monitor-health]" });
    try {
      const { page } = view;
      const card = "[data-testid=monitor-health]";
      assert((await page.locator(card).getAttribute("data-state")) === (state === "none" ? "not_recorded" : state), `${state}: data-state`);
      assert((await page.locator(`${card} [data-slot=status-badge]`).getAttribute("data-kind")) === kind, `${state}: badge kind`);
      assert((await page.locator(`${card} [data-slot=status-badge]`).innerText()).trim() === chip, `${state}: chip words`);
      assert((await page.locator("[data-testid=monitor-headline]").innerText()).trim() === headline, `${state}: headline`);
      const iconNow = await iconNameOf(page, `${card} [data-slot=status-badge]`);
      assert(iconNow === icon, `${state}: icon ${iconNow} != ${icon}`);
      const colours = await page.evaluate(({ card, token }) => {
        const probe = document.createElement("i"); probe.className = token; document.body.appendChild(probe);
        const want = getComputedStyle(probe).color; probe.remove();
        const mark = document.querySelector(`${card} [data-slot=status-badge] svg`) ?? document.querySelector(`${card} [data-slot=status-badge] span[aria-hidden]`);
        return { want, icon: mark ? getComputedStyle(mark).color : null };
      }, { card, token });
      assert(colours.icon === colours.want, `${state}: the icon colour ${colours.icon} is not the ${token} colour ${colours.want}`);
      seen.push(colours.want);
      const chipPage = await openFresh(ctx, `monitor chip ${state}`, "#/research", { patch: state === "healthy" ? {} : { monitor: state }, ready: "[data-testid=monitor-chip] [data-slot=status-badge]" });
      try {
        await chipPage.page.waitForFunction(() => !/正在读取/.test(document.querySelector("[data-testid=monitor-chip]").innerText), null, { timeout: 10000 });
        assert((await chipPage.page.locator("[data-testid=monitor-chip] [data-slot=status-badge]").getAttribute("data-kind")) === kind, `${state}: the watchlist chip's kind`);
        assert((await chipPage.page.locator("[data-testid=monitor-chip]").innerText()).trim() === chip, `${state}: the watchlist chip's words`);
      } finally { await chipPage.close(); }
    } finally { await view.close(); }
  }
  assert(new Set(seen.slice(0, 3)).size === 3, `the three coloured states do not differ: ${seen}`);
  return "正常 / 延迟 / 异常 / 无记录: badge kind success / action / failure / neutral, icon circle-check / hourglass / circle-x / none, icon colour = the token, words and headline fixed; the watchlist chip is the same component";
}

async function monitorDotInSidebar(ctx) {
  const notes = [];
  for (const [state, patch, label, token] of [["healthy", {}, null, null], ["none", { monitor: "none" }, null, null], ["delayed", { monitor: "delayed" }, "监控延迟", "--action"], ["degraded", { monitor: "degraded" }, "监控异常", "--danger"]]) {
    const view = await openFresh(ctx, `monitor dot ${state}`, "#/research/scores", { patch, ready: "[data-testid=cohort-card]" });
    try {
      const { page } = view;
      await pollFor(page, () => monitorReads(view) >= 1, 8000);
      assert(monitorReads(view) === 1, `${state}: ${monitorReads(view)} reads of the monitor on entering the research area`);
      await settle(page);
      const dots = await page.locator('[data-slot="sidebar"] [data-testid=monitor-dot]').count();
      if (!label) { assert(dots === 0 && (await page.locator("[data-testid=monitor-dot]").count()) === 0, `${state}: a dot for a monitor that is ${state}`); notes.push(`${state}: none`); continue; }
      await page.locator('[data-slot="sidebar"] [data-testid=monitor-dot]').waitFor({ timeout: 5000 });
      assert((await page.locator('[data-slot="sidebar"] [data-testid=monitor-dot]').count()) === 1, `${state}: ${dots} dots`);
      assert((await page.locator('[data-slot="sidebar"] [data-testid=monitor-dot]').getAttribute("aria-label")) === label, `${state}: the dot's words`);
      const beside = await page.locator('[data-slot="sidebar"] a', { hasText: "研究" }).first().evaluate((a) => Boolean(a.querySelector("[data-testid=monitor-dot]")));
      assert(beside, `${state}: the dot is not beside 研究`);
      const same = await page.evaluate((token) => { const probe = document.createElement("i"); probe.style.backgroundColor = `var(${token})`; document.body.appendChild(probe); const want = getComputedStyle(probe).backgroundColor; probe.remove(); return getComputedStyle(document.querySelector("[data-testid=monitor-dot]")).backgroundColor === want; }, token);
      assert(same, `${state}: the dot is not in the ${token} colour`);
      notes.push(`${state}: dot "${label}"`);
    } finally { await view.close(); }
  }
  const phone = await openFresh(ctx, "monitor dot phone", "#/research/scores", { width: 390, patch: { monitor: "degraded" }, ready: "[data-testid=cohort-card]" });
  try {
    await phone.page.locator('[data-slot="mobile-tab-bar"] [data-testid=monitor-dot]').waitFor({ timeout: 8000 });
    assert((await phone.page.locator('[data-slot="mobile-tab-bar"] a', { hasText: "研究" }).locator("[data-testid=monitor-dot]").count()) === 1, "the dot is not on the 研究 tab");
    notes.push("390 tab bar: dot");
  } finally { await phone.close(); }
  const chat = await openFresh(ctx, "monitor dot from chat", "#/chat", { patch: { monitor: "degraded" }, ready: "[data-testid=message]" });
  try {
    await settle(chat.page);
    assert(monitorReads(chat) === 0 && (await chat.page.locator("[data-testid=monitor-dot]").count()) === 0, "the chat page read the monitor or shows a dot");
    await pressNavItem(chat.page, "研究");
    await chat.page.locator('[data-slot="sidebar"] [data-testid=monitor-dot]').waitFor({ timeout: 8000 });
    assert(monitorReads(chat) === 1, `${monitorReads(chat)} reads after entering the research area`);
    notes.push("chat: no read, 研究 reads once");
  } finally { await chat.close(); }
  return notes.join("; ");
}

/**
 * P9.1: the positive control of the `*-no-legacy` checks.  No product page is inside the old-UI marker any more, so a control that opens "a page that is still old" is gone;
 * instead a probe is put into the page itself (the marker attribute, one old class, a native <select>, a text of 11px), read with the SAME counting function the check uses,
 * taken out again, and read once more.  A selector that is broken (and would read 0 everywhere) fails here, whichever page is clean.
 */
async function probeControl(page, count, oldClass) {
  const before = await count(page);
  await page.evaluate((cls) => {
    const probe = document.createElement("div");
    probe.setAttribute("data-legacy", ""); probe.setAttribute("data-smoke-injected", ""); if (cls) probe.className = cls;
    probe.innerHTML = '<select aria-hidden="true"><option>x</option></select><span style="font-size:11px">probe</span>';
    (document.querySelector("main") ?? document.body).appendChild(probe);
  }, oldClass);
  const withProbe = await count(page);
  await page.evaluate(() => document.querySelectorAll("[data-smoke-injected]").forEach((el) => el.remove()));
  const after = await count(page);
  return { before, withProbe, after };
}
/** What the control must read (relative to what the page already read, so the control says nothing about the page's own cleanliness): each counter the check keeps goes up with the probe in and is back where it was once the probe is out (`keys` = the counters this check has). */
function assertProbe(name, keys, { before, withProbe, after }) {
  const blind = keys.filter((key) => !(withProbe[key] > before[key])), stuck = keys.filter((key) => after[key] !== before[key]);
  assert(!blind.length, `${name}: the control's probe was not counted (${blind.map((key) => `${key} ${JSON.stringify(before[key])} -> ${JSON.stringify(withProbe[key])}`).join(", ")}): the selector is broken, not the pages clean`);
  assert(!stuck.length, `${name}: ${stuck.map((key) => `${key} ${JSON.stringify(before[key])} -> ${JSON.stringify(after[key])}`).join(", ")} once the probe was taken out`);
}

/** The old marker and the old classes: nothing in the research area may carry either (the old classes are what the legacy sheets are keyed on). */
const OLD_MARKS = "main.workspace, .workspace-stack, .v2-desk, .historical-replay-workspace, .v2-notice, .text-button, .empty-watchlist, .primary-action";
const oldMarkCounts = (page) => page.evaluate((selector) => ({ legacy: document.querySelectorAll("[data-legacy]").length, old: document.querySelectorAll(selector).length }), OLD_MARKS);

async function researchNoLegacy(ctx) {
  // Every research-area route has at least one address here (add a row when a research-area route is added): all of them hold no old-UI marker and no old class.
  // Since P7.3 the research area is at 0; the five P6.2 / P6.3 pages and the `latest` redirect page were the temporary exception of opus-p64-ruling.md item 3.
  const clean = [["#/research", "main"], ["#/research/c/AAPL", "[data-testid=company-overview]"], ["#/research/c/AAPL?tab=forecasts", "main"], ["#/research/c/AAPL?tab=materials", "[data-testid=material-row]"],
    ["#/research/scores", "[data-testid=cohort-card]"], ["#/research/replay", "[data-testid=replay-row]"], ["#/research/monitor", "[data-testid=monitor-health]"],
    ["#/research/forecasts", "[data-testid=forecast-home]"], [`#/research/forecasts/${ROOT.aapl}`, "[data-testid=forecast-page]"], [`#/research/judgments/${JUDGMENT.aapl}`, "[data-testid=judgment-card]"],
    ["#/research/evidence?symbol=AAPL", "[data-testid=evidence-page]"], [`#/research/evidence/${VERSION.aapl3}`, "[data-testid=evidence-page]"],
    [`#/research/evidence/${VERSION.aapl3}/uploaded_media/${materialId(3)}`, "[data-testid=evidence-drawer]"], ["#/research/materials", "[data-testid=material-row]"],
    ["#/research/c/AAPL/latest?section=versions", "[data-testid=forecast-page]"]];
  const bad = [];
  const view = await newView(ctx.browser, { width: 1440, theme: "light", label: "research no legacy", unmatched });
  const read = async (hash, ready) => {
    await view.page.goto(`${ctx.server.url}${hash}`, { waitUntil: "load" });
    await view.page.waitForSelector(ready, { state: "visible", timeout: 30000 });
    await settle(view.page);
    return oldMarkCounts(view.page);
  };
  const judge = (hash, got) => {
    if (got.legacy) bad.push(`${hash}: ${got.legacy} data-legacy element(s)`);
    if (got.old) bad.push(`${hash}: ${got.old} old workspace element(s)`);
  };
  const failing = await newView(ctx.browser, { width: 1440, theme: "light", label: "research no legacy (latest, list unreadable)", unmatched, fixtureState: stateWithMaterials({ forecastRootsError: true }) });
  try {
    for (const [hash, ready] of clean) judge(hash, await read(hash, ready));
    // the `latest` redirect page stopped on its error state (the company's forecast list cannot be read)
    const errorHash = "#/research/c/AAPL/latest?section=versions";
    await failing.page.goto(`${ctx.server.url}${errorHash}`, { waitUntil: "load" });
    await failing.page.waitForSelector("[data-testid=latest-error]", { state: "visible", timeout: 30000 });
    await settle(failing.page);
    judge(`${errorHash} (list unreadable)`, await oldMarkCounts(failing.page));
    // the replay page with an EMPTY watchlist (it was drawn with old classes until P9.1, and no address above reaches it)
    const empty = await newView(ctx.browser, { width: 1440, theme: "light", label: "research no legacy (empty watchlist)", unmatched, fixtureState: stateWithQueue([]) });
    try {
      await empty.page.goto(`${ctx.server.url}#/research/replay`, { waitUntil: "load" });
      await empty.page.getByText("关注列表为空", { exact: true }).waitFor({ timeout: 30000 });
      await settle(empty.page);
      judge("#/research/replay (empty watchlist)", await oldMarkCounts(empty.page));
    } finally { await empty.close(); }
    // the positive control (P9.1: injected, since no product page keeps the marker): a probe with the marker and an old class is counted by the same function, and is gone again after
    await view.page.goto(`${ctx.server.url}#/research/materials`, { waitUntil: "load" });
    await view.page.waitForSelector("[data-testid=material-row]", { state: "visible", timeout: 30000 });
    assertProbe("research-no-legacy", ["legacy", "old"], await probeControl(view.page, oldMarkCounts, "workspace-stack"));
  } finally { await failing.close(); await view.close(); }
  assert(!bad.length, bad.join("; "));
  return `${clean.length + 2} research-area addresses (watchlist, company and its tabs, forecast home, one forecast, judgment, the three evidence addresses, materials, 模型成绩, 历史回放, 监控, the latest redirect page opened and stopped on its error, the replay page with an empty watchlist) hold no data-legacy element and no old workspace class; the control (a probe with the marker and an old class, injected into the page) is counted and reads 0 once removed`;
}

// --- P7.1: the portfolio page ------------------------------------------------------------------------------------------------------
// The baseline is what the OLD page (HEAD 476188e) sent and said on the same fixtures (fixtures/portfolio-bodies-baseline.json, recorded before the page was touched).
const PF_BASE = JSON.parse(fs.readFileSync(new URL("./fixtures/portfolio-bodies-baseline.json", import.meta.url), "utf8"));
const PF_TABLE = "[data-testid=portfolio-table]";
const pfWrites = (view) => view.mock.state.portfolio.writes ?? [];
/** The portfolio page on the fake backend; `state` switches (fixtures/portfolio.mjs) go through stateWithPortfolio. */
async function openPortfolio(ctx, label, { width = 1440, theme = "light", motion = false, switches, identity } = {}) {
  const view = await newView(ctx.browser, { width, theme, label, unmatched, motion, ...(identity ? { identity } : {}), ...(switches ? { fixtureState: stateWithPortfolio(switches) } : {}) });
  await view.page.goto(`${ctx.server.url}#/portfolio`, { waitUntil: "load" });
  await view.page.waitForSelector(switches?.empty ? "[data-testid=portfolio-empty]" : PF_TABLE, { timeout: 30000 });
  await settle(view.page);
  return view;
}
/** Fill the record dialog the way a reader would and press 记录 (without waiting for the answer). */
async function fillRecord(page, c) {
  await page.locator("[data-testid=record-kind]").getByText(KIND_LABEL[c.kind], { exact: true }).click();
  const set = async (key, value) => { if (value !== undefined) await page.locator(`[data-testid=record-${key}]`).fill(value); };
  await set("symbol", c.symbol); await set("quantity", c.quantity); await set("price", c.price); await set("fee", c.fee); await set("ratio", c.ratio); await set("amount", c.amount); await set("occurred_on", c.occurred_on); await set("note", c.note);
}
const KIND_LABEL = { buy: "买入", sell: "卖出", opening: "期初持仓", dividend: "分红", split: "拆股", deposit: "入金", withdraw: "出金" };
const pfUntil = async (page, read, want, what) => { const end = Date.now() + 8000; while (Date.now() < end) { if ((await read()) >= want) return; await page.waitForTimeout(50); } throw new Error(`${what}: not reached`); };

/** 记一笔: every kind sends the old body, field for field; every rule the old form had still stops the form with its sentence and sends nothing; the kinds and the fields per kind are the old ones. */
async function portfolioRecordBody(ctx) {
  const done = [];
  for (const [name, base] of Object.entries(PF_BASE.entry)) {
    const view = await openPortfolio(ctx, `record body ${name}`);
    try {
      const { page } = view;
      await page.locator("[data-testid=record-open]").click(); await page.locator("[data-testid=record-dialog]").waitFor();
      await fillRecord(page, base.input);
      await page.locator("[data-testid=record-submit]").click();
      await pfUntil(page, async () => pfWrites(view).length, 1, `${name}: no request`);
      const sent = pfWrites(view);
      assert(sent.length === 1 && sent[0].method === base.method && sent[0].path === base.path, `${name}: sent ${JSON.stringify(sent.map((w) => `${w.method} ${w.path}`))}, the old page sent ${base.method} ${base.path}`);
      assert(sameJson(sent[0].body, base.body), `${name}: body ${JSON.stringify(sent[0].body)} differs from the old ${JSON.stringify(base.body)}`);
      await page.locator("[data-testid=record-dialog]").waitFor({ state: "detached", timeout: 8000 });
      done.push(name);
    } finally { await view.close(); }
  }
  // the rules: each broken one is said in the dialog, the dialog stays, nothing goes out
  const view = await openPortfolio(ctx, "record validation");
  try {
    const { page } = view;
    for (const [name, c] of Object.entries(PF_BASE.entryValidation)) {
      await page.locator("[data-testid=record-open]").click(); await page.locator("[data-testid=record-dialog]").waitFor();
      await fillRecord(page, c.input);
      await page.locator("[data-testid=record-submit]").click();
      await page.locator("[data-testid=record-error]").waitFor({ timeout: 5000 });
      const said = [(await page.locator("[data-testid=record-error]").innerText()).trim()];
      assert(sameJson(said, c.alert), `${name}: said ${JSON.stringify(said)}, the old page said ${JSON.stringify(c.alert)}`);
      assert(pfWrites(view).length === 0, `${name}: a request went out`);
      await page.keyboard.press("Escape"); await page.locator("[data-testid=record-dialog]").waitFor({ state: "detached" });
      // the draft is kept after Esc: reopening shows what was typed, and the old error is gone
      await page.locator("[data-testid=record-open]").click(); await page.locator("[data-testid=record-dialog]").waitFor();
      assert((await page.locator("[data-testid=record-error]").count()) === 0, `${name}: the old error is still up after reopening`);
      await page.keyboard.press("Escape"); await page.locator("[data-testid=record-dialog]").waitFor({ state: "detached" });
      // a new kind starts the form over, as the old one did
      await page.locator("[data-testid=record-open]").click(); await page.locator("[data-testid=record-dialog]").waitFor();
      await page.locator("[data-testid=record-kind]").getByText("买入", { exact: true }).click();
      assert((await page.locator("[data-testid=record-symbol]").inputValue()) === "", `${name}: choosing a kind did not blank the form`);
      await page.keyboard.press("Escape"); await page.locator("[data-testid=record-dialog]").waitFor({ state: "detached" });
    }
    // the kinds, and the fields each shows
    await page.locator("[data-testid=record-open]").click(); await page.locator("[data-testid=record-dialog]").waitFor();
    const kinds = await page.locator("[data-testid=record-kind] input[type=radio]").evaluateAll((els) => els.map((el) => el.value));
    assert(sameJson(kinds, PF_BASE.kinds.map(([v]) => v)), `kinds ${JSON.stringify(kinds)}`);
    for (const [kind, labels] of Object.entries(PF_BASE.fieldsPerKind)) {
      await page.locator("[data-testid=record-kind]").getByText(KIND_LABEL[kind], { exact: true }).click();
      const shown = await page.locator("[data-testid=record-form] label:not([data-option])").evaluateAll((els) => els.map((el) => el.textContent.trim()));
      const want = labels.filter((l) => !l.startsWith("NOTE:") && !l.startsWith("类型"));
      assert(sameJson(shown, want), `${kind}: fields ${JSON.stringify(shown)}, the old form had ${JSON.stringify(want)}`);
      const note = await page.locator("[data-testid=record-opening-note]").count();
      assert(note === (kind === "opening" ? 1 : 0), `${kind}: the 期初持仓 note count is ${note}`);
    }
  } finally { await view.close(); }
  return `${done.length} kinds sent the old bodies (${done.join(", ")}); ${Object.keys(PF_BASE.entryValidation).length} broken rules each stopped with the old sentence and no request; the 7 kinds and their fields are the old ones`;
}

/** 可用资金: 修改 turns the number into an input (the old starting text); Enter and 保存 send the old body; a bad number is said and nothing goes out; Esc and 取消 send nothing and return focus. */
async function portfolioCashEdit(ctx) {
  const done = [];
  for (const [name, c] of Object.entries(PF_BASE.cash)) {
    const view = await openPortfolio(ctx, `cash ${name}`);
    try {
      const { page } = view;
      await page.locator("[data-testid=cash-edit]").click();
      const input = page.locator("[data-testid=cash-input]"); await input.waitFor();
      assert((await input.inputValue()) === c.initial, `${name}: the input starts as ${await input.inputValue()}, the old page started with ${c.initial}`);
      assert(await input.evaluate((el) => el === document.activeElement), `${name}: the input is not focused`);
      await input.fill(c.value);
      // half the cases go by Enter, half by the 保存 key
      if (done.length % 2 === 0) await input.press("Enter"); else await page.locator("[data-testid=cash-save]").click();
      if (c.body) {
        await pfUntil(page, async () => pfWrites(view).length, 1, `${name}: no request`);
        const w = pfWrites(view);
        assert(w.length === 1 && w[0].method === "PUT" && w[0].path === "/portfolio/cash" && sameJson(w[0].body, c.body), `${name}: sent ${JSON.stringify(w)}, the old page sent ${JSON.stringify(c.body)}`);
        await page.locator("[data-testid=cash-form]").waitFor({ state: "detached", timeout: 8000 });
        const shown = (await page.locator("[data-testid=cash-value]").innerText()).trim();
        assert(shown === Number(c.body.available_funds).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 }), `${name}: the tile shows ${shown} after the save`);
      } else {
        await page.locator("[data-testid=cash-problem]").waitFor({ timeout: 5000 });
        assert(sameJson([(await page.locator("[data-testid=cash-problem]").innerText()).trim()], c.alert), `${name}: said ${await page.locator("[data-testid=cash-problem]").innerText()}, the old page said ${JSON.stringify(c.alert)}`);
        assert(pfWrites(view).length === 0, `${name}: a request went out`);
        assert((await input.count()) === 1, `${name}: the editor closed on a bad number`);
      }
      done.push(name);
    } finally { await view.close(); }
  }
  const view = await openPortfolio(ctx, "cash cancel");
  try {
    const { page } = view;
    for (const way of ["Escape", "取消"]) {
      await page.locator("[data-testid=cash-edit]").click();
      await page.locator("[data-testid=cash-input]").fill("999");
      if (way === "Escape") await page.locator("[data-testid=cash-input]").press("Escape"); else await page.getByRole("button", { name: "取消" }).click();
      await page.locator("[data-testid=cash-form]").waitFor({ state: "detached", timeout: 3000 });
      assert((await page.locator("[data-testid=cash-value]").innerText()).trim() === "25,800.00", `${way}: the old number is not back`);
      await page.waitForFunction(() => document.activeElement?.getAttribute("data-testid") === "cash-edit", null, { timeout: 3000 }).catch(() => { throw new Error(`${way}: focus did not go back to 修改`); });
      assert(pfWrites(view).length === 0, `${way}: a request went out`);
    }
    // a refused save is said under the input and the editor stays
    view.mock.control.fail = (method, path) => (method === "PUT" && path.endsWith("/portfolio/cash") ? 500 : 0);
    await page.locator("[data-testid=cash-edit]").click(); await page.locator("[data-testid=cash-input]").fill("1000"); await page.locator("[data-testid=cash-save]").click();
    await page.locator("[data-testid=cash-problem]").waitFor({ timeout: 5000 });
    assert((await page.locator("[data-testid=cash-input]").count()) === 1, "the editor closed on a failed save");
  } finally { await view.close(); }
  return `${done.length} typed values: the old bodies (-100 and 0 go out as before) or the old sentence; Esc and 取消 send nothing and give focus back; a failed save stays in the editor with its message`;
}

/** 我的计划: opening a row and saving sends the old body for every case; a bad price is said and nothing goes out; the draft survives closing the row and another row's save, and is marked 未保存. */
async function portfolioPlanSave(ctx) {
  const done = [];
  for (const [name, c] of Object.entries(PF_BASE.plan)) {
    if (name.startsWith("_")) continue;
    const view = await openPortfolio(ctx, `plan ${name}`);
    try {
      const { page } = view;
      await page.locator("[data-testid=pf-position][data-symbol=AAPL] [data-testid=pf-toggle]").click();
      const plan = page.locator("[data-testid=pf-position][data-symbol=AAPL] [data-testid=pf-plan]"); await plan.waitFor();
      const save = plan.locator("[data-testid=pf-plan-save]");
      assert(await save.isDisabled(), `${name}: 保存计划 is on before any change`);
      const { text, add, stop, target } = c.input;
      if (text !== undefined) await plan.locator("[data-testid=pf-plan-text]").fill(name === "longText" ? "字".repeat(PF_BASE.plan._longTextInput) : text);
      if (add !== undefined) await plan.locator("[data-testid=pf-add_price]").fill(add);
      if (stop !== undefined) await plan.locator("[data-testid=pf-stop_price]").fill(stop);
      if (target !== undefined) await plan.locator("[data-testid=pf-target_price]").fill(target);
      assert(!(await save.isDisabled()), `${name}: 保存计划 is still off after a change`);
      assert((await page.locator("[data-testid=pf-position][data-symbol=AAPL] [data-testid=pf-unsaved]").count()) >= 1, `${name}: no 未保存 mark`);
      await save.click();
      if (c.body) {
        await pfUntil(page, async () => pfWrites(view).length, 1, `${name}: no request`);
        const w = pfWrites(view);
        assert(w.length === 1 && w[0].method === "PUT" && w[0].path === "/portfolio/plans/AAPL" && sameJson(w[0].body, c.body), `${name}: sent ${JSON.stringify(w)}, the old page sent ${JSON.stringify(c.body)}`);
        await page.waitForFunction(() => !document.querySelector("[data-testid=pf-position][data-symbol=AAPL] [data-testid=pf-unsaved]"), null, { timeout: 8000 });
      } else {
        await plan.locator("[data-testid=pf-plan-problem]").waitFor({ timeout: 5000 });
        assert(sameJson([(await plan.locator("[data-testid=pf-plan-problem]").innerText()).trim()], c.alert), `${name}: said ${await plan.locator("[data-testid=pf-plan-problem]").innerText()}, the old page said ${JSON.stringify(c.alert)}`);
        assert(pfWrites(view).length === 0, `${name}: a request went out`);
      }
      done.push(name);
    } finally { await view.close(); }
  }
  // the draft: kept when the row is closed and when another row is opened, marked on the closed row, still there when it opens again; a save of another plan leaves it
  const view = await openPortfolio(ctx, "plan draft");
  try {
    const { page } = view;
    const row = (s) => page.locator(`[data-testid=pf-position][data-symbol=${s}]`);
    await row("NVDA").locator("[data-testid=pf-toggle]").click();
    await row("NVDA").locator("[data-testid=pf-plan-text]").fill("未保存的草稿");
    await row("AAPL").locator("[data-testid=pf-toggle]").click(); // opens AAPL, closes NVDA
    assert((await row("NVDA").locator("[data-testid=pf-panel]").count()) === 0, "two rows are open at once");
    assert((await row("NVDA").locator("[data-testid=pf-unsaved]").count()) === 1, "the closed row is not marked 未保存");
    await row("AAPL").locator("[data-testid=pf-plan-text]").fill("先改 AAPL"); await row("AAPL").locator("[data-testid=pf-plan-save]").click();
    await pfUntil(page, async () => pfWrites(view).length, 1, "AAPL save");
    await row("NVDA").locator("[data-testid=pf-toggle]").click();
    assert((await row("NVDA").locator("[data-testid=pf-plan-text]").inputValue()) === "未保存的草稿", "the draft is gone after another plan's save");
    assert(pfWrites(view).length === 1 && pfWrites(view)[0].path === "/portfolio/plans/AAPL", `writes ${JSON.stringify(pfWrites(view))}`);
    assert((await row("NVDA").locator("[data-testid=pf-unsaved]").count()) >= 1, "NVDA lost its 未保存 mark");
  } finally { await view.close(); }
  return `${done.length} plans (${done.join(", ")}): the old bodies (blank price = null) or the old sentence; the draft is kept per symbol and marked 未保存`;
}

/** 删除一笔记录: the question says the positions and the cash are worked out again; Esc and 取消 send nothing and return focus; a full hold sends one DELETE for that id and the list is read again; from the all-records list and from an open position. */
async function portfolioDeleteRecord(ctx) {
  const view = await openPortfolio(ctx, "delete record", { motion: true });
  try {
    const { page } = view;
    const dialog = page.locator('[data-slot="alert-dialog-content"]');
    const dels = () => view.mock.requests.filter((r) => r.method === "DELETE" && /\/portfolio\/transactions\/[^/]+$/.test(r.path));
    const gets = () => view.mock.requests.filter((r) => r.method === "GET" && r.path.endsWith("/portfolio")).length;
    const trigger = page.locator("[data-testid=portfolio-ledger] [data-testid=record-delete]").first();
    await trigger.evaluate((el) => el.setAttribute("data-probe-trigger", ""));
    const firstId = await page.locator("[data-testid=portfolio-ledger] [data-testid=record-row]").first().getAttribute("data-id");
    const rowsBefore = await page.locator("[data-testid=portfolio-ledger] [data-testid=record-row]").count();
    await trigger.click(); await dialog.waitFor();
    const title = (await dialog.locator('[data-slot="alert-dialog-title"]').innerText()).trim(), description = (await dialog.locator('[data-slot="alert-dialog-description"]').innerText()).trim();
    assert(title === PF_BASE.remove.dialog.title && description === PF_BASE.remove.dialog.description, `the question reads ${title} / ${description}`);
    assert(description.includes("重新计算"), "the question does not say the numbers are worked out again");
    assert(await dialog.locator('[data-slot="hold-button"]').count() === 1, "not a press-and-hold confirmation");
    assert(dels().length === 0, "a request went out before the answer");
    await page.keyboard.press("Escape"); await dialog.waitFor({ state: "detached" });
    await page.waitForFunction(() => document.activeElement?.hasAttribute("data-probe-trigger"), null, { timeout: 3000 }).catch(() => { throw new Error("Esc: focus did not return to the delete key"); });
    await trigger.click(); await dialog.waitFor(); await dialog.getByRole("button", { name: "取消" }).click(); await dialog.waitFor({ state: "detached" });
    assert(dels().length === 0, "取消 sent a request");
    const readsBefore = gets();
    await trigger.click(); await dialog.waitFor();
    await holdPointer(page, dialog.locator('[data-slot="hold-button"]'), 300);
    assert(dels().length === 0 && (await dialog.count()) === 1, "a short press confirmed");
    await holdPointer(page, dialog.locator('[data-slot="hold-button"]'));
    await dialog.waitFor({ state: "detached", timeout: 5000 });
    await pfUntil(page, async () => dels().length, 1, "no DELETE after the hold");
    assert(dels().length === 1 && dels()[0].path.endsWith(`/portfolio/transactions/${firstId}`), `the DELETE was ${JSON.stringify(dels().map((d) => d.path))}, wanted .../${firstId}`);
    await pfUntil(page, async () => gets() - readsBefore, 1, "the ledger was not read again");
    await page.waitForFunction((n) => document.querySelectorAll("[data-testid=portfolio-ledger] [data-testid=record-row]").length === n, rowsBefore - 1, { timeout: 8000 });
    assert((await page.locator(`[data-testid=record-row][data-id="${firstId}"]`).count()) === 0, "the deleted record is still listed");
    // from an open position's own list
    await page.locator("[data-testid=pf-position][data-symbol=AAPL] [data-testid=pf-toggle]").click();
    const own = page.locator("[data-testid=pf-position][data-symbol=AAPL] [data-testid=record-delete]").first();
    const ownId = await page.locator("[data-testid=pf-position][data-symbol=AAPL] [data-testid=record-row]").first().getAttribute("data-id");
    await own.click(); await dialog.waitFor(); await holdPointer(page, dialog.locator('[data-slot="hold-button"]'));
    await dialog.waitFor({ state: "detached", timeout: 5000 });
    await pfUntil(page, async () => dels().length, 2, "no second DELETE");
    assert(dels()[1].path.endsWith(`/portfolio/transactions/${ownId}`), `the second DELETE was ${dels()[1].path}`);
    return `the question is the old one and says 重新计算; Esc / 取消 send nothing and give focus back; a short press does nothing; a hold sends one DELETE for the row's id, the ledger is read again and the row is gone (all-records list and an open position)`;
  } finally { await view.close(); }
}

/** The colour that a token resolves to in the page (so a check compares what is drawn, not a name). */
const tokenColour = (page, token) => page.evaluate((name) => { const probe = document.createElement("i"); probe.style.color = `var(${name})`; document.body.appendChild(probe); const colour = getComputedStyle(probe).color; probe.remove(); return colour; }, token);
const readPnl = (page) => page.evaluate(() => [...document.querySelectorAll("[data-pnl]")].map((el) => {
  const change = el.querySelector("[data-slot=change]"), target = change ?? el.firstElementChild;
  return { dir: el.getAttribute("data-pnl"), text: target.textContent.trim(), arrow: change ? change.querySelectorAll("svg").length : 0, path: change ? [...change.querySelectorAll("svg path")].map((p) => p.getAttribute("d")).join("|") : "", colour: getComputedStyle(target).color, where: el.closest("[data-slot=stat-tile]")?.querySelector("[data-slot=stat-label]")?.textContent ?? el.closest("[data-testid=pf-position]")?.getAttribute("data-symbol") ?? "?" };
}));

/** Every profit-and-loss figure has all three signals (colour, arrow, sign) or none (zero, missing); red-up swaps the two colours and leaves the arrow and the sign alone. */
async function portfolioPnlThreeSignals(ctx) {
  const overrides = { override: { summary: { realized_pnl: "0.00" }, positions: { MSFT: { floating_pnl: "0.00", floating_pnl_pct: "0.00", today_pnl: null } } } };
  const view = await openPortfolio(ctx, "pnl three signals", { switches: overrides });
  try {
    const { page } = view;
    await page.locator("[data-testid=pf-position][data-symbol=MSFT] [data-testid=pf-toggle]").click(); await page.locator("[data-testid=pf-panel]").waitFor();
    const green = await tokenColour(page, "--up"), red = await tokenColour(page, "--down");
    const before = await readPnl(page);
    assert(before.length >= 12, `only ${before.length} figures carry data-pnl`);
    const ups = before.filter((f) => f.dir === "up"), downs = before.filter((f) => f.dir === "down"), flats = before.filter((f) => f.dir === "flat" || f.dir === "none");
    assert(ups.length >= 4 && downs.length >= 3 && flats.length >= 4, `directions: ${ups.length} up, ${downs.length} down, ${flats.length} flat/none`);
    for (const f of ups) assert(/^\+/.test(f.text) && f.arrow === 1 && f.colour === green, `${f.where}: an up figure is ${JSON.stringify(f)} (green ${green})`);
    for (const f of downs) assert(/^-/.test(f.text) && f.arrow === 1 && f.colour === red, `${f.where}: a down figure is ${JSON.stringify(f)} (red ${red})`);
    for (const f of flats) assert(!/^[+-]/.test(f.text) && f.arrow === 0 && f.colour !== green && f.colour !== red, `${f.where}: a flat figure is ${JSON.stringify(f)}`);
    assert(flats.some((f) => f.dir === "flat" && /^0\.00%?$/.test(f.text)) && flats.some((f) => f.dir === "none" && f.text === "—"), `flat figures: ${JSON.stringify(flats.map((f) => f.text))}`);
    // red up: the colours trade places, nothing else moves
    await page.evaluate(() => { try { localStorage.setItem("market-evidence-agent:updown:v1", "red-up"); } catch { /* storage unavailable */ } document.documentElement.dataset.updown = "red-up"; });
    const greenR = await tokenColour(page, "--up"), redR = await tokenColour(page, "--down"); // the names stay: --up is now the red one
    assert(greenR === red && redR === green, `under red-up --up is ${greenR} and --down is ${redR}; they should be ${red} and ${green}`);
    const after = await readPnl(page);
    assert(after.length === before.length, "red-up changed how many figures there are");
    after.forEach((f, i) => {
      const b = before[i];
      assert(f.text === b.text && f.arrow === b.arrow && f.path === b.path && f.dir === b.dir, `${f.where}: the sign or the arrow changed under red-up (${b.text} -> ${f.text})`);
      if (f.dir === "up") assert(f.colour === greenR, `${f.where}: an up figure is ${f.colour} under red-up, wanted the new --up ${greenR}`);
      if (f.dir === "down") assert(f.colour === redR, `${f.where}: a down figure is ${f.colour} under red-up, wanted the new --down ${redR}`);
    });
    return `${before.length} figures: ${ups.length} up (green, arrow up, +), ${downs.length} down (red, arrow down, -), ${flats.length} zero or missing (no colour, arrow or sign); under red-up the colours swap and every sign and arrow stays`;
  } finally { await view.close(); }
}

/** The numbers on the page are what portfolio-items.mjs makes of the server's figures: the six tiles, every cell of every position, the records, and the research lines. */
async function portfolioNumbersMatchLogic(ctx) {
  const state = stateWithPortfolio({});
  const data = portfolioSummary(state);
  const view = await openPortfolio(ctx, "numbers match", { switches: {} });
  try {
    const { page } = view;
    const tile = async (label) => (await page.locator("[data-slot=stat-tile]", { has: page.locator(`[data-slot=stat-label]:text-is("${label}")`) }).locator("[data-slot=stat-value]").innerText()).replace(/\s+/g, " ").trim();
    const want = { 总资产: formatMoney(data.total_assets), 持仓市值: formatMoney(data.positions_value), 浮动盈亏: formatMoney(data.floating_pnl, { signed: true }), 今日盈亏: formatMoney(data.today_pnl, { signed: true }), 已实现盈亏: formatMoney(data.realized_pnl, { signed: true }) };
    for (const [label, text] of Object.entries(want)) assert((await tile(label)) === text, `${label}: the page shows ${await tile(label)}, the logic gives ${text}`);
    const cash = (await page.locator("[data-testid=cash-value]").innerText()).trim();
    assert(cash === formatMoney(data.available_funds), `可用资金 ${cash}`);
    assert((await page.locator("[data-testid=portfolio-price-date]").innerText()).trim() === `行情数据日期 ${data.price_date}`, "the price date line");
    for (const p of data.positions) {
      const cells = await page.locator(`[data-testid=pf-position][data-symbol=${p.symbol}] [role=row]`).first().locator("[role=cell]").evaluateAll((els) => els.map((el) => el.innerText.replace(/\s+/g, " ").trim()));
      const wantCells = [p.symbol, formatShares(p.shares), formatPrice(p.avg_cost), formatPrice(p.diluted_cost), `${formatPrice(p.price)} ${p.price_date}`, formatMoney(p.market_value), formatPercent(p.weight_pct), `${formatMoney(p.floating_pnl, { signed: true })} ${formatPercent(p.floating_pnl_pct, { signed: true })}`];
      // a cell begins with its phone label (hidden on the table): compare the figures at the end
      cells.forEach((text, i) => assert(text.endsWith(wantCells[i]), `${p.symbol} cell ${i}: the page shows "${text}", the logic gives "${wantCells[i]}"`));
    }
    const rows = await page.locator("[data-testid=portfolio-ledger] [data-testid=record-row]").evaluateAll((els) => els.map((el) => [...el.querySelectorAll("[role=cell]")].map((c) => c.innerText.replace(/\s+/g, " ").trim())));
    assert(rows.length === data.transactions.length, `${rows.length} records listed, ${data.transactions.length} held`);
    data.transactions.forEach((tx, i) => {
      const cells = ledgerCells(tx);
      assert(rows[i][0] === tx.occurred_on && rows[i][1] === (tx.symbol || "—") && rows[i][2] === cells.label, `record ${i}: ${JSON.stringify(rows[i])}`);
      for (const piece of [cells.quantity, cells.price].filter(Boolean)) assert(rows[i].some((c) => c === piece), `record ${i}: ${piece} is not in ${JSON.stringify(rows[i])}`);
      if (cells.fee) assert(rows[i].some((c) => c.endsWith(cells.fee)), `record ${i}: the fee ${cells.fee} is missing`);
    });
    // the research lines: the percentages and the model of the logic's own pick
    const forecasts = forecastList(new URLSearchParams("symbols=AAPL,NVDA,TSLA,MSFT&state=open&limit=200"), state).forecasts;
    for (const p of data.positions) {
      const rec = researchRecord(p.symbol, forecasts, JUDGMENTS);
      await page.locator(`[data-testid=pf-position][data-symbol=${p.symbol}] [data-testid=pf-toggle]`).click();
      const panel = page.locator(`[data-testid=pf-position][data-symbol=${p.symbol}] [data-testid=pf-research]`);
      await panel.waitFor();
      if (!rec.forecast && !rec.judgment) { await page.waitForFunction((s) => document.querySelector(`[data-testid=pf-position][data-symbol=${s}] [data-testid=pf-research]`)?.textContent.includes("暂无研究记录"), p.symbol, { timeout: 8000 }); continue; }
      if (rec.forecast) {
        const line = (await panel.locator("[data-testid=pf-research-forecast]").innerText()).replace(/\s+/g, " ");
        const { bearish, neutral, bullish } = rec.forecast.percent;
        assert(line.includes(`下跌 ${bearish}% · 持平 ${neutral}% · 上涨 ${bullish}%`) && line.includes(rec.forecast.targetDate) && line.includes(rec.forecast.model), `${p.symbol}: forecast line "${line}"`);
      } else assert((await panel.locator("[data-testid=pf-research-forecast]").count()) === 0, `${p.symbol}: a forecast line without a forecast`);
      assert((await panel.locator("[data-testid=pf-research-judgment]").count()) === (rec.judgment ? 1 : 0), `${p.symbol}: judgment line count`);
    }
    return `${Object.keys(want).length} tiles, cash, ${data.positions.length} positions x 8 cells, ${rows.length} records and the research lines equal what portfolio-items.mjs / researchRecord give for the same fixture`;
  } finally { await view.close(); }
}

const TRADE_WORDING = [/(?<!不会)(?<!不)下单/, /(?<!不)执行交易/, /(?<!不)立即(买入|卖出|下单|交易)/, /(?<!不)(马上|一键)(买入|卖出)/, /提交订单/, /委托/, /(?<!not )place (an )?order/i, /execute (a )?trade/i, /(buy|sell) now/i, /one-click (buy|sell)/i];
const TRADE_BUTTON = /^(买入|卖出|立即.*|下单.*|buy|sell|buy now|sell now|trade|place order)$/i;
/** The page is a ledger, not a trading screen: no wording that offers or implies an order (the list is TRADE_WORDING above; 不会下单 / "never trades" is allowed, it says the opposite), no button named 买入 / 卖出 (the record kinds are radio choices of what the reader did), and the empty state says the assistant does not trade. */
async function portfolioNoTradeWording(ctx) {
  const bad = [], seen = [];
  const sweep = async (page, where) => {
    const text = await page.evaluate(() => document.body.innerText);
    for (const re of TRADE_WORDING) { const m = re.exec(text); if (m) bad.push(`${where}: "${m[0]}"`); }
    const buttons = await page.evaluate(() => [...document.querySelectorAll("button, [role=button], a")].map((el) => (el.getAttribute("aria-label") || el.textContent || "").trim()));
    for (const b of buttons) if (TRADE_BUTTON.test(b)) bad.push(`${where}: a button named "${b}"`);
    seen.push(where);
  };
  for (const locale of ["zh-CN", "en-US"]) {
    const view = await openPortfolio(ctx, `no trade wording ${locale}`);
    try {
      const { page } = view;
      if (locale === "en-US") { await page.evaluate(() => { localStorage.setItem("market-evidence-agent:locale:v1", "en-US"); }); await page.reload({ waitUntil: "load" }); await page.waitForSelector(PF_TABLE, { timeout: 30000 }); await settle(page); }
      await sweep(page, `${locale} page`);
      await page.locator("[data-testid=pf-position][data-symbol=AAPL] [data-testid=pf-toggle]").click(); await page.locator("[data-testid=pf-research]").waitFor(); await settle(page);
      await sweep(page, `${locale} open row`);
      await page.locator("[data-testid=record-open]").click(); await page.locator("[data-testid=record-dialog]").waitFor();
      for (const kind of Object.keys(KIND_LABEL)) { await page.locator("[data-testid=record-kind] input[type=radio]").evaluateAll((els, k) => els.find((e) => e.value === k).click(), kind); await sweep(page, `${locale} dialog ${kind}`); }
      await page.keyboard.press("Escape");
    } finally { await view.close(); }
  }
  const empty = await openPortfolio(ctx, "no trade wording empty", { switches: { empty: true, cash: "0.00" } });
  try {
    await sweep(empty.page, "empty page");
    const said = await empty.page.locator("[data-testid=portfolio-empty]").innerText();
    assert(/自己记的账/.test(said) && /不会替你交易/.test(said), `the empty state says: ${said.replace(/\s+/g, " ")}`);
  } finally { await empty.close(); }
  assert(!bad.length, bad.join("; "));
  return `${seen.length} screens (both languages, the page, an open row, the dialog in all 7 kinds, the empty state) hold none of ${TRADE_WORDING.length} order phrases and no 买入 / 卖出 button; the empty state says 自己记的账 / 不会替你交易`;
}

/** Only the keyboard: reach a row, open it (Enter), change the plan, save it, close it (Space). */
async function portfolioKeyboard(ctx) {
  const view = await openPortfolio(ctx, "portfolio keyboard");
  try {
    const { page } = view;
    const active = () => page.evaluate(() => { const a = document.activeElement; return a ? { id: a.getAttribute("data-testid"), sym: a.closest("[data-symbol]")?.getAttribute("data-symbol") ?? null, expanded: a.getAttribute("aria-expanded") } : null; });
    const tabTo = async (match, what) => { for (let i = 0; i < 80; i += 1) { await page.keyboard.press("Tab"); const a = await active(); if (a && match(a)) return a; } throw new Error(`Tab never reached ${what}`); };
    await page.locator("[data-testid=portfolio-page]").evaluate(() => { document.activeElement?.blur?.(); });
    await tabTo((a) => a.id === "pf-toggle" && a.sym === "AAPL", "the AAPL row");
    assert((await active()).expanded === "false", "aria-expanded is not false before opening");
    await page.keyboard.press("Enter");
    await page.locator("[data-testid=pf-position][data-symbol=AAPL] [data-testid=pf-panel]").waitFor({ timeout: 5000 });
    assert((await active()).expanded === "true" && (await active()).id === "pf-toggle", "Enter did not open the row (focus stays on its button)");
    await tabTo((a) => a.id === "pf-plan-text", "the plan text");
    await page.keyboard.press("End"); await page.keyboard.type(" 键盘加的一句");
    await tabTo((a) => a.id === "pf-add_price", "the 补仓价"); await page.keyboard.press("Control+a"); await page.keyboard.type("199.5");
    const save = await tabTo((a) => a.id === "pf-plan-save", "保存计划 (it is on after the change)");
    assert(save.id === "pf-plan-save", "not on the save key");
    await page.keyboard.press("Enter");
    await pfUntil(page, async () => pfWrites(view).length, 1, "the keyboard save sent nothing");
    const w = pfWrites(view)[0];
    assert(w.method === "PUT" && w.path === "/portfolio/plans/AAPL" && w.body.plan_text === "回调到 200 附近分批加仓；跌破 185 止损。 键盘加的一句" && w.body.add_price === "199.5" && w.body.stop_price === "185.00" && w.body.target_price === "235.00", `sent ${JSON.stringify(w)}`);
    // back to the row's button, Space closes it
    for (let i = 0; i < 12; i += 1) { await page.keyboard.press("Shift+Tab"); if ((await active()).id === "pf-toggle") break; }
    assert((await active()).id === "pf-toggle", "Shift+Tab did not come back to the row's button");
    await page.keyboard.press("Space");
    await page.locator("[data-testid=pf-position][data-symbol=AAPL] [data-testid=pf-panel]").waitFor({ state: "detached", timeout: 5000 });
    return "Tab reached the AAPL row, Enter opened it (aria-expanded true), Tab reached the plan, the text and a price were typed, Enter on 保存计划 sent the plan, Space closed the row";
  } finally { await view.close(); }
}

/** One position opens at a time; the one disclaimer of the research area is on screen once; its lines link to the forecast and the judgment pages; the model's opinion is labelled. */
async function portfolioResearchArea(ctx) {
  const view = await openPortfolio(ctx, "portfolio research");
  try {
    const { page } = view;
    await page.locator("[data-testid=pf-position][data-symbol=AAPL] [data-testid=pf-toggle]").click();
    await page.locator("[data-testid=pf-research-forecast]").waitFor();
    assert((await page.locator("[data-testid=pf-panel]").count()) === 1, "more than one row is open");
    assert((await page.getByText("概率未经校准，属实验性信息。仅供参考，买不买由你决定。").count()) === 1, "the disclaimer is not on screen exactly once");
    const card = page.locator("[data-testid=pf-research-opinion]");
    assert((await card.locator("[data-slot=opinion-label]").innerText()).includes("模型意见"), "the research area is not labelled 模型意见");
    const hrefs = await card.locator("a").evaluateAll((els) => els.map((el) => el.getAttribute("href")));
    assert(hrefs.length === 2 && /^#\/research\/forecasts\/[^/]+$/.test(hrefs[0]) && /^#\/research\/judgments\/[^/]+$/.test(hrefs[1]), `links ${JSON.stringify(hrefs)}`);
    const colours = await card.locator("[data-testid=pf-research-forecast], [data-testid=pf-research-judgment]").evaluateAll((els) => els.map((el) => getComputedStyle(el).color));
    const [up, down] = [await tokenColour(page, "--up"), await tokenColour(page, "--down")];
    assert(colours.length === 2 && new Set(colours).size === 1 && !colours.includes(up) && !colours.includes(down), `the lines are not one plain colour: ${colours} (up ${up}, down ${down})`);
    await page.locator("[data-testid=pf-position][data-symbol=MSFT] [data-testid=pf-toggle]").click();
    await page.waitForFunction(() => document.querySelector("[data-testid=pf-position][data-symbol=MSFT] [data-testid=pf-research]")?.textContent.includes("暂无研究记录"), null, { timeout: 8000 });
    assert((await page.getByText("概率未经校准").count()) === 0, "the disclaimer shows where there is no probability");
    return "one row open at a time; one disclaimer; 模型意见 label; links to #/research/forecasts/<id> and #/research/judgments/<id>; plain colour; 暂无研究记录 for a symbol with none";
  } finally { await view.close(); }
}

/** The states: the skeleton after 400 ms and not before, the empty state (the ledger is the reader's own), the error bar with 重试 (not "Failed to fetch"), a refresh that fails keeps the numbers, 今日盈亏 says 仅供参考 only when the server says so. */
async function portfolioStates(ctx) {
  const bad = [];
  { // skeleton
    const view = await newView(ctx.browser, { width: 1440, theme: "light", label: "portfolio skeleton", unmatched });
    try {
      view.mock.control.hold = (method, path) => method === "GET" && path.endsWith("/portfolio");
      await view.page.goto(`${ctx.server.url}#/portfolio`, { waitUntil: "load" });
      await view.page.waitForSelector("[data-testid=portfolio-page]", { timeout: 30000 });
      assert((await view.page.locator("[data-testid=portfolio-skeleton]").count()) === 0, "a skeleton showed at once");
      await view.page.locator("[data-testid=portfolio-skeleton]").waitFor({ timeout: 3000 });
      assert((await view.page.locator("[data-testid=portfolio-skeleton] [data-slot=skeleton]").count()) >= 10, "the skeleton has no tiles and rows");
    } finally { await view.close(); }
  }
  { // error and retry; offline wording
    const view = await openPortfolio(ctx, "portfolio error", { switches: { fail: true } }).catch(() => null);
    const v = view ?? await newView(ctx.browser, { width: 1440, theme: "light", label: "portfolio error", unmatched, fixtureState: stateWithPortfolio({ fail: true }) });
    try {
      if (!view) await v.page.goto(`${ctx.server.url}#/portfolio`, { waitUntil: "load" });
      await v.page.locator("[data-testid=portfolio-error] [data-slot=error-bar]").waitFor({ timeout: 20000 });
      v.mock.state.portfolio.fail = false;
      await v.page.getByRole("button", { name: "重试" }).click();
      await v.page.waitForSelector(PF_TABLE, { timeout: 10000 });
    } finally { await v.close(); }
    const off = await newView(ctx.browser, { width: 1440, theme: "light", label: "portfolio offline", unmatched });
    try {
      await off.page.goto(`${ctx.server.url}#/chat`, { waitUntil: "load" }); await off.page.locator("[data-testid=message]").first().waitFor();
      off.mock.control.down = true;
      await off.page.evaluate(() => { location.hash = "#/portfolio"; });
      await off.page.locator("[data-testid=portfolio-error] [data-slot=error-bar]").waitFor({ timeout: 20000 });
      const said = await off.page.locator("[data-testid=portfolio-error]").innerText();
      assert(!/Failed to fetch/i.test(said) && said.includes("连不上后端"), `an unreachable server reads: ${said}`);
    } finally { await off.close(); }
  }
  { // a refresh that fails keeps the numbers on screen
    const view = await openPortfolio(ctx, "portfolio refresh fails");
    try {
      view.mock.control.fail = (method, path) => (method === "GET" && path.endsWith("/portfolio") ? 500 : 0);
      await view.page.locator("[data-testid=cash-edit]").click(); await view.page.locator("[data-testid=cash-input]").fill("26000"); await view.page.locator("[data-testid=cash-save]").click();
      await view.page.locator("[data-slot=error-bar]").first().waitFor({ timeout: 8000 });
      assert((await view.page.locator(PF_TABLE).count()) === 1 && (await view.page.locator("[data-slot=stat-tile]").count()) === 6, "the numbers left the page when the refresh failed");
      assert(pfWrites(view).length === 1, "the write did not go out");
    } finally { await view.close(); }
  }
  { // empty
    const view = await openPortfolio(ctx, "portfolio empty", { switches: { empty: true, cash: "0.00" } });
    try {
      await view.page.locator("[data-testid=portfolio-empty]").getByRole("button", { name: "记第一笔" }).click();
      await view.page.locator("[data-testid=record-dialog]").waitFor();
    } finally { await view.close(); }
  }
  { // 仅供参考
    const quiet = await openPortfolio(ctx, "portfolio reference off");
    const flagged = await openPortfolio(ctx, "portfolio reference on", { switches: { referenceOnly: true } });
    try {
      assert(!(await quiet.page.locator("[data-slot=stat-label]", { hasText: "今日盈亏" }).innerText()).includes("仅供参考"), "仅供参考 shows when the server did not say so");
      assert((await flagged.page.locator("[data-slot=stat-label]", { hasText: "今日盈亏" }).innerText()).trim() === "今日盈亏 · 仅供参考", "仅供参考 is missing from 今日盈亏");
      assert((await flagged.page.locator("[data-testid=portfolio-warning]").count()) === 1, "the server's warning is not shown");
    } finally { await quiet.close(); await flagged.close(); }
  }
  return "skeleton after 400 ms; error bar + 重试 recovers; an unreachable server reads 连不上后端 (not Failed to fetch); a failed refresh keeps the numbers; empty state opens the dialog; 今日盈亏 · 仅供参考 only when flagged, with the server's warning";
}

/** The dialog is one form in a dialog and in a drawer: the draft typed at 1440 is still there at 390 and back (the breakpoint is 640); the page holds no old-UI marker or old class. */
async function portfolioDialogBreakpoint(ctx) {
  const view = await openPortfolio(ctx, "portfolio breakpoint");
  try {
    const { page } = view;
    assert((await page.locator("[data-legacy]").count()) === 0, "the portfolio page is inside the old-UI marker");
    assert((await page.locator("[class*='pf-'], .personal-page, .portfolio-page, .memory-actions").count()) === 0, "an old class of the page is left");
    await page.locator("[data-testid=record-open]").click(); await page.locator("[data-testid=record-dialog]").waitFor();
    await page.locator("[data-testid=record-kind]").getByText("卖出", { exact: true }).click();
    await page.locator("[data-testid=record-symbol]").fill("tsla"); await page.locator("[data-testid=record-quantity]").fill("12"); await page.locator("[data-testid=record-price]").fill("250"); await page.locator("[data-testid=record-note]").fill("跨断点");
    for (const width of [390, 1440, 390]) {
      await page.setViewportSize({ width, height: width === 390 ? 844 : 900 });
      await page.locator("[data-testid=record-dialog]").waitFor();
      const drawer = (await page.locator('[data-slot="drawer-content"]').count()) === 1, dialog = (await page.locator('[data-slot="dialog-content"]').count()) === 1;
      assert(width === 390 ? drawer && !dialog : dialog && !drawer, `at ${width}: drawer ${drawer}, dialog ${dialog}`);
      const got = await page.evaluate(() => ({ s: document.querySelector("[data-testid=record-symbol]").value, q: document.querySelector("[data-testid=record-quantity]").value, p: document.querySelector("[data-testid=record-price]").value, n: document.querySelector("[data-testid=record-note]").value, k: document.querySelector("[data-testid=record-kind] input:checked")?.value }));
      assert(sameJson(got, { s: "tsla", q: "12", p: "250", n: "跨断点", k: "sell" }), `at ${width} the draft is ${JSON.stringify(got)}`);
      // P9.1: the focus stays on the control it was on (the note, the last one typed in), not on the new shell's first field.
      await focusOn(page, "[data-testid=record-note]", `at ${width}: after the swap the focus is not on the note field it was on`, 3000);
    }
    await page.locator("[data-testid=record-submit]").click();
    await pfUntil(page, async () => pfWrites(view).length, 1, "the send from the drawer");
    assert(sameJson(pfWrites(view)[0].body, { kind: "sell", symbol: "TSLA", quantity: "12", price: "250", note: "跨断点" }), `sent ${JSON.stringify(pfWrites(view)[0].body)}`);
    return "dialog at 1440, drawer at 390, dialog again: kind, code, quantity and note survive each crossing; no data-legacy and no old class on the page";
  } finally { await view.close(); }
}

// --- P7.2: the task page ----------------------------------------------------------------------------------------------------------
// The baseline is what the OLD page (HEAD 86ff97b) sent and said on the same fixtures (fixtures/routine-bodies-baseline.json, recorded before the page was touched).
const RT_BASE = JSON.parse(fs.readFileSync(new URL("./fixtures/routine-bodies-baseline.json", import.meta.url), "utf8"));
const RT_CARDS = "[data-testid=tasks-list] [data-testid=task-card]";
const RT_DRAWER = "[data-testid=task-drawer]";
const RT_CONFIRM_READY = '[data-testid=confirm-entry] [data-slot="approval-card"], [data-testid=confirm-empty]';
const rtWrites = (view) => view.mock.state.routines.writes ?? [];
const rtBotName = (id) => ({ [BOT.finbot]: "FinBot", [BOT.newsbot]: "NewsBot", [BOT.applebot]: "AppleBot", [BOT.reportbot]: "ReportBot", [BOT.teslabot]: "TeslaBot" })[id];
/** The body the old page sent for a write (a string, as it went out), found by its method and path in a baseline's `sent` list. */
const rtOldBody = (sent, method, re) => sent.find((r) => r.method === method && re.test(r.path))?.body ?? null;
/** What the page sent, as the fake backend kept it, as the same compact string. */
const rtBody = (write) => (write.body === null ? null : JSON.stringify(write.body));
async function openRoutines(ctx, label, { tab = "tasks", width = 1440, theme = "light", state, motion = false, hash, ready } = {}) {
  const view = await newView(ctx.browser, { width, theme, label, unmatched, motion, ...(state ? { fixtureState: state } : {}) });
  await view.page.goto(`${ctx.server.url}${hash ?? `#/routines?tab=${tab}`}`, { waitUntil: "load" });
  await view.page.waitForSelector(ready ?? (tab === "tasks" ? RT_CARDS : tab === "runs" ? "[data-testid=runs-pane] [data-slot=timeline-item]" : RT_CONFIRM_READY), { state: "visible", timeout: 30000 });
  await settle(view.page);
  return view;
}
const rtWritesAfter = async (view, count, what) => { const end = Date.now() + 8000; while (rtWrites(view).length < count && Date.now() < end) await view.page.waitForTimeout(60); if (rtWrites(view).length < count) throw new Error(`${what}: no request went out`); return rtWrites(view); };
async function rtGo(page, section) { await page.locator(`${RT_DRAWER} [data-step-button=${section}]`).click(); await page.locator(`[data-testid=task-section-${section}]`).waitFor({ timeout: 5000 }); }
/** Choose in one of the two comboboxes (the bot, the time zone): open it, search, press the item. */
async function rtCombo(page, button, search, itemText) {
  await page.locator(button).click();
  await page.locator("[cmdk-input]").fill(search);
  await page.locator("[cmdk-item]", { hasText: itemText }).first().click();
  await page.locator("[cmdk-item]").first().waitFor({ state: "detached", timeout: 5000 });
}
async function rtCheck(page, selector, on) { const box = page.locator(selector); if ((await box.getAttribute("data-state")) === (on ? "checked" : "unchecked")) return; await box.click(); }
/** Fill the drawer the way the old form was filled (the baseline's `input`: the old labels), section by section, price lines as rows. */
async function rtFill(page, c, rows = []) {
  const d = page.locator(RT_DRAWER);
  await rtGo(page, "basics");
  if (c.bot) await rtCombo(page, "#task-bot", rtBotName(c.bot), rtBotName(c.bot));
  if (c.name !== undefined) await d.locator("#task-name").fill(c.name);
  if (c.kind) await d.locator(`[data-testid=task-kind] [data-option=${c.kind}]`).click();
  await rtGo(page, "time");
  if (c.schedule) await d.locator(`[data-testid=task-schedule] [data-option=${c.schedule}]`).click();
  if (c.every !== undefined) await d.locator("#task-every").fill(c.every);
  if (c.unit) await d.locator(`[data-testid=task-unit] [data-option=${c.unit}]`).click();
  if (c.time) await d.locator("#task-time").fill(c.time);
  if (c.tz) await rtCombo(page, "#task-timezone", c.tz, c.tz.replaceAll("_", " "));
  if (c.count) await d.locator(`[data-testid=task-count] [data-option=${c.count}]`).click();
  if (c.runs !== undefined) await d.locator("#task-runs").fill(c.runs);
  await rtGo(page, "scope");
  if (c.scope) await d.locator(`[data-testid=task-scope] [data-option=${c.scope}]`).click();
  if (c.symbols) { await d.locator("#task-symbols").fill(c.symbols); await d.locator("#task-symbols").press("Enter"); }
  await rtGo(page, "content");
  if (c.instruction !== undefined && c.kind !== "alerts") await d.locator("#task-instruction").fill(c.instruction);
  if (c.skill && c.kind !== "alerts") { await d.locator("#task-skill").click(); await page.getByRole("option", { name: c.skill === RT_BASE.load.skillOptions[1][0] ? RT_BASE.load.skillOptions[1][1] : RT_BASE.load.skillOptions[2][1] }).click(); }
  if (c.kind === "alerts") {
    if (c.filings !== undefined) await rtCheck(page, "#task-filings", c.filings);
    if (c.news !== undefined) await rtCheck(page, "#task-news", c.news);
    if (c.telegram !== undefined) await rtCheck(page, "#task-telegram", c.telegram);
    await rtRows(page, rows);
  }
}
async function rtRows(page, rows) {
  const d = page.locator(RT_DRAWER);
  for (let i = 0; i < rows.length; i++) await d.locator("[data-testid=price-add]").click();
  const list = d.locator("[data-testid=price-row]");
  const have = (await list.count()) - rows.length;
  for (const [i, [symbol, side, price]] of rows.entries()) {
    await list.nth(have + i).locator("[data-field=symbol]").fill(symbol);
    await list.nth(have + i).locator(`[data-option=${side}]`).click();
    await list.nth(have + i).locator("[data-field=price]").fill(price);
  }
}
/** The price lines of the old cases that had some, as the rows a reader would write for the text they typed. */
const RT_ROWS = {
  alertPrice3: [["NVDA", "above", "150"], ["AAPL", "below", "180"], ["tsla", "above", "200.5"]],
  alertPriceSpaces: [["NVDA", "above", "150"], ["AAPL", "below", "180"]],
  alertBothSides: [["NVDA", "above", "150"], ["NVDA", "below", "120"]],
  alertEvery: [["AAPL", "below", "180"]],
};
async function rtNewTask(view) { await view.page.locator("[data-testid=task-new]").first().click(); await view.page.locator(RT_DRAWER).waitFor({ timeout: 10000 }); }
async function rtSave(view) { await view.page.locator("[data-testid=task-submit]").click(); }
async function rtEdit(page, name) {
  const card = page.locator(RT_CARDS, { hasText: name }).first();
  await card.locator("[data-testid=task-menu]").click();
  await page.locator("[data-testid=task-edit]").click();
  await page.locator(RT_DRAWER).waitFor({ timeout: 10000 });
}
/** Run the old new-task cases through the drawer: the body that went out is the old body, character for character. */
async function rtCreateCases(ctx, names, label) {
  const done = [];
  for (const name of names) {
    const old = RT_BASE.create[name];
    const view = await openRoutines(ctx, `${label} ${name}`);
    try {
      await rtNewTask(view);
      await rtFill(view.page, old.input, RT_ROWS[name] ?? []);
      await rtSave(view);
      const writes = await rtWritesAfter(view, 1, name);
      const want = rtOldBody(old.sent, "POST", /\/tasks$/);
      assert(writes.length === 1 && writes[0].method === "POST" && writes[0].path === "/tasks", `${name}: sent ${JSON.stringify(writes.map((w) => `${w.method} ${w.path}`))}`);
      assert(rtBody(writes[0]) === want, `${name}: body\n  ${rtBody(writes[0])}\n  differs from the old one\n  ${want}`);
      await view.page.locator(RT_DRAWER).waitFor({ state: "detached", timeout: 8000 });
      await view.page.locator(RT_CARDS, { hasText: old.input.name?.trim() ?? "研究队列简报" }).first().waitFor({ timeout: 8000 });
      done.push(name);
    } finally { await view.close(); }
  }
  return done;
}
const rtBrief = ["briefDefault", "briefEverything", "briefHourly", "briefDaily", "briefSymbolsDaily"];
const rtAlert = ["alertPlain", "alertPrice3", "alertPriceSpaces", "alertBothSides", "alertEvery"];

async function routinesCreateBrief(ctx) {
  const done = await rtCreateCases(ctx, rtBrief, "create brief");
  return `${done.length} new brief tasks (${done.join(", ")}) sent the old body character for character, the drawer closed and the card is in the list`;
}
async function routinesCreateAlert(ctx) {
  const done = await rtCreateCases(ctx, rtAlert, "create alert");
  return `${done.length} new alert tasks (${done.join(", ")}) sent the old body character for character, price lines made of rows, the drawer closed and the card is in the list`;
}

async function routinesPricelineFormat(ctx) {
  const notes = [];
  // 1. the rows say what the old text said: the price_lines of the body are the old ones, as the compact JSON the server reads
  for (const name of ["alertPrice3", "alertPriceSpaces", "alertBothSides", "alertEvery"]) {
    const old = JSON.parse(rtOldBody(RT_BASE.create[name].sent, "POST", /\/tasks$/)).config.price_lines;
    const view = await openRoutines(ctx, `priceline ${name}`);
    try {
      await rtNewTask(view); await rtFill(view.page, RT_BASE.create[name].input, RT_ROWS[name]); await rtSave(view);
      const [write] = await rtWritesAfter(view, 1, name);
      assert(JSON.stringify(write.body.config.price_lines) === JSON.stringify(old), `${name}: price_lines ${JSON.stringify(write.body.config.price_lines)}, the old text gave ${JSON.stringify(old)}`);
      notes.push(name);
    } finally { await view.close(); }
  }
  // 2. an existing task saved with its price lines untouched sends them as they were stored (a line with both sides: the two lines the old form made of it)
  for (const [name, stored] of [["价格线提醒", '[{"symbol":"NVDA","above":140},{"symbol":"AAPL","below":190}]'], ["NVDA 上下沿提醒", '[{"symbol":"NVDA","above":150},{"symbol":"NVDA","below":120.5}]']]) {
    const view = await openRoutines(ctx, `priceline keep ${name}`, { state: stateWithRoutines() });
    try {
      await rtEdit(view.page, name); await rtGo(view.page, "content");
      assert((await view.page.locator("[data-testid=price-row]").count()) === JSON.parse(stored).length, `${name}: the rows are not the stored lines`);
      await rtSave(view);
      const [write] = await rtWritesAfter(view, 1, name);
      assert(JSON.stringify(write.body.config.price_lines) === stored, `${name}: saved ${JSON.stringify(write.body.config.price_lines)}, stored ${stored}`);
      assert(rtBody(write) === rtOldBody(RT_BASE.edit[name].sent, "PATCH", /\/tasks\//), `${name}: the whole body differs from the old form's`);
    } finally { await view.close(); }
  }
  // 3. a row that is wrong is said at the row and stops the save; nothing goes out
  const view = await openRoutines(ctx, "priceline rules");
  try {
    await rtNewTask(view);
    const page = view.page;
    await rtFill(page, { kind: "alerts", name: "规则" }, [["NVDA", "above", "abc"], ["1A", "above", "5"], ["AAPL", "below", ""], ["", "above", "5"]]);
    await rtSave(view);
    await page.locator("[data-testid=price-row-message]").first().waitFor({ timeout: 5000 });
    const said = await page.locator("[data-testid=price-row-message]").allInnerTexts();
    assert(said.length === 4, `${said.length} rows said what is wrong, 4 are wrong: ${JSON.stringify(said)}`);
    assert(said[0].includes("价格要写成数字") && said[1].includes("代码要以字母开头") && said[2].includes("代码和价格都要填") && said[3].includes("代码和价格都要填"), `the sentences: ${JSON.stringify(said)}`);
    assert(rtWrites(view).length === 0, "a request went out with a wrong price line");
    // fixing them one by one: the sentence goes with the fault
    const rows = page.locator("[data-testid=price-row]");
    await rows.nth(0).locator("[data-field=price]").fill("150");
    await rows.nth(1).locator("[data-field=symbol]").fill("MSFT");
    await rows.nth(2).locator("[data-field=price]").fill("180");
    await rows.nth(3).locator("[data-testid=price-remove]").click();
    await page.waitForFunction(() => document.querySelectorAll("[data-testid=price-row-message]").length === 0, null, { timeout: 5000 });
    await rtSave(view);
    const [write] = await rtWritesAfter(view, 1, "fixed rows");
    assert(JSON.stringify(write.body.config.price_lines) === '[{"symbol":"NVDA","above":150},{"symbol":"MSFT","above":5},{"symbol":"AAPL","below":180}]', `the fixed rows sent ${JSON.stringify(write.body.config.price_lines)}`);
    notes.push("4 wrong rows each said, the save held, fixed rows sent");
  } finally { await view.close(); }
  // 4. a task whose price line is an old free text: the parts it can read become rows, the part it cannot stays as written and is said at once; the save waits; it is never dropped
  const legacy = await openRoutines(ctx, "priceline legacy", { state: stateWithRoutines() });
  try {
    const page = legacy.page;
    await rtEdit(page, "旧式价格线"); await rtGo(page, "content");
    const rows = page.locator("[data-testid=price-row]");
    assert((await rows.count()) === 3, `the old text became ${await rows.count()} rows, not 3`);
    assert((await rows.nth(0).locator("[data-field=symbol]").inputValue()) === "NVDA" && (await rows.nth(0).locator("[data-field=price]").inputValue()) === "150.5", "the first part (nvda > 150.5) is not the row NVDA 高于 150.5");
    assert((await rows.nth(1).locator("[data-field=price]").inputValue()) === "180", "the second part (AAPL<180) is not a row");
    const raw = page.locator('[data-testid=price-row][data-problem=raw]');
    assert((await raw.count()) === 1 && (await raw.locator("[data-field=raw]").inputValue()) === "腾讯>300", "the part that is not a line is not kept as written");
    assert((await raw.locator("[data-testid=price-row-message]").innerText()).includes("这一行读不出代码和价格"), "the unreadable part is not said at once");
    await rtSave(legacy);
    await page.locator("[data-testid=task-problems]").waitFor({ timeout: 5000 });
    assert(rtWrites(legacy).length === 0, "an old task with an unreadable price line was saved (it would lose that line)");
    // written as a line by the reader: it becomes a row and goes out
    await raw.locator("[data-field=raw]").fill("TCEHY > 300");
    await page.waitForFunction(() => document.querySelectorAll("[data-testid=price-row][data-problem=raw]").length === 0, null, { timeout: 5000 });
    await rtSave(legacy);
    const [write] = await rtWritesAfter(legacy, 1, "legacy fixed");
    assert(JSON.stringify(write.body.config.price_lines) === '[{"symbol":"NVDA","above":150.5},{"symbol":"AAPL","below":180},{"symbol":"TCEHY","above":300}]', `saved ${JSON.stringify(write.body.config.price_lines)}`);
    notes.push("legacy text: 2 rows + 1 kept as written, said, save held, rewritten and sent (the old form sent [] and lost all three)");
  } finally { await legacy.close(); }
  const legacy2 = await openRoutines(ctx, "priceline legacy delete", { state: stateWithRoutines() });
  try {
    const page = legacy2.page;
    await rtEdit(page, "旧式价格线"); await rtGo(page, "content");
    await page.locator('[data-testid=price-row][data-problem=raw] [data-testid=price-remove]').click();
    await rtSave(legacy2);
    const [write] = await rtWritesAfter(legacy2, 1, "legacy delete");
    assert(JSON.stringify(write.body.config.price_lines) === '[{"symbol":"NVDA","above":150.5},{"symbol":"AAPL","below":180}]', `saved ${JSON.stringify(write.body.config.price_lines)}`);
    notes.push("the unreadable row deleted: the other two sent");
  } finally { await legacy2.close(); }
  return `price_lines of the rows = the old text's, character for character (${notes.join("; ")})`;
}

async function routinesEditRoundtrip(ctx) {
  const state = () => stateWithRoutines();
  const names = ["盘前新闻速览", "AAPL 财报跟踪", "价格线提醒", "周日组合复盘", "旧的盘后提醒", "NVDA 上下沿提醒", "悉尼开盘简报"];
  const done = [];
  for (const name of names) {
    const view = await openRoutines(ctx, `roundtrip ${name}`, { state: state() });
    try {
      const page = view.page;
      const task = view.mock.state.tasks.find((t) => t.name === name);
      await rtEdit(page, name);
      // what the drawer shows is the task
      await rtGo(page, "basics");
      assert((await page.locator("#task-name").inputValue()) === task.name, `${name}: the name field holds ${await page.locator("#task-name").inputValue()}`);
      assert((await page.locator("#task-bot").innerText()).includes(rtBotName(task.bot_id)), `${name}: the bot is not ${rtBotName(task.bot_id)}`);
      assert((await page.locator(`[data-testid=task-kind] input:checked`).getAttribute("value")) === task.kind, `${name}: kind`);
      await rtGo(page, "time");
      assert((await page.locator(`[data-testid=task-schedule] input:checked`).getAttribute("value")) === task.schedule_kind, `${name}: schedule`);
      assert((await page.locator("#task-time").inputValue()) === task.schedule_time, `${name}: time`);
      assert((await page.locator("#task-timezone").innerText()).includes(task.timezone.replaceAll("_", " ")), `${name}: the time zone button says ${await page.locator("#task-timezone").innerText()}, the task has ${task.timezone}`);
      await rtSave(view);
      const [write] = await rtWritesAfter(view, 1, name);
      assert(write.method === "PATCH" && write.path === `/tasks/${task.id}`, `${name}: ${write.method} ${write.path}`);
      assert(rtBody(write) === rtOldBody(RT_BASE.edit[name].sent, "PATCH", /\/tasks\//), `${name}: body\n  ${rtBody(write)}\n  differs from the old form's\n  ${rtOldBody(RT_BASE.edit[name].sent, "PATCH", /\/tasks\//)}`);
      // equivalent to the task as stored (the fields the form owns)
      const b = write.body;
      assert(b.timezone === task.timezone && b.schedule_time === task.schedule_time && b.schedule_kind === task.schedule_kind && b.name === task.name && b.kind === task.kind && b.bot_id === task.bot_id, `${name}: a stored field changed`);
      assert(JSON.stringify(b.config.price_lines ?? null) === JSON.stringify(task.kind === "alerts" ? task.config.price_lines : null), `${name}: price lines changed`);
      done.push(name);
    } finally { await view.close(); }
  }
  // the one change the old form made too: rename and re-zone
  const view = await openRoutines(ctx, "roundtrip changed", { state: state() });
  try {
    await rtEdit(view.page, "悉尼开盘简报");
    await view.page.locator("#task-name").fill("悉尼开盘简报 2");
    await rtGo(view.page, "time"); await rtCombo(view.page, "#task-timezone", "Sydney", "Australia/Sydney");
    await rtSave(view);
    const [write] = await rtWritesAfter(view, 1, "changed");
    assert(rtBody(write) === rtOldBody(RT_BASE.edit._changed.sent, "PATCH", /\/tasks\//), `the changed body differs: ${rtBody(write)}`);
  } finally { await view.close(); }
  return `${done.length} tasks opened and saved untouched sent the old form's body and equal their stored fields (${done.join(", ")}); a rename + new zone sent the old changed body`;
}

async function routinesTimezoneKept(ctx) {
  const notes = [];
  // a zone that is in the browser's list is found in the list; one that is not (an alias the server accepts) is shown, offered under 已保存的值 and kept
  const state = stateWithRoutines();
  const alias = state.tasks.find((t) => t.name === "悉尼开盘简报");
  const view = await openRoutines(ctx, "timezone kept", { state });
  try {
    const page = view.page;
    const candidates = ["US/Eastern", "US/Pacific", "Asia/Calcutta", "Australia/ACT"];
    const absent = await page.evaluate((list) => list.find((z) => !Intl.supportedValuesOf("timeZone").includes(z)) ?? null, candidates);
    assert(absent, "every candidate alias is in this browser's list: pick another one for the check");
    alias.timezone = absent;
    await page.reload({ waitUntil: "load" }); await page.locator(RT_CARDS).first().waitFor({ timeout: 15000 });
    assert((await page.locator(RT_CARDS, { hasText: "悉尼开盘简报" }).first().innerText()).includes(absent), `the card does not show ${absent}`);
    await rtEdit(page, "悉尼开盘简报"); await rtGo(page, "time");
    assert((await page.locator("#task-timezone").innerText()).includes(absent), `the drawer shows ${await page.locator("#task-timezone").innerText()}, not ${absent}`);
    await page.locator("#task-timezone").click();
    const group = page.locator("[cmdk-group]", { hasText: "已保存的值" });
    assert((await group.locator("[cmdk-item]", { hasText: absent }).count()) === 1, `${absent} is not offered under 已保存的值`);
    await page.keyboard.press("Escape");
    await rtSave(view);
    const [write] = await rtWritesAfter(view, 1, "kept");
    assert(write.body.timezone === absent, `saved ${write.body.timezone}, the task had ${absent}`);
    notes.push(`${absent} shown on the card and in the drawer, listed under 已保存的值, saved unchanged`);
  } finally { await view.close(); }
  // the usual ones are on top, the rest follow, the search finds by any part
  const second = await openRoutines(ctx, "timezone list");
  try {
    const page = second.page;
    await rtNewTask(second); await rtGo(page, "time");
    await page.locator("#task-timezone").click();
    const heads = await page.locator("[cmdk-group-heading]").allInnerTexts();
    assert(heads[0] === "常用时区" && heads.includes("全部时区"), `the groups are ${JSON.stringify(heads)}`);
    const first = await page.locator("[cmdk-group]").first().locator("[cmdk-item]").evaluateAll((els) => els.map((e) => e.textContent.trim()));
    assert(first[0] === "Asia/Shanghai" && first.includes("UTC") && first.includes("America/New York"), `the usual zones: ${JSON.stringify(first)}`);
    const total = await page.locator("[cmdk-item]").count();
    assert(total > 100, `only ${total} zones are offered`);
    await page.locator("[cmdk-input]").fill("tokyo");
    assert((await page.locator("[cmdk-item]").first().innerText()).includes("Asia/Tokyo") && (await page.locator("[cmdk-item]").count()) < 6, `the search for tokyo finds ${await page.locator("[cmdk-item]").count()} zones, the first is ${await page.locator("[cmdk-item]").first().innerText()}`);
    await page.keyboard.press("Escape");
    // the submitted value is an IANA name, as before
    await rtFill(page, { name: "时区试验", tz: "Europe/Paris" });
    await rtSave(second);
    const [write] = await rtWritesAfter(second, 1, "zone");
    assert(write.body.timezone === "Europe/Paris", `sent ${write.body.timezone}`);
    notes.push(`${total} zones, the usual ones first, search by any part, the sent value is the IANA name`);
  } finally { await second.close(); }
  return notes.join("; ");
}

async function routinesToggle(ctx) {
  const notes = [];
  for (const [name, label, enabled] of [["盘前新闻速览", "暂停", false], ["旧的盘后提醒", "启用", true]]) {
    const view = await openRoutines(ctx, `toggle ${label}`);
    try {
      const page = view.page;
      const card = page.locator(RT_CARDS, { hasText: name }).first();
      const sw = card.locator("[data-testid=task-switch]");
      assert((await sw.getAttribute("aria-checked")) === String(!enabled), `${name}: the switch does not start ${!enabled ? "on" : "off"}`);
      assert((await sw.getAttribute("aria-label")).startsWith(label), `${name}: the switch is named ${await sw.getAttribute("aria-label")}`);
      await sw.click();
      const [write] = await rtWritesAfter(view, 1, name);
      const old = RT_BASE.toggle[`${name}:${label}`].sent[0];
      assert(write.method === "PATCH" && write.path.endsWith(old.path.replace("/agent-chat", "")) && rtBody(write) === old.body, `${name}: sent ${write.method} ${write.path} ${rtBody(write)}, the old one sent ${old.method} ${old.path} ${old.body}`);
      await page.waitForFunction(([n, on]) => [...document.querySelectorAll("[data-testid=task-card]")].find((c) => c.textContent.includes(n))?.querySelector("[data-testid=task-switch]").getAttribute("aria-checked") === String(on), [name, enabled], { timeout: 8000 });
      // the badge follows the switch as it is shown (not only the server's later answer), and is still right after the lists are read again
      for (let round = 0; round < 2; round++) {
        const paused = await card.getByText("已暂停", { exact: true }).count();
        assert(paused === (enabled ? 0 : 1), `${name}: the 已暂停 badge count is ${paused}${round ? " after the lists were read again" : ""}`);
        await page.waitForFunction(([n]) => { const c = [...document.querySelectorAll("[data-testid=task-card]")].find((x) => x.textContent.includes(n)); return c && !c.querySelector("[data-testid=task-switch]").disabled; }, [name], { timeout: 8000 });
      }
      notes.push(`${label}: ${old.body}`);
    } finally { await view.close(); }
  }
  // a failed save puts the switch back and says so
  const view = await openRoutines(ctx, "toggle fails");
  try {
    const page = view.page;
    view.mock.control.fail = (method, path) => (method === "PATCH" && /\/tasks\//.test(path) ? 500 : 0);
    const sw = page.locator(RT_CARDS, { hasText: "盘前新闻速览" }).first().locator("[data-testid=task-switch]");
    await sw.click();
    await page.locator("[data-sonner-toast]").first().waitFor({ timeout: 8000 });
    await page.waitForFunction(() => document.querySelector("[data-testid=task-card] [data-testid=task-switch]").getAttribute("aria-checked") === "true", null, { timeout: 8000 });
    assert(((await page.locator("[data-sonner-toast]").first().innerText()).trim()).length > 0, "the toast is empty");
    notes.push("a failed save: the switch is back on and a toast says so");
  } finally { await view.close(); }
  return notes.join("; ");
}

async function routinesDelete(ctx) {
  const view = await openRoutines(ctx, "delete", { motion: true });
  try {
    const page = view.page;
    const card = page.locator(RT_CARDS, { hasText: "AAPL 财报跟踪" }).first();
    const menu = card.locator("[data-testid=task-menu]");
    await menu.click(); await page.locator("[data-testid=task-delete]").click();
    const dlg = page.locator('[data-slot="alert-dialog-content"]'); await dlg.waitFor({ timeout: 5000 });
    const dialog = { title: (await dlg.locator('[data-slot="alert-dialog-title"]').innerText()).trim(), description: (await dlg.locator('[data-slot="alert-dialog-description"]').innerText()).trim(), buttons: await dlg.locator("button").allInnerTexts() };
    assert(JSON.stringify(dialog.title) === JSON.stringify(RT_BASE.del.dialog.title) && JSON.stringify(dialog.description) === JSON.stringify(RT_BASE.del.dialog.description), `the question is ${JSON.stringify(dialog)}, the old one ${JSON.stringify(RT_BASE.del.dialog)}`);
    assert(JSON.stringify(dialog.buttons) === JSON.stringify(RT_BASE.del.dialog.buttons), `the buttons are ${JSON.stringify(dialog.buttons)}`);
    await page.keyboard.press("Escape"); await dlg.waitFor({ state: "detached", timeout: 5000 });
    assert(rtWrites(view).length === 0, "Esc sent a request");
    await page.waitForFunction(() => document.activeElement?.getAttribute("data-testid") === "task-menu", null, { timeout: 3000 }).catch(() => { throw new Error("the focus did not return to the card's 「…」 button after Esc"); });
    await menu.click(); await page.locator("[data-testid=task-delete]").click(); await dlg.waitFor({ timeout: 5000 });
    await holdPointer(page, dlg.locator('[data-slot="hold-button"]'), 300);
    assert((await dlg.count()) === 1 && rtWrites(view).length === 0, "a short press deleted the task");
    await holdPointer(page, dlg.locator('[data-slot="hold-button"]'));
    await dlg.waitFor({ state: "detached", timeout: 5000 });
    const [write] = await rtWritesAfter(view, 1, "delete");
    const old = RT_BASE.del.sent[0];
    assert(write.method === "DELETE" && old.method === "DELETE" && write.path === old.path.replace("/agent-chat", ""), `sent ${write.method} ${write.path}, the old one ${old.method} ${old.path}`);
    await page.waitForFunction(() => ![...document.querySelectorAll("[data-testid=task-card]")].some((c) => c.textContent.includes("AAPL 财报跟踪")), null, { timeout: 8000 });
    return "the question is the old one (title, words, 取消 / 删除); Esc sends nothing and the focus returns to 「…」; a short press does nothing; a full hold sends one DELETE of the old path; the card is gone";
  } finally { await view.close(); }
}

const rtBadge = (page) => page.locator('[data-slot="sidebar"] a[href="#/routines"]').locator("xpath=..").locator("[data-count]");
const rtBadgeNumber = async (page) => { const badge = rtBadge(page); return (await badge.count()) ? Number((await badge.innerText()).trim()) : 0; };
const rtTabNumber = async (page) => { const n = page.locator("[data-testid=tab-confirm-count]"); return (await n.count()) ? Number((await n.innerText()).trim()) : 0; };
const rtLiveCards = (page) => page.locator('[data-testid=confirm-entry][data-phase=live] [data-slot="approval-card"][data-state="active"]').count();
async function rtNumbers(page, want, what) {
  const end = Date.now() + 10000;
  let got;
  for (;;) {
    got = [await rtBadgeNumber(page), await rtTabNumber(page), await rtLiveCards(page)];
    if (got.every((n) => n === want)) return got;
    if (Date.now() > end) throw new Error(`${what}: sidebar ${got[0]}, tab ${got[1]}, live cards ${got[2]}; expected all ${want}`);
    await page.waitForTimeout(80);
  }
}
const rtEntry = (page, text) => page.locator("[data-testid=confirm-entry]", { hasText: text }).first();
async function rtMore(page, entry, item) { await entry.getByRole("button", { name: "更多操作" }).click(); await page.getByRole("menuitem", { name: item }).click(); }

async function routinesBadgeEqualsTab(ctx) {
  const notes = [];
  const liveFixtures = PROPOSALS.filter((p) => !p.expired).length + INBOX.filter((i) => i.section === "confirm" && i.status !== "done" && i.status !== "dismissed").length;
  const view = await openRoutines(ctx, "badge equals tab", { tab: "confirm" });
  try {
    const page = view.page;
    await rtNumbers(page, liveFixtures, "opening");
    // one handled: the three drop together
    await rtEntry(page, "NVDA 10-Q").getByRole("button", { name: "更多操作" }).click();
    await page.getByRole("menuitem", { name: "跳过" }).click();
    await rtNumbers(page, liveFixtures - 1, "after 跳过");
    notes.push(`${liveFixtures} = ${liveFixtures} = ${liveFixtures} on opening; 跳过 → ${liveFixtures - 1} in all three`);
    await rtEntry(page, "每周五盘后总结").getByRole("button", { name: "去对话核对" }).waitFor({ timeout: 5000 });
  } finally { await view.close(); }
  // with an expired proposal, another suggestion and a confirmed one: expired and confirmed are lines, not live cards, not counted
  const second = await openRoutines(ctx, "badge equals tab extras", { tab: "confirm", state: stateWithRoutines() });
  try {
    const page = second.page;
    await rtNumbers(page, liveFixtures + 1, "with extras");
    assert((await page.locator('[data-testid=confirm-entry][data-phase=expired]').count()) === 1, "the expired proposal is not shown as a line");
    assert((await rtEntry(page, "NVDA").locator('[data-slot="approval-card"]').getAttribute("data-state")) === "active", "a live card is not active");
    await rtEntry(page, "AAPL 10-K").getByRole("button", { name: "同意" }).click();
    await rtNumbers(page, liveFixtures, "after 同意");
    const folded = page.locator("[data-testid=confirm-entry][data-phase=done]");
    await folded.waitFor({ timeout: 5000 });
    assert((await folded.innerText()).includes("已确认"), `the confirmed write's line says ${await folded.innerText()}`);
    // 稍后再说 leaves the card where it is and the number as it is
    await rtEntry(page, "NVDA 10-Q").getByRole("button", { name: "更多操作" }).click();
    await page.getByRole("menuitem", { name: "稍后再说" }).click();
    await page.waitForFunction(() => document.querySelector("[data-sonner-toast]"), null, { timeout: 5000 });
    await rtNumbers(page, liveFixtures, "after 稍后再说");
    notes.push(`with an expired proposal and a second write: ${liveFixtures + 1} in all three, the expired one a line and not counted; 同意 → ${liveFixtures} and a 已确认 line; 稍后再说 changes nothing`);
  } finally { await second.close(); }
  // the phone's bar says it too
  const phone = await openRoutines(ctx, "badge phone", { tab: "confirm", width: 390 });
  try {
    const bar = phone.page.locator('[data-slot="mobile-tab-bar"] a[href="#/routines"] [data-count]');
    await bar.waitFor({ timeout: 10000 });
    assert(Number((await bar.innerText()).trim()) === liveFixtures && (await rtTabNumber(phone.page)) === liveFixtures && (await rtLiveCards(phone.page)) === liveFixtures, "the phone's bar, the tab and the cards differ");
    notes.push("same on the phone");
  } finally { await phone.close(); }
  return notes.join("; ");
}

/** The two ways to a conversation: what the old page's presses did.  The reads and writes of the old page are the baseline's. */
const rtReads = (view, from) => view.mock.requests.slice(from).filter((r) => r.method === "GET").map((r) => r.path + r.query);
// What this check can and cannot see (P9.1, opus-phase7-accept 2.4 criterion 2): after 「去对话核对」 the chat page has no last fact to wait for, so the check does not wait for one.  It catches a
// request that goes out EARLY or WRONG (an extra one that arrives before the comparison, a changed body or path); a duplicate that arrives LATER than the comparison is a blind spot, covered only
// by reading the code.  Whoever quotes this check says no more than that.
async function routinesProposalActions(ctx) {
  const notes = [];
  const view = await openRoutines(ctx, "proposal actions", { tab: "confirm", state: stateWithRoutines() });
  try {
    const page = view.page;
    const live = page.locator("[data-testid=confirm-entry][data-kind=proposal][data-phase=live]");
    assert((await live.count()) === 1, "there is not one live proposal");
    const buttons = await live.locator("button").allInnerTexts();
    assert(JSON.stringify(buttons.map((b) => b.trim())) === JSON.stringify(["去对话核对"]), `the proposal card's buttons are ${JSON.stringify(buttons)}: its only press is the way to its conversation`);
    assert((await live.getByRole("button", { name: /同意|确认/ }).count()) === 0, "a proposal card carries a 同意 button the old page did not have");
    assert((await live.locator('[data-slot="approval-card"]').getAttribute("data-kind")) === "write", "the card is not the action material's write card");
    const from = view.mock.requests.length;
    await live.getByRole("button", { name: "去对话核对" }).click();
    await waitHash(page, RT_BASE.proposals.live.hashAfter);
    await until(() => rtReads(view, from).some((p) => p.includes(`/conversations/${PROPOSALS[0].conversation_id}/messages`)), "the proposal's conversation was not opened");
    assert(rtWrites(view).length === 0, "pressing 去对话核对 on a proposal wrote something to the task lists");
    const old = RT_BASE.proposals.live.writes.map((w) => `${w.method} ${w.path}`);
    const followed = () => view.mock.requests.slice(from).filter((r) => r.method !== "GET").map((r) => `${r.method} ${r.path.startsWith("/agent-chat") ? r.path : `/agent-chat${r.path}`}`);
    // The bot's read mark is sent a moment after the conversation's messages are read: wait for the request the old page sent (the fact), then compare the whole list.
    await until(() => followed().length >= old.length, `the old page's ${JSON.stringify(old)} was not sent (sent: ${JSON.stringify(followed())})`);
    const got = followed();
    assert(JSON.stringify(got) === JSON.stringify(old), `the requests that followed: ${JSON.stringify(got)}, the old page's: ${JSON.stringify(old)}`);
    notes.push(`a live proposal: one button, 去对话核对, opens its conversation (${RT_BASE.proposals.live.hashAfter}), the old requests`);
  } finally { await view.close(); }
  const second = await openRoutines(ctx, "proposal expired", { tab: "confirm", state: stateWithRoutines() });
  try {
    const page = second.page;
    const line = page.locator("[data-testid=confirm-entry][data-kind=proposal][data-phase=expired]");
    const text = (await line.innerText()).replace(/\s+/g, " ");
    assert(text.includes("已过期") && text.includes("在对话里再说一次") && text.includes("NewsBot") && text.includes("删除任务「盘前新闻速览」"), `the expired line says: ${text}`);
    assert((await line.locator('[data-slot="approval-card"]').getAttribute("data-state")) === "expired", "the expired line is not the card's own folded state");
    const from = second.mock.requests.length;
    await line.getByRole("button", { name: "打开对话" }).click();
    await waitHash(page, RT_BASE.proposals.expired.hashAfter);
    await until(() => rtReads(second, from).some((p) => p.includes(`/conversations/${EXPIRED_PROPOSAL_CONVERSATION}/messages`)), "the expired proposal's conversation was not opened");
    notes.push("an expired proposal: a line 已过期 · 在对话里再说一次 with the bot and what it was, and 打开对话 to its conversation");
  } finally { await second.close(); }
  return notes.join("; ");
}
const EXPIRED_PROPOSAL_CONVERSATION = CONVERSATION.newsbot;

async function routinesSuggestionActions(ctx) {
  const done = [];
  const CASES = [
    ["confirm", (page, e) => e.getByRole("button", { name: "同意", exact: true }).click(), "NVDA 10-Q"],
    ["skip", (page, e) => rtMore(page, e, "跳过"), "NVDA 10-Q"],
    ["later", (page, e) => rtMore(page, e, "稍后再说"), "NVDA 10-Q"],
    ["mint", (page, e) => e.getByRole("button", { name: "去对话核对", exact: true }).click(), "NVDA 10-Q"],
    ["dismiss", (page, e) => rtMore(page, e, "忽略"), "NVDA 10-Q"],
    ["open", (page, e) => rtMore(page, e, "打开对话"), "AAPL 10-K"],
  ];
  for (const [name, press, text] of CASES) {
    const old = RT_BASE.suggestions[name];
    const view = await openRoutines(ctx, `suggestion ${name}`, { tab: "confirm", state: stateWithRoutines() });
    try {
      const page = view.page;
      const entry = rtEntry(page, text);
      if (name === "confirm") {
        // at most two main buttons; the rest are in 「…」
        const visible = (await entry.locator("button").allInnerTexts()).map((b) => b.trim()).filter(Boolean);
        assert(JSON.stringify(visible) === JSON.stringify(["同意", "去对话核对"]), `the card's visible buttons are ${JSON.stringify(visible)}`);
        await entry.getByRole("button", { name: "更多操作" }).click();
        const items = await page.getByRole("menuitem").allInnerTexts();
        assert(JSON.stringify(items.map((i) => i.trim())) === JSON.stringify(["跳过", "稍后再说", "忽略"]), `the 「…」 menu holds ${JSON.stringify(items)}`);
        await page.keyboard.press("Escape");
        assert((await entry.innerText()).includes("周日组合复盘") && (await entry.innerText()).includes("FinBot"), "the card does not say which bot and which task it comes from");
      }
      const from = view.mock.requests.length;
      await press(page, entry);
      if (name === "mint" || name === "open") await waitHash(page, old.hashAfter);
      else await until(() => rtWrites(view).length >= 1, `${name}: nothing was sent`);
      await page.waitForTimeout(250);
      const got = rtWrites(view).map((w) => ({ path: `/agent-chat${w.path}`, body: rtBody(w) }));
      const want = old.writes.filter((w) => /\/inbox\//.test(w.path)).map((w) => ({ path: w.path, body: w.body }));
      assert(JSON.stringify(got) === JSON.stringify(want), `${name}: sent ${JSON.stringify(got)}, the old page sent ${JSON.stringify(want)}`);
      if (name === "mint") assert(view.mock.requests.slice(from).some((r) => r.method === "GET" && r.path.includes("/conversations/")), "mint: the conversation of the run was not opened");
      // what is left on the page
      if (name === "confirm") assert((await page.locator("[data-testid=confirm-entry][data-phase=done]").count()) === 1, "confirm: no 已确认 line");
      if (name === "skip" || name === "dismiss") assert((await page.locator("[data-testid=confirm-entry]", { hasText: "NVDA 10-Q" }).count()) === 0, `${name}: the card is still there`);
      if (name === "later") assert((await rtLiveCards(page)) === 3, `later: ${await rtLiveCards(page)} live cards, 3 expected`);
      done.push(name);
    } finally { await view.close(); }
  }
  return `${done.length} presses (${done.join(", ")}) sent the old requests with the old bodies; the card has two main buttons (同意, 去对话核对) and 跳过 / 稍后再说 / 忽略 in 「…」; 打开对话 only where the run has a conversation`;
}

async function routinesValidation(ctx) {
  const view = await openRoutines(ctx, "validation");
  try {
    const page = view.page;
    await rtNewTask(view);
    // everything wrong at once: every rule is listed, the stepper marks the sections, the form jumps to the first
    await rtGo(page, "basics"); await page.locator("#task-name").fill("");
    await rtGo(page, "time"); await page.locator(`[data-testid=task-schedule] [data-option=every]`).click(); await page.locator("#task-every").fill("0");
    await page.locator("#task-time").fill("");
    await page.locator(`[data-testid=task-count] [data-option=count]`).click(); await page.locator("#task-runs").fill("2.5");
    await rtGo(page, "scope"); await page.locator("[data-testid=task-scope] [data-option=symbols]").click();
    await rtGo(page, "basics"); await page.locator("[data-testid=task-kind] [data-option=alerts]").click();
    await rtGo(page, "content"); await rtRows(page, [["NVDA", "above", ""]]);
    await rtSave(view);
    const list = page.locator("[data-testid=task-problems]");
    await list.waitFor({ timeout: 5000 });
    const said = (await list.locator("li").allInnerTexts()).map((t) => t.trim());
    assert(said.length === 6, `${said.length} rules listed, 6 are broken: ${JSON.stringify(said)}`);
    assert(said[0] === RT_BASE.createValidation.noName.alert[0] && said.includes(RT_BASE.createValidation.symbolsEmpty.alert[0]), `the old sentences are not there: ${JSON.stringify(said)}`);
    assert(said.includes("间隔要填整数，至少为 1。") && said.includes("执行次数要填整数，至少为 1。") && said.includes("请填运行时间。") && said.includes("代码和价格都要填。"), `the sentences: ${JSON.stringify(said)}`);
    assert(rtWrites(view).length === 0, "a request went out with the form broken");
    assert((await page.locator(`${RT_DRAWER}`).getAttribute("data-section")) === "basics", "the form did not jump to the first section with a problem");
    assert((await page.locator(`${RT_DRAWER} [data-slot=stepper] [data-step-button]`).count()) === 4, "the step row is not four buttons");
    const marked = await page.locator(`${RT_DRAWER} [data-slot=stepper] li`).evaluateAll((els) => els.filter((e) => /这一步有要改/.test(e.textContent)).map((e) => e.getAttribute("data-step")));
    assert(JSON.stringify(marked) === JSON.stringify(["basics", "time", "scope", "content"]), `the step row marks ${JSON.stringify(marked)}`);
    // a sentence in the list goes to its section; in the section it is at its field
    await page.locator("[data-testid=task-problems] button", { hasText: "股票代码无效" }).click();
    await page.locator("[data-testid=task-section-scope]").waitFor({ timeout: 5000 });
    await page.locator("[data-slot=field-error]", { hasText: "股票代码无效" }).waitFor({ timeout: 5000 });
    // mending them one by one empties the list; then the save goes out
    await page.locator("#task-symbols").fill("AAPL"); await page.locator("#task-symbols").press("Enter");
    await rtGo(page, "basics"); await page.locator("#task-name").fill("全修好");
    await rtGo(page, "time"); await page.locator("#task-every").fill("2"); await page.locator("#task-time").fill("09:00"); await page.locator("#task-runs").fill("4");
    await rtGo(page, "content"); await page.locator("[data-testid=price-row] [data-field=price]").fill("150");
    await page.waitForFunction(() => !document.querySelector("[data-testid=task-problems]"), null, { timeout: 5000 });
    await rtSave(view);
    const [write] = await rtWritesAfter(view, 1, "mended");
    assert(write.body.name === "全修好" && write.body.every_value === 2 && write.body.max_runs === 4 && JSON.stringify(write.body.symbols) === '["AAPL"]', `mended body ${JSON.stringify(write.body)}`);
    // the code of a company is checked as it is typed: what the server would refuse never becomes a tag
    return "6 broken rules listed at once with the old sentences, the step row marks all four sections, the form jumps to the first, a listed sentence goes to its field, mending them clears the list and the save goes out";
  } finally { await view.close(); }
}

async function routinesUnsavedClose(ctx) {
  const view = await openRoutines(ctx, "unsaved close");
  try {
    const page = view.page;
    const button = page.locator("[data-testid=task-new]").first();
    // nothing changed: Esc closes at once
    await button.focus(); await page.keyboard.press("Enter"); await page.locator(RT_DRAWER).waitFor({ timeout: 5000 });
    await page.keyboard.press("Escape"); await page.locator(RT_DRAWER).waitFor({ state: "detached", timeout: 5000 });
    await page.waitForFunction(() => document.activeElement?.getAttribute("data-testid") === "task-new", null, { timeout: 3000 }).catch(() => { throw new Error("the focus did not return to 新建任务 after the drawer closed"); });
    // a change: Esc, the button and the overlay each ask first
    for (const how of ["escape", "cancel", "overlay"]) {
      await button.focus(); await page.keyboard.press("Enter"); await page.locator(RT_DRAWER).waitFor({ timeout: 5000 });
      await page.locator("#task-name").fill(`改过的名字 ${how}`);
      if (how === "escape") await page.keyboard.press("Escape"); else if (how === "cancel") await page.locator("[data-testid=task-cancel]").click(); else await page.mouse.click(60, 600);
      const dlg = page.locator('[data-slot="alert-dialog-content"]'); await dlg.waitFor({ timeout: 5000 });
      assert((await dlg.locator('[data-slot="alert-dialog-title"]').innerText()).includes("放弃未保存的修改"), `${how}: the question is not about unsaved changes`);
      await dlg.getByRole("button", { name: "继续编辑" }).click(); await dlg.waitFor({ state: "detached", timeout: 5000 });
      assert((await page.locator("#task-name").inputValue()) === `改过的名字 ${how}`, `${how}: the draft was lost on 继续编辑`);
      if (how === "overlay") { await page.keyboard.press("Escape"); await dlg.waitFor({ timeout: 5000 }); await dlg.getByRole("button", { name: "放弃修改" }).click(); await page.locator(RT_DRAWER).waitFor({ state: "detached", timeout: 5000 }); }
      else { await page.keyboard.press("Escape"); await dlg.waitFor({ timeout: 5000 }); await dlg.getByRole("button", { name: "放弃修改" }).click(); await page.locator(RT_DRAWER).waitFor({ state: "detached", timeout: 5000 }); }
    }
    assert(rtWrites(view).length === 0, "closing sent a request");
    // reopened: a fresh form, not the thrown-away draft
    await button.click(); await page.locator(RT_DRAWER).waitFor({ timeout: 5000 });
    assert((await page.locator("#task-name").inputValue()) === "研究队列简报", "the thrown-away draft came back");
    return "no change: Esc closes at once and the focus returns to 新建任务; a change: Esc, 取消 and a click outside each ask 放弃未保存的修改？; 继续编辑 keeps the draft, 放弃修改 closes it and the next form is fresh; nothing was sent";
  } finally { await view.close(); }
}

async function routinesDrawerBreakpoint(ctx) {
  const view = await openRoutines(ctx, "drawer breakpoint");
  try {
    const page = view.page;
    await rtNewTask(view);
    await page.locator(RT_DRAWER).evaluate((el) => { el.setAttribute("data-mark", "same"); });
    await page.locator("#task-name").fill("跨断点不丢");
    await rtGo(page, "time"); await page.locator(`[data-testid=task-schedule] [data-option=daily]`).click();
    for (const width of [390, 1023, 1024, 1440]) {
      await page.setViewportSize({ width, height: width < 1024 ? 844 : 900 });
      await page.waitForTimeout(250);
      assert((await page.locator(RT_DRAWER).getAttribute("data-mark")) === "same", `at ${width}: the drawer is another element (it was re-mounted)`);
      assert((await page.locator(RT_DRAWER).getAttribute("data-section")) === "time", `at ${width}: the section changed`);
      assert((await page.locator(`[data-testid=task-schedule] input:checked`).getAttribute("value")) === "daily", `at ${width}: the schedule was lost`);
    }
    await rtGo(page, "basics");
    assert((await page.locator("#task-name").inputValue()) === "跨断点不丢", "the name was lost");
    const box = await page.locator(RT_DRAWER).boundingBox();
    await page.setViewportSize({ width: 390, height: 844 });
    await page.waitForTimeout(250);
    const phone = await page.locator(RT_DRAWER).boundingBox();
    assert(phone.width >= 388 && phone.height >= 840, `on a phone the drawer is ${phone.width}x${phone.height}, not the whole screen`);
    assert(box.width < 600, `on a desktop the drawer is ${box.width} wide`);
    return "one drawer element across 390 → 1023 → 1024 → 1440 (the same node, the section, the choice and the name kept); the whole screen on a phone, a side panel on a desktop";
  } finally { await view.close(); }
}

async function routinesKeyboard(ctx) {
  const view = await openRoutines(ctx, "keyboard", { tab: "confirm" });
  try {
    const page = view.page;
    const tab = (testid) => page.locator(`[data-testid=${testid}]`);
    // the tabs (the company page's tab list: manual activation): the arrow keys move the focus, Enter or Space opens the one in focus and the address follows (replace, no history entry)
    await tab("tab-confirm").focus();
    const length = await page.evaluate(() => history.length);
    await page.keyboard.press("ArrowRight");
    await page.waitForFunction(() => document.activeElement?.getAttribute("data-testid") === "tab-tasks", null, { timeout: 5000 }).catch(() => { throw new Error("ArrowRight did not move the focus to 全部任务"); });
    assert(!(await page.evaluate(() => /[?&]tab=tasks/.test(location.hash))), "an arrow key opened a tab (it should only move the focus)");
    await page.keyboard.press("Enter");
    await page.waitForFunction(() => /[?&]tab=tasks/.test(location.hash), null, { timeout: 5000 });
    await page.waitForFunction(() => document.querySelector("[data-testid=tab-tasks]")?.getAttribute("aria-selected") === "true", null, { timeout: 5000 }).catch(() => { throw new Error("Enter did not select 全部任务"); });
    await page.keyboard.press("ArrowRight"); await page.keyboard.press("Space");
    await page.waitForFunction(() => /[?&]tab=runs/.test(location.hash), null, { timeout: 5000 });
    assert((await page.evaluate(() => history.length)) === length, "switching tabs added history entries");
    await page.keyboard.press("ArrowLeft"); await page.keyboard.press("Enter"); await page.waitForFunction(() => /[?&]tab=tasks/.test(location.hash), null, { timeout: 5000 });
    await page.locator(RT_CARDS).first().waitFor({ timeout: 10000 });
    // a card's switch with Space, its menu with Enter and the arrow keys
    const first = page.locator(RT_CARDS).first();
    await first.locator("[data-testid=task-switch]").focus(); await page.keyboard.press("Space");
    await rtWritesAfter(view, 1, "Space on the switch");
    assert(rtBody(rtWrites(view)[0]) === '{"enabled":false}', `Space sent ${rtBody(rtWrites(view)[0])}`);
    await page.waitForFunction(() => !document.querySelector("[data-testid=task-menu]").disabled, null, { timeout: 8000 });
    await first.locator("[data-testid=task-menu]").focus(); await page.keyboard.press("Enter");
    await page.locator("[data-testid=task-edit]").waitFor({ timeout: 5000 });
    await page.keyboard.press("Enter");
    await page.locator(RT_DRAWER).waitFor({ timeout: 5000 });
    // in the drawer: the focus is inside it, the step buttons are reachable, Tab does not leave it
    await page.waitForFunction(() => !!document.activeElement?.closest("[data-testid=task-drawer]"), null, { timeout: 4000 }).catch(() => { throw new Error("the focus did not move into the drawer"); });
    for (let i = 0; i < 40; i++) { await page.keyboard.press("Tab"); if (!(await page.evaluate(() => !!document.activeElement?.closest("[data-testid=task-drawer]")))) throw new Error(`Tab left the drawer after ${i + 1} presses`); }
    // the drawer is modal: what is behind it is hidden from a screen reader and cannot be reached (an overlay is up)
    assert(await page.evaluate(() => !!document.querySelector("[data-testid=routines-page]")?.closest('[aria-hidden="true"], [inert]')), "the page behind the drawer is not hidden from a screen reader (the drawer is not modal)");
    assert((await page.locator('[data-slot="drawer-overlay"]').count()) === 1, "the drawer has no overlay");
    // from the name, only the keyboard: type, go to 内容, save
    await page.locator("[data-step-button=basics]").focus(); await page.keyboard.press("Enter");
    await page.locator("#task-name").focus(); await page.keyboard.press("Control+a"); await page.keyboard.type("键盘改的名字");
    await page.locator("[data-step-button=content]").focus(); await page.keyboard.press("Enter");
    await page.locator("[data-testid=task-section-content]").waitFor({ timeout: 5000 });
    await page.locator("[data-testid=task-submit]").focus(); await page.keyboard.press("Enter");
    await rtWritesAfter(view, 2, "the keyboard save");
    assert(rtWrites(view)[1].body.name === "键盘改的名字", `the keyboard save sent ${rtBody(rtWrites(view)[1])}`);
    await page.locator(RT_DRAWER).waitFor({ state: "detached", timeout: 8000 });
    await page.waitForFunction(() => document.activeElement?.getAttribute("data-testid") === "task-menu", null, { timeout: 3000 }).catch(() => { throw new Error("the focus did not return to the card's 「…」 button after the save"); });
    // 待你确认: the card's buttons are reached by Tab, the 「…」 menu opens with Enter
    await tab("tab-confirm").click();
    await page.locator('[data-testid=confirm-entry] [data-slot="approval-card"]').first().waitFor({ timeout: 10000 });
    const entry = rtEntry(page, "NVDA 10-Q");
    await entry.getByRole("button", { name: "更多操作" }).focus(); await page.keyboard.press("Enter");
    await page.getByRole("menuitem", { name: "跳过" }).waitFor({ timeout: 5000 });
    await page.keyboard.press("ArrowDown"); await page.keyboard.press("Escape");
    return "tabs: arrow keys move the focus, Enter / Space open (the address follows, no history entry); Space flips a switch; Enter opens the 「…」 menu and 编辑; the drawer holds the focus (40 Tabs stay in), a keyboard-only save sends the new name, the focus returns to 「…」; a card's 「…」 menu opens by Enter";
  } finally { await view.close(); }
}

async function routinesStates(ctx) {
  const notes = [];
  // 全部任务: skeleton after 400 ms; the read failing: an error bar with 重试 and the other tabs unharmed; empty: the first-task offer
  const held = await newView(ctx.browser, { width: 1440, theme: "light", label: "routines held", unmatched });
  try {
    const page = held.page;
    held.mock.control.hold = (method, path) => method === "GET" && /\/tasks$/.test(path);
    await page.goto(`${ctx.server.url}#/routines?tab=tasks`, { waitUntil: "load" });
    await page.locator("[data-testid=routines-page]").waitFor({ timeout: 15000 });
    assert((await page.locator("[data-testid=tasks-skeleton]").count()) === 0, "a skeleton before 400 ms");
    await page.locator("[data-testid=tasks-skeleton]").waitFor({ timeout: 3000 });
    // the other tabs have their own states: 运行记录 is not waiting for the tasks
    await page.locator("[data-testid=tab-runs]").click();
    await page.locator("[data-testid=runs-pane] [data-slot=timeline-item]").first().waitFor({ timeout: 8000 });
    notes.push("tasks held: no skeleton before 400 ms, one after; the runs tab is not held up by it");
  } finally { await held.close(); }
  const failing = await newView(ctx.browser, { width: 1440, theme: "light", label: "routines failing", unmatched });
  try {
    const page = failing.page;
    failing.mock.control.fail = (method, path) => (method === "GET" && /\/tasks$/.test(path) ? 500 : 0);
    await page.goto(`${ctx.server.url}#/routines?tab=tasks`, { waitUntil: "load" });
    const bar = page.locator('[data-testid=tasks-list] [data-slot="error-bar"]');
    await bar.waitFor({ timeout: 15000 });
    assert((await bar.getByRole("button", { name: "重试" }).count()) === 1, "no 重试");
    failing.mock.control.fail = null;
    await bar.getByRole("button", { name: "重试" }).click();
    await page.locator(RT_CARDS).first().waitFor({ timeout: 8000 });
    assert((await bar.count()) === 0, "the error bar stayed after the list came");
    notes.push("a failing read: error bar with 重试 in the tab, the list comes with it");
  } finally { await failing.close(); }
  const empty = await newView(ctx.browser, { width: 1440, theme: "light", label: "routines empty", unmatched, fixtureState: (() => { const s = buildState(); s.tasks = []; s.runs = []; return s; })() });
  try {
    const page = empty.page;
    await page.goto(`${ctx.server.url}#/routines?tab=tasks`, { waitUntil: "load" });
    await page.locator("[data-testid=tasks-empty]").waitFor({ timeout: 15000 });
    assert((await page.locator("[data-testid=tasks-empty]").innerText()).includes("还没有任务。"), "the empty sentence is not the old one");
    await page.locator("[data-testid=tasks-empty]").getByRole("button", { name: "新建任务" }).click();
    await page.locator(RT_DRAWER).waitFor({ timeout: 5000 });
    await page.keyboard.press("Escape"); await page.locator(RT_DRAWER).waitFor({ state: "detached", timeout: 5000 });
    await page.locator("[data-testid=tab-runs]").click();
    await page.locator("[data-testid=runs-empty]").waitFor({ timeout: 8000 });
    assert((await page.locator("[data-testid=runs-empty]").innerText()).includes("还没有运行记录。"), "the runs' empty sentence is not the old one");
    notes.push("empty: 还没有任务。 with 新建任务 that opens the drawer; 还没有运行记录。");
  } finally { await empty.close(); }
  // 待你确认: nothing waits (one sentence), one of the two lists failing (the other still lists, with an error bar)
  const none = await openRoutines(ctx, "routines none", { tab: "confirm", state: stateWithoutConfirms(), ready: "[data-testid=confirm-empty]" });
  try {
    assert((await none.page.locator("[data-testid=confirm-empty]").innerText()).includes("没有等你确认的事"), "the empty sentence is wrong");
    assert((await rtBadgeNumber(none.page)) === 0 && (await rtTabNumber(none.page)) === 0, "a number is shown with nothing waiting");
    notes.push("nothing waiting: 没有等你确认的事, no number anywhere");
  } finally { await none.close(); }
  const partial = await newView(ctx.browser, { width: 1440, theme: "light", label: "routines partial", unmatched });
  try {
    const page = partial.page;
    partial.mock.control.fail = (method, path) => (method === "GET" && /\/tasks\/proposals$/.test(path) ? 500 : 0);
    await page.goto(`${ctx.server.url}#/routines?tab=confirm`, { waitUntil: "load" });
    await page.locator('[data-testid=confirm-tab] [data-slot="error-bar"]').waitFor({ timeout: 15000 });
    await page.locator('[data-testid=confirm-entry][data-kind=suggestion] [data-slot="approval-card"]').first().waitFor({ timeout: 10000 });
    notes.push("proposals unreadable: the error bar and the suggested writes still listed");
  } finally { await partial.close(); }
  return notes.join("; ");
}

async function routinesTabAddress(ctx) {
  const notes = [];
  const view = await openRoutines(ctx, "tab address", { hash: "#/routines", ready: RT_CONFIRM_READY });
  try {
    const page = view.page;
    assert((await page.locator("[data-testid=tab-confirm]").getAttribute("aria-selected")) === "true", "an address without ?tab= does not open 待你确认");
    await page.locator("[data-testid=tab-tasks]").click();
    await page.waitForFunction(() => /[?&]tab=tasks/.test(location.hash), null, { timeout: 5000 });
    await page.locator(RT_CARDS).first().waitFor({ timeout: 8000 });
    // the bot filter: in the address, on the list and on the runs (the server is asked for that bot's)
    await rtCombo(page, "[data-testid=bot-filter]", "News", "NewsBot");
    await page.waitForFunction(() => /[?&]bot=/.test(location.hash), null, { timeout: 5000 });
    await page.waitForFunction(() => document.querySelectorAll("[data-testid=task-card]").length === 1, null, { timeout: 5000 });
    assert((await page.locator(RT_CARDS).first().innerText()).includes("盘前新闻速览"), "the filtered list is not NewsBot's");
    await page.locator("[data-testid=tab-runs]").click();
    await page.locator("[data-testid=runs-pane] [data-slot=timeline-item]").first().waitFor({ timeout: 8000 });
    assert(view.mock.requests.some((r) => r.method === "GET" && /\/tasks\/runs$/.test(r.path) && r.query.includes(`bot_id=${BOT.newsbot}`)), "the runs were not asked for NewsBot's");
    assert((await page.locator("[data-testid=runs-pane] [data-slot=timeline-item]").count()) === 2, "NewsBot has two runs in the fixtures");
    notes.push("no ?tab= → 待你确认; clicking a tab writes it into the address; ?bot= filters the tasks (one) and asks the server for that bot's runs (two)");
  } finally { await view.close(); }
  // an address names everything: a refresh and a pasted link land on the same tab, bot and (for a bad value) fall back
  for (const [hash, tab, bot] of [[`#/routines?tab=runs&bot=${BOT.applebot}`, "runs", "AppleBot"], [`#/routines?tab=tasks&bot=${BOT.finbot}`, "tasks", "FinBot"], ["#/routines?tab=nonsense&bot=nope", "confirm", null]]) {
    const v = await openRoutines(ctx, `address ${tab}`, { hash, ready: "[data-testid=routines-page]" });
    try {
      await v.page.waitForFunction((t) => document.querySelector(`[data-testid=tab-${t}]`)?.getAttribute("aria-selected") === "true", tab, { timeout: 8000 });
      if (bot) assert((await v.page.locator("[data-testid=bot-filter]").innerText()).includes(bot), `${hash}: the filter says ${await v.page.locator("[data-testid=bot-filter]").innerText()}`);
    } finally { await v.close(); }
  }
  notes.push("a pasted link opens the named tab and bot; an unknown tab or bot falls back");
  return notes.join("; ");
}

async function routinesBotSection(ctx) {
  const view = await openRoutines(ctx, "bot section", { state: stateWithRoutines(), hash: `#/chat/${BOT.applebot}/settings?section=routines`, ready: "[data-testid=bot-settings-page]" });
  try {
    const page = view.page;
    await openSection(page, "routines");
    const section = page.locator("[data-section=routines]");
    await section.locator("[data-testid=task-card]").first().waitFor({ timeout: 15000 });
    const names = (await section.locator("[data-testid=task-card] h3").allInnerTexts()).map((n) => n.trim());
    assert(JSON.stringify(names) === JSON.stringify(["AAPL 财报跟踪", "旧式价格线"]), `the section lists ${JSON.stringify(names)}: AppleBot's two tasks and no one else's`);
    assert((await section.locator("[data-legacy]").count()) === 0 && (await section.locator(".bot-routines, .task-form, .personal-badge, .memory-list").count()) === 0, "the section still carries the old markup");
    await section.locator("[data-slot=timeline-item]").first().waitFor({ timeout: 8000 });
    assert((await section.locator("h3", { hasText: "最近 20 次运行" }).count()) === 1, "the runs heading is gone");
    assert((await section.locator("[data-testid=bot-routines] [data-testid=task-card] [data-slot=bot-avatar]").count()) === 0, "a card repeats the bot's avatar on the bot's own page");
    // new: the bot is fixed; the body is the old settings-page body
    await section.locator("[data-testid=task-new]").click(); await page.locator(RT_DRAWER).waitFor({ timeout: 5000 });
    assert((await page.locator("[data-testid=task-bot-locked]").innerText()).includes("AppleBot"), "the bot is not shown as fixed");
    assert((await page.locator("#task-bot[role=combobox]").count()) === 0, "the bot can be changed on the bot's own page");
    await page.locator("#task-name").fill("本 bot 简报"); await rtGo(page, "content"); await page.locator("#task-instruction").fill("x");
    await rtSave(view);
    const [write] = await rtWritesAfter(view, 1, "bot section");
    assert(rtBody(write) === rtOldBody(RT_BASE.botPage.create.sent, "POST", /\/tasks$/), `body ${rtBody(write)} differs from the old section's ${rtOldBody(RT_BASE.botPage.create.sent, "POST", /\/tasks$/)}`);
    await section.locator("[data-testid=task-card]", { hasText: "本 bot 简报" }).waitFor({ timeout: 8000 });
    assert((await page.locator('[data-testid=save-bar]').count()) === 0, "a task change brought up the bot's save bar");
    // the same page, a phone
    return "AppleBot's two tasks and its runs, no old markup; 新建 fixes the bot and sends the old body; the card is listed and the save bar stays away";
  } finally { await view.close(); }
}

async function routinesNoLegacy(ctx) {
  const view = await openRoutines(ctx, "routines no legacy", { tab: "confirm", state: stateWithRoutines() });
  try {
    const page = view.page;
    const check = async (what) => {
      const found = await page.evaluate(() => {
        const OLD = ".personal-page, .personal-card, .memory-panel, .memory-list, .memory-quote, .personal-badge, .task-form, .bot-routines, .secondary-action, .primary-action, .fine-print";
        return { legacy: document.querySelectorAll("[data-legacy]").length, old: document.querySelectorAll(`:is(main, [data-testid=task-drawer]) :is(${OLD}), :is(main, [data-testid=task-drawer]):is(${OLD})`).length, native: document.querySelectorAll("main select, [data-testid=task-drawer] select").length };
      });
      assert(found.legacy === 0 && found.old === 0, `${what}: ${found.legacy} old-UI frames and ${found.old} old class elements`);
      assert(found.native === 0, `${what}: ${found.native} native <select>`);
    };
    await check("待你确认");
    await page.locator("[data-testid=tab-tasks]").click(); await page.locator(RT_CARDS).first().waitFor({ timeout: 8000 }); await check("全部任务");
    await page.locator("[data-testid=tab-runs]").click(); await page.locator("[data-slot=timeline-item]").first().waitFor({ timeout: 8000 }); await check("运行记录");
    await page.locator("[data-testid=tab-tasks]").click(); await page.locator("[data-testid=task-new]").first().click(); await page.locator(RT_DRAWER).waitFor({ timeout: 5000 });
    for (const section of ["basics", "time", "scope", "content"]) { await rtGo(page, section); await check(`抽屉 ${section}`); }
    // no order wording anywhere: the page is a list of routines and nods, never a trade
    const words = await page.locator("main").innerText();
    assert(!/买入|卖出|下单|成交|执行交易/.test(words.replace(/新建任务/g, "")), `the page holds trade wording: ${words.match(/买入|卖出|下单|成交|执行交易/)}`);
    const small = await page.evaluate(() => [...document.querySelectorAll("[data-testid=routines-page] *, [data-testid=task-drawer] *")].filter((el) => el.childNodes.length && [...el.childNodes].some((n) => n.nodeType === 3 && n.textContent.trim()) && parseFloat(getComputedStyle(el).fontSize) < 12).length);
    assert(small === 0, `${small} text elements under 12px`);
    return "the three tabs and the drawer's four sections: no old-UI frame, no old class, no native <select>, no trade wording, no text under 12px";
  } finally { await view.close(); }
}


// --- P7.3: the research area without the old-UI marker -------------------------------------------------------------------------------------
/** A watcher that lives in the page from its first byte: it counts the most old-marker / old-class elements the document ever held at one time (a state that comes and goes between two reads is still seen). */
function watchOldMarks(selector) {
  window.__oldMarkPeak = 0;
  const look = () => { const n = document.querySelectorAll(`[data-legacy], ${selector}`).length; if (n > window.__oldMarkPeak) window.__oldMarkPeak = n; };
  new MutationObserver(look).observe(document, { childList: true, subtree: true, attributes: true });
  document.addEventListener("DOMContentLoaded", look);
}

async function latestRedirectStates(ctx) {
  const notes = [];
  const expectedRoot = forecastRoots("AAPL").roots[0].id;
  assert(forecastRoots("MSFT").roots.length === 0, "the fixture changed: MSFT has forecasts now, so there is no company without one");
  const open = async (label, symbol, patch) => {
    const view = await newView(ctx.browser, { width: 1440, theme: "light", label, unmatched, ...(patch ? { fixtureState: stateWithMaterials(patch) } : {}) });
    await view.context.addInitScript(watchOldMarks, OLD_MARKS);
    await view.page.goto(`${ctx.server.url}#/research/c/${symbol}/latest?section=versions`, { waitUntil: "load" });
    return view;
  };
  const peak = (view) => view.page.evaluate(() => window.__oldMarkPeak ?? -1);
  // 1. a company with a forecast: the page replaces itself with that forecast's address, on its version list
  const withForecast = await open("latest: company with a forecast", "AAPL");
  try {
    const { page } = withForecast;
    await page.waitForSelector("[data-testid=forecast-page]", { state: "visible", timeout: 30000 });
    const hash = await hashOf(page);
    assert(hash.startsWith(`#/research/forecasts/${expectedRoot}`) && hash.includes("section=versions"), `landed on ${hash}, expected the forecast ${expectedRoot} on its version list`);
    await settle(page);
    assert((await peak(withForecast)) === 0, `${await peak(withForecast)} old-marker / old-class element(s) were in the page at some point`);
    assert((await oldMarkCounts(page)).legacy === 0 && (await oldMarkCounts(page)).old === 0, "the forecast page holds an old marker");
    notes.push("a company with a forecast lands on its forecast with section=versions");
  } finally { await withForecast.close(); }
  // 2. a company with no forecast: the forecast home
  const none = await open("latest: company without a forecast", "MSFT");
  try {
    await none.page.waitForSelector("[data-testid=forecast-home]", { state: "visible", timeout: 30000 });
    assert((await hashOf(none.page)) === "#/research/forecasts", `landed on ${await hashOf(none.page)}, expected #/research/forecasts`);
    await settle(none.page);
    assert((await peak(none)) === 0, `${await peak(none)} old-marker / old-class element(s) were in the page at some point`);
    notes.push("a company with none lands on the forecast home");
  } finally { await none.close(); }
  // 3. the list cannot be read: the error stays, says the old sentence, and its one way out leads to the forecast home
  const failing = await open("latest: list unreadable", "AAPL", { forecastRootsError: true });
  try {
    const { page } = failing;
    const box = page.locator("[data-testid=latest-error]");
    await box.waitFor({ state: "visible", timeout: 30000 });
    await settle(page);
    const text = (await box.innerText()).replace(/\s+/g, " ");
    assert(text.includes("暂时无法读取预测日期列表。"), `the error says: ${text}`);
    assert((await box.getAttribute("role")) === "alert", "the error is not announced as an alert");
    assert((await hashOf(page)).startsWith("#/research/c/AAPL/latest"), `the page left the redirect address: ${await hashOf(page)}`);
    await box.getByText("回到预测首页", { exact: true }).click();
    await page.waitForSelector("[data-testid=forecast-home]", { state: "visible", timeout: 30000 });
    assert((await hashOf(page)) === "#/research/forecasts", `回到预测首页 led to ${await hashOf(page)}`);
    assert((await peak(failing)) === 0, `${await peak(failing)} old-marker / old-class element(s) were in the page at some point`);
    notes.push("an unreadable list stops on the error sentence; 回到预测首页 leads to the forecast home");
  } finally { await failing.close(); }
  return `${notes.join("; ")}; in all three the document never held a data-legacy element or an old class`;
}

/** The plain buttons of the research pages keep the pointer, and the links that were underlined by the browser's own rule keep their line. */
async function researchBareControls(ctx) {
  const notes = [];
  const measure = (page, rootSelector) => page.evaluate((rootSel) => {
    const shown = (el) => { const style = getComputedStyle(el); return el.getClientRects().length > 0 && style.visibility !== "hidden" && style.display !== "none"; };
    // The restore rules of the old marker never reached a data-slot part inside the page, or anything in one, so such buttons are not part of what this check is about.
    // (The shell's own data-slot containers sit above the page's root and do not count.)
    const root = document.querySelector(rootSel);
    const inPart = (el) => { const part = el.closest("[data-slot]"); return Boolean(part) && root.contains(part) && part !== root; };
    const buttons = [...root.querySelectorAll("button")].filter((el) => !el.disabled && !inPart(el) && shown(el));
    return { count: buttons.length, wrong: buttons.filter((el) => getComputedStyle(el).cursor !== "pointer").map((el) => `${el.getAttribute("data-testid") ?? (el.textContent || "").trim().slice(0, 20)}=${getComputedStyle(el).cursor}`) };
  }, rootSelector);
  const underlined = (page, selector) => page.evaluate((sel) => { const el = document.querySelector(sel); return el ? getComputedStyle(el).textDecorationLine : null; }, selector);
  // [label, width, address, ready, the page's root, how many plain buttons it holds (counted on the page as it was inside the marker), before(page), links that stay underlined]
  const PAGES_READ = [
    ["forecast home", 1440, "#/research/forecasts", "[data-testid=forecast-home] [data-slot=formal-row]", "[data-testid=forecast-home]", 3, null, []],
    ["forecast home (phone)", 390, "#/research/forecasts", "[data-testid=forecast-home] [data-slot=formal-row]", "[data-testid=forecast-home]", 5, null, []],
    ["one forecast", 1440, `#/research/forecasts/${ROOT.aapl}`, "[data-testid=forecast-judgment]", "[data-testid=forecast-page]", 3, null, ["[data-testid=forecast-back]", "[data-testid=rail-evidence]"]],
    ["one forecast (phone)", 390, `#/research/forecasts/${ROOT.aapl}`, "[data-testid=forecast-judgment]", "[data-testid=forecast-page]", 4, null, ["[data-testid=forecast-back]", "[data-testid=rail-evidence]"]],
    ["forecast, audit tab", 1440, `#/research/forecasts/${ROOT.aapl}?section=audit`, "[data-testid=forecast-judgment]", "[data-testid=forecast-page]", 6, async (page) => { await page.waitForSelector("[data-testid=forecast-events]", { timeout: 15000 }); }, ["[data-testid=forecast-back]", "[data-testid=forecast-sources] a[href^=http]"]],
    ["judgment", 1440, `#/research/judgments/${JUDGMENT.aapl}`, "[data-testid=judgment-card]", "[data-testid=judgment-page]", 0, null, ["[data-testid=judgment-back]", "[data-testid=judgment-open-forecast]"]],
    ["evidence", 1440, `#/research/evidence/${VERSION.aapl3}`, "[data-testid=evidence-card]", "[data-testid=evidence-page]", 3, null, []],
    ["materials", 1440, "#/research/materials", "[data-testid=material-row]", "[data-testid=material-library]", 10, null, []],
  ];
  for (const [label, width, hash, ready, rootSelector, expected, before, links] of PAGES_READ) {
    const view = await newView(ctx.browser, { width, theme: "light", label: `bare controls: ${label}`, unmatched });
    try {
      const { page } = view;
      await page.goto(`${ctx.server.url}${hash}`, { waitUntil: "load" });
      await page.waitForSelector(ready, { state: "visible", timeout: 30000 });
      await settle(page);
      if (before) { await before(page); await settle(page, { pinTranscript: false }); }
      const got = await measure(page, rootSelector);
      assert(got.count === expected, `${label}: ${got.count} plain button(s) on the page, ${expected} expected (the population is the one counted on the page before the marker came off)`);
      assert(!got.wrong.length, `${label}: plain button(s) without the pointer: ${got.wrong.join(", ")}`);
      for (const selector of links) {
        const line = await underlined(page, selector);
        assert(line !== null, `${label}: ${selector} is not on the page`);
        assert(line.includes("underline"), `${label}: ${selector} lost its underline (text-decoration-line: ${line})`);
      }
      notes.push(`${label}: ${got.count} button(s)${links.length ? `, ${links.length} underlined link(s)` : ""}`);
    } finally { await view.close(); }
  }
  return notes.join("; ");
}

/** The 「…」 menu of a suggested write in the English interface: Skip, Later, Ignore (Later sends the same request as 稍后再说); the sign-in dialog keeps its Cancel. */
async function routinesLaterEnglish(ctx) {
  const view = await newView(ctx.browser, { width: 1440, theme: "light", locale: "en-US", label: "routines later (en)", unmatched, fixtureState: stateWithRoutines() });
  try {
    const { page } = view;
    await page.goto(`${ctx.server.url}#/routines?tab=confirm`, { waitUntil: "load" });
    await page.waitForSelector(RT_CONFIRM_READY, { state: "visible", timeout: 30000 });
    await settle(page);
    const entry = rtEntry(page, "NVDA 10-Q");
    await entry.getByRole("button", { name: "More actions" }).click();
    const items = (await page.getByRole("menuitem").allInnerTexts()).map((item) => item.trim());
    assert(JSON.stringify(items) === JSON.stringify(["Skip", "Later", "Ignore"]), `the 「…」 menu reads ${JSON.stringify(items)}`);
    await page.getByRole("menuitem", { name: "Later", exact: true }).click();
    await until(() => rtWrites(view).length >= 1, "Later: nothing was sent");
    // The press ends with the bot list read again (write -> notice -> the two lists -> the bot list, RoutinesPage `after`): wait for THAT fact, not for a time, then compare the whole set of writes.
    await until(() => { const sent = view.mock.requests; const w = sent.findIndex((r) => r.method !== "GET" && /\/inbox\//.test(r.path)); return w >= 0 && sent.slice(w + 1).some((r) => r.method === "GET" && /\/agent-chat\/bots$/.test(r.path)); }, "Later: the bot list was not read again after the write (the press has not ended)");
    const got = rtWrites(view).map((w) => ({ path: `/agent-chat${w.path}`, body: rtBody(w) }));
    const want = RT_BASE.suggestions.later.writes.filter((w) => /\/inbox\//.test(w.path)).map((w) => ({ path: w.path, body: w.body }));
    assert(JSON.stringify(got) === JSON.stringify(want), `Later sent ${JSON.stringify(got)}, 稍后再说 sent ${JSON.stringify(want)} in the old baseline`);
    assert(got.length === 1 && JSON.parse(got[0].body).action === "later", `Later's body is ${got[0]?.body}`);
  } finally { await view.close(); }
  const guest = await newView(ctx.browser, { width: 1440, theme: "light", locale: "en-US", label: "login dialog (en)", unmatched, identity: "guest" });
  try {
    const { page } = guest;
    await page.goto(`${ctx.server.url}#/chat`, { waitUntil: "load" });
    await page.waitForSelector('[data-slot="guest-composer"]', { state: "visible", timeout: 30000 });
    await settle(page);
    await page.locator('[data-slot="guest-composer"] button').first().click();
    const dialog = page.getByRole("dialog");
    await dialog.waitFor({ timeout: 5000 });
    assert((await dialog.getByRole("button", { name: "Cancel", exact: true }).count()) === 1, `the sign-in dialog's buttons: ${JSON.stringify(await dialog.getByRole("button").allInnerTexts())}`);
  } finally { await guest.close(); }
  return "English 「…」 menu: Skip / Later / Ignore; Later sends the baseline's later body (action: later); the sign-in dialog still reads Cancel";
}

// --- P8.1: the assistant's four pages (技能, 记忆, 新闻源, 知识库) ---------------------------------------------------------------------------
// The baseline is what the OLD pages (the production build of af8b894) sent and showed on the same fixtures (fixtures/assistant-bodies-baseline.json, recorded before any page was touched):
// the new pages must send the same requests, body for body.  Writes are read from the fake backend (`state.assistant.writes`; an upload from `state.materialPosts`), reads from its request log.
const AS = JSON.parse(fs.readFileSync(new URL("./fixtures/assistant-bodies-baseline.json", import.meta.url), "utf8"));
const asWrites = (view) => view.mock.state.assistant.writes;
const asBody = (write) => (write.body === null ? null : JSON.stringify(write.body));
/** The body the old page sent (as a string) for the first request of that method whose path ends as the pattern says. */
const asOld = (entry, method, re) => entry.sent.find((r) => r.method === method && re.test(r.path))?.body ?? null;
const asReads = (view, re) => view.mock.requests.filter((r) => r.method === "GET" && re.test(r.path)).map((r) => r.path + r.query);
async function asOpen(ctx, label, hash, ready, { state, width = 1440, theme = "light", motion = false } = {}) {
  const view = await newView(ctx.browser, { width, theme, label, unmatched, motion, ...(state ? { fixtureState: state } : {}) });
  await view.context.addInitScript(() => { window.__downloads = []; const click = HTMLAnchorElement.prototype.click; HTMLAnchorElement.prototype.click = function () { if (this.download) { window.__downloads.push(this.download); return; } return click.call(this); }; });
  await view.page.goto(`${ctx.server.url}${hash}`, { waitUntil: "load" });
  await view.page.waitForSelector(ready, { state: "visible", timeout: 30000 });
  await settle(view.page);
  return view;
}
async function asWritesAfter(view, count, what) {
  const end = Date.now() + 8000;
  while (asWrites(view).length < count && Date.now() < end) await view.page.waitForTimeout(60);
  if (asWrites(view).length < count) throw new Error(`${what}: no request went out`);
  return asWrites(view);
}
/** Settle for a moment and say that nothing (more) went out. */
async function asNoWrites(view, what, ms = 500) { await view.page.waitForTimeout(ms); assert(asWrites(view).length === 0, `${what}: ${asWrites(view).length} request(s) went out: ${JSON.stringify(asWrites(view).map((w) => `${w.method} ${w.path}`))}`); }
const asToast = (page, text) => page.getByText(text, { exact: true }).first().waitFor({ timeout: 8000 });
const asHere = (w, method, re, what) => { assert(w.method === method && re.test(w.path), `${what}: sent ${w.method} ${w.path}`); };
/** Choose an item of a Radix select: open it, press the option. */
async function asPick(page, trigger, name) { await trigger.click(); await page.getByRole("option", { name, exact: true }).click(); }
/** Press Tab until the focus is on the element the selector names (a keyboard user's walk; fails when it is not reached). */
async function asTabTo(page, selector, max = 40) {
  for (let i = 0; i < max; i += 1) {
    if (await page.evaluate((s) => !!document.activeElement?.matches(s), selector)) return;
    await page.keyboard.press("Tab");
  }
  throw new Error(`the keyboard never reached ${selector}`);
}
const asOnly = (page, selector) => page.evaluate((s) => document.activeElement?.matches(s) ?? false, selector);
const SK_CARD = "[data-testid=skill-card]", SK_DRAWER = "[data-testid=skill-drawer]", SK_IMPORT = "[data-testid=skill-import-drawer]";
const skCard = (page, name) => page.locator(SK_CARD, { hasText: name }).first();
const SK_ID = { builtin: "s3000000-0000-4000-8000-000000000001", mine: "s3000000-0000-4000-8000-000000000002", imported: "s3000000-0000-4000-8000-000000000003", draft: "s3000000-0000-4000-8000-000000000004" };
async function skFill(page, c) {
  const d = page.locator(SK_DRAWER);
  if (c.name !== undefined) await d.locator("#skill-name").fill(c.name);
  if (c.description !== undefined) await d.locator("#skill-description").fill(c.description);
  if (c.body !== undefined) await d.locator("#skill-body").fill(c.body);
  if (c.template !== undefined) await d.locator("#skill-template").fill(c.template);
  for (const i of c.tools ?? []) await d.locator("[data-testid=skill-tool-list] li").nth(i).locator("button[role=checkbox]").click();
}
const skMenu = async (page, name, item) => { await skCard(page, name).locator("[data-testid=skill-menu]").click(); await page.locator(`[data-testid=${item}]`).click(); };

async function skillsOps(ctx) {
  const done = [];
  // 1. 新建: four cases of the old editor, each the old body character for character (enabled: true, the template null when blank, tools in the order they were ticked)
  const CASES = {
    minimal: { name: "  新技能一  ", description: "  说明一句  ", body: "步骤1\n步骤2", tools: [0] },
    withTemplate: { name: "带模板", description: "d", body: "b", template: "## 要点\n## 风险", tools: [2, 0] },
    allTools: { name: "全部工具", description: "全部", body: "x", template: "  ", tools: [0, 1, 2, 3, 4] },
    noTools: { name: "没有工具", description: "无", body: "z", tools: [] },
  };
  for (const [k, c] of Object.entries(CASES)) {
    const view = await asOpen(ctx, `skills new ${k}`, "#/assistant/skills", SK_CARD);
    try {
      const { page } = view;
      await page.locator("[data-testid=skill-new]").click(); await page.locator(SK_DRAWER).waitFor({ timeout: 8000 });
      await skFill(page, c);
      await page.locator("[data-testid=skill-save]").click();
      const [w] = await asWritesAfter(view, 1, k);
      asHere(w, "POST", /\/skills$/, k);
      assert(asBody(w) === asOld(AS.skills.create[k], "POST", /\/skills$/), `${k}: body\n  ${asBody(w)}\n  differs from the old one\n  ${asOld(AS.skills.create[k], "POST", /\/skills$/)}`);
      assert(w.body.enabled === true, `${k}: a new skill was not created enabled`);
      await page.locator(SK_DRAWER).waitFor({ state: "detached", timeout: 8000 });
      await asToast(page, "已保存。");
      await skCard(page, c.name.trim()).waitFor({ timeout: 8000 });
    } finally { await view.close(); }
  }
  done.push("4 new skills");
  // 2. 编辑 (the body has no `enabled`), and 3. a draft saved: 核对并保存 → 保存为技能 sends save_draft
  for (const [k, name, change] of [["untouched", "周日复盘", null], ["rename", "周日复盘", { name: "周日复盘 v2", description: "改过的说明" }], ["tools", "新闻去重", { tools: [0] }]]) {
    const view = await asOpen(ctx, `skills edit ${k}`, "#/assistant/skills", SK_CARD);
    try {
      const { page } = view;
      await skCard(page, name).locator("[data-testid=skill-edit]").click(); await page.locator(SK_DRAWER).waitFor({ timeout: 8000 });
      await page.waitForFunction(() => document.querySelector("#skill-name")?.value, null, { timeout: 5000 });
      assert((await page.locator(SK_DRAWER).getAttribute("data-draft")) === "false", `${k}: an own skill's editor says it is a draft`);
      if (change) await skFill(page, change);
      await page.locator("[data-testid=skill-save]").click();
      const [w] = await asWritesAfter(view, 1, k);
      asHere(w, "PATCH", /\/skills\/s3000000-0000-4000-8000-00000000000[23]$/, k);
      assert(asBody(w) === asOld(AS.skills.edit[k], "PATCH", /\/skills\//), `${k}: body ${asBody(w)} differs from the old ${asOld(AS.skills.edit[k], "PATCH", /\/skills\//)}`);
      assert(!("enabled" in w.body) && !("save_draft" in w.body), `${k}: the body carries enabled or save_draft`);
    } finally { await view.close(); }
  }
  {
    const view = await asOpen(ctx, "skills draft save", "#/assistant/skills", SK_CARD);
    try {
      const { page } = view;
      const draft = skCard(page, "估值草稿");
      assert((await draft.locator("[data-testid=skill-edit]").innerText()).trim() === "核对并保存", "the draft's main button is not 核对并保存");
      await draft.locator("[data-testid=skill-edit]").click(); await page.locator(SK_DRAWER).waitFor({ timeout: 8000 });
      assert((await page.locator("[data-testid=skill-save]").innerText()).trim() === "保存为技能", "a draft saves as 保存为技能");
      await page.locator("[data-testid=skill-save]").click();
      const [w] = await asWritesAfter(view, 1, "draft");
      asHere(w, "PATCH", /\/skills\/s3000000-0000-4000-8000-000000000004$/, "draft");
      assert(asBody(w) === asOld(AS.skills.draft, "PATCH", /\/skills\//) && w.body.save_draft === true, `draft: body ${asBody(w)}`);
    } finally { await view.close(); }
  }
  done.push("3 edits + the draft (save_draft)");
  // 4. 启用 / 停用: saved as it is flipped; only an active skill has the switch (a draft has none)
  for (const [k, name] of [["off", "周日复盘"], ["on", "新闻去重"], ["builtin", "财报速读"]]) {
    const view = await asOpen(ctx, `skills toggle ${k}`, "#/assistant/skills", SK_CARD);
    try {
      await skCard(view.page, name).locator("[data-testid=skill-switch]").click();
      const [w] = await asWritesAfter(view, 1, k);
      asHere(w, "POST", /\/skills\/s3000000-0000-4000-8000-00000000000\d\/enabled$/, k);
      assert(asBody(w) === asOld(AS.skills.toggle[k], "POST", /\/enabled$/), `${k}: body ${asBody(w)}`);
    } finally { await view.close(); }
  }
  {
    const view = await asOpen(ctx, "skills no switch", "#/assistant/skills", SK_CARD);
    try {
      assert((await skCard(view.page, "估值草稿").locator("[data-testid=skill-switch]").count()) === 0, "a draft has an on / off switch");
      assert((await skCard(view.page, "周日复盘").locator("[data-testid=skill-switch]").count()) === 1, "an active skill has no switch");
    } finally { await view.close(); }
  }
  done.push("switch both ways, none on a draft");
  // 5. 复制 and 6. 导出 (the file is <name>.md)
  {
    const view = await asOpen(ctx, "skills copy", "#/assistant/skills", SK_CARD);
    try {
      const { page } = view;
      await skMenu(page, "财报速读", "skill-copy");
      const [w] = await asWritesAfter(view, 1, "copy");
      asHere(w, "POST", /\/skills\/s3000000-0000-4000-8000-000000000001\/copy$/, "copy");
      assert(w.body === null, "a copy sends a body");
      await asToast(page, "已复制，可以在「我的」里编辑。");
      await skCard(page, "财报速读 副本").waitFor({ timeout: 8000 });
    } finally { await view.close(); }
  }
  for (const name of ["财报速读", "周日复盘"]) {
    const view = await asOpen(ctx, `skills export ${name}`, "#/assistant/skills", SK_CARD);
    try {
      const { page } = view;
      await skMenu(page, name, "skill-export");
      await page.waitForFunction(() => window.__downloads.length === 1, null, { timeout: 8000 });
      assert((await page.evaluate(() => window.__downloads[0])) === `${name}.md`, `the file is called ${await page.evaluate(() => window.__downloads[0])}`);
      assert(asReads(view, /\/skills\/[^/]+\/export$/).length === 1, "the export was not one GET");
      assert(asWrites(view).length === 0, "an export wrote something");
    } finally { await view.close(); }
  }
  done.push("copy, export (name.md)");
  // 7. 导入预览 and 8. 确认导入: the old bodies; the text is sent as typed
  {
    const view = await asOpen(ctx, "skills import", "#/assistant/skills", SK_CARD);
    try {
      const { page } = view;
      await page.locator("[data-testid=skill-import-open]").click(); await page.locator(SK_IMPORT).waitFor({ timeout: 8000 });
      await page.locator("[data-testid=skill-import-text]").fill(AS.skills.importOp.pasted.markdown);
      await page.locator("[data-testid=skill-import-preview]").click(); await page.locator("[data-testid=skill-preview]").waitFor({ timeout: 8000 });
      const [preview] = await asWritesAfter(view, 1, "preview");
      asHere(preview, "POST", /\/skills\/import\/preview$/, "preview");
      assert(asBody(preview) === asOld(AS.skills.importOp.pasted.preview, "POST", /import\/preview$/), `preview body ${asBody(preview)}`);
      await page.locator("[data-testid=skill-import-confirm]").click();
      const w = await asWritesAfter(view, 2, "import");
      asHere(w[1], "POST", /\/skills\/import$/, "import");
      assert(asBody(w[1]) === asOld(AS.skills.importOp.pasted, "POST", /\/skills\/import$/), `import body ${asBody(w[1])}`);
      await asToast(page, "已导入。");
      await skCard(page, "周报整理").waitFor({ timeout: 8000 });
    } finally { await view.close(); }
  }
  done.push("import: preview, then import");
  // 9. 删除 (press and hold): a built-in has neither 编辑 nor 删除; Esc sends nothing
  {
    const view = await asOpen(ctx, "skills delete", "#/assistant/skills", SK_CARD, { motion: true });
    try {
      const { page } = view;
      const builtin = skCard(page, "财报速读");
      assert((await builtin.locator("[data-testid=skill-edit]").count()) === 0, "a built-in skill has 编辑");
      await builtin.locator("[data-testid=skill-menu]").click();
      assert((await page.locator("[data-testid=skill-export]").count()) === 1 && (await page.locator("[data-testid=skill-copy]").count()) === 1 && (await page.locator("[data-testid=skill-delete]").count()) === 0, "a built-in skill's menu is not just 导出 and 复制");
      await page.keyboard.press("Escape");
      await skMenu(page, "周日复盘", "skill-delete");
      await dialogOf(page).waitFor({ timeout: 5000 });
      assert((await dialogOf(page).locator('[data-slot="alert-dialog-title"]').innerText()).includes("周日复盘"), "the question does not name the skill");
      await page.keyboard.press("Escape"); await dialogOf(page).waitFor({ state: "detached", timeout: 5000 });
      await asNoWrites(view, "Esc");
      await skMenu(page, "周日复盘", "skill-delete");
      await dialogOf(page).waitFor({ timeout: 5000 });
      await holdPointer(page, dialogOf(page).locator('[data-slot="hold-button"]'));
      const [w] = await asWritesAfter(view, 1, "delete");
      asHere(w, "DELETE", /\/skills\/s3000000-0000-4000-8000-000000000002$/, "delete");
      await asToast(page, "已删除。");
      await skCard(page, "周日复盘").waitFor({ state: "detached", timeout: 8000 });
    } finally { await view.close(); }
  }
  done.push("delete (hold); a built-in has no edit or delete");
  return `9 operations: ${done.join("; ")}; every request equals the old page's`;
}

async function skillsImportPreviewListsWrites(ctx) {
  const view = await asOpen(ctx, "skills import preview", "#/assistant/skills", SK_CARD);
  try {
    const { page } = view;
    await page.locator("[data-testid=skill-import-open]").click(); await page.locator(SK_IMPORT).waitFor({ timeout: 8000 });
    const confirmBtn = page.locator("[data-testid=skill-import-confirm]"), preview = page.locator("[data-testid=skill-import-preview]"), text = page.locator("[data-testid=skill-import-text]");
    assert(await confirmBtn.isDisabled(), "导入 can be pressed before there is any preview");
    assert(await preview.isDisabled(), "预览 can be pressed with an empty box");
    await text.fill(AS.skills.importOp.pasted.markdown);
    assert(await confirmBtn.isDisabled(), "导入 can be pressed with text but no preview");
    await preview.click(); await page.locator("[data-testid=skill-preview]").waitFor({ timeout: 8000 });
    assert(!(await confirmBtn.isDisabled()), "导入 cannot be pressed after the preview");
    // everything the old preview said: the name and description, every tool, the write mark on the one that writes, the sentence
    const old = AS.skills.importOp.pasted.preview.text;
    assert(old[0].startsWith("周报整理") && (await page.locator("[data-testid=skill-preview-name]").innerText()).trim() === "周报整理", "the skill's name is not in the preview");
    assert((await page.locator("[data-testid=skill-preview]").innerText()).includes("把本周的新闻和材料整理成一页周报"), "the description is not in the preview");
    const tools = await page.locator("[data-testid=skill-preview] [data-testid=skill-tool]").evaluateAll((l) => l.map((e) => [e.getAttribute("data-tool"), e.getAttribute("data-write"), e.textContent.trim()]));
    assert(tools.length === 3 && tools.map((t) => t[0]).join() === "search_news,get_market_data,save_material", `the tools: ${JSON.stringify(tools)}`);
    assert(tools.filter((t) => t[1] === "true").map((t) => t[0]).join() === "save_material" && tools.find((t) => t[0] === "save_material")[2].includes("写操作"), `the write mark: ${JSON.stringify(tools)}`);
    assert(tools.filter((t) => t[1] === "false").every((t) => !t[2].includes("写操作")), "a read tool is marked as a write");
    assert((await page.locator("[data-testid=skill-preview-write-note]").innerText()).trim() === "写操作：仍需确认卡", "the sentence for a write is missing");
    // a text changed afterwards withdraws the preview
    await text.fill(`${AS.skills.importOp.pasted.markdown}\n4. 多一步`);
    assert((await page.locator("[data-testid=skill-preview]").count()) === 0 && (await confirmBtn.isDisabled()), "the preview stayed after the text changed");
    // a skill of read tools only: no write mark, no sentence
    await text.fill(AS.skills.importOp.readOnly.markdown); await preview.click(); await page.locator("[data-testid=skill-preview]").waitFor({ timeout: 8000 });
    assert((await page.locator("[data-testid=skill-preview] [data-write=true]").count()) === 0 && (await page.locator("[data-testid=skill-preview-write-note]").count()) === 0, "a read-only skill shows a write mark or the write sentence");
    // a file is read into the box; a text that is not a skill is refused with the server's sentence and no preview
    await page.locator("[data-testid=skill-import-file]").setInputFiles({ name: "skill.md", mimeType: "text/markdown", buffer: Buffer.from(AS.skills.importOp.pasted.markdown, "utf8") });
    await page.waitForFunction((md) => document.querySelector("[data-testid=skill-import-text]").value === md, AS.skills.importOp.pasted.markdown, { timeout: 5000 });
    assert((await page.locator("[data-testid=skill-preview]").count()) === 0, "a chosen file kept the old preview");
    await text.fill("这不是技能文件"); await preview.click();
    await page.locator(`${SK_IMPORT} [role=alert]`).waitFor({ timeout: 8000 });
    assert((await page.locator(`${SK_IMPORT} [role=alert]`).first().innerText()).includes(AS.skills.importOp.refused.alert[0]), "the refusal sentence is not the old one");
    assert((await page.locator("[data-testid=skill-preview]").count()) === 0 && (await confirmBtn.isDisabled()), "a refused text has a preview");
    assert(asWrites(view).filter((w) => !/import\/preview$/.test(w.path)).length === 0, "something other than a preview was sent");
    return "导入 stays disabled until a preview of this very text exists; the preview lists all 3 tools, marks save_material 写操作 with the sentence; editing withdraws it; a read-only skill has no mark; a file fills the box; a refusal says why";
  } finally { await view.close(); }
}

async function skillsDraftLink(ctx) {
  const notes = [];
  const draftNote = AS.skills.draft.opened.note;
  for (const [label, hash] of [["new address", `#/assistant/skills/${SK_ID.draft}`], ["old address #skills/<id>", `#skills/${SK_ID.draft}`]]) {
    const view = await newView(ctx.browser, { width: 1440, theme: "light", label: `skill link ${label}`, unmatched });
    try {
      const { page } = view;
      await page.goto(`${ctx.server.url}${hash}`, { waitUntil: "load" });
      await page.locator(`${SK_DRAWER}[data-draft=true]`).waitFor({ timeout: 15000 });
      await waitHash(page, `#/assistant/skills/${SK_ID.draft}`);
      assert((await page.locator("[data-testid=skill-draft-note]").innerText()).trim() === draftNote, `${label}: the draft sentence is not "${draftNote}"`);
      assert((await page.locator("#skill-name").inputValue()) === "估值草稿", `${label}: the drawer is not that draft's`);
      assert((await page.locator("[data-testid=skill-save]").innerText()).trim() === "保存为技能", `${label}: not 保存为技能`);
      await page.locator("[data-testid=skill-cancel]").click();
      await page.locator(SK_DRAWER).waitFor({ state: "detached", timeout: 8000 });
      await waitHash(page, "#/assistant/skills");
      assert((await page.locator("[data-testid=skill-group][data-group=drafts] [data-testid=skill-group-note]").innerText()).trim() === draftNote, `${label}: the sentence above the drafts is missing`);
      notes.push(label);
    } finally { await view.close(); }
  }
  // an own skill's link opens its editor (no draft sentence); a built-in's opens none and says nothing; a missing one says 这个技能不存在。
  const own = await asOpen(ctx, "skill link own", `#/assistant/skills/${SK_ID.mine}`, `${SK_DRAWER}[data-draft=false]`);
  try { assert((await own.page.locator("#skill-name").inputValue()) === "周日复盘" && (await own.page.locator("[data-testid=skill-draft-note]").count()) === 0, "an own skill's link did not open its editor"); notes.push("own skill"); } finally { await own.close(); }
  const builtin = await asOpen(ctx, "skill link builtin", `#/assistant/skills/${SK_ID.builtin}`, SK_CARD);
  try { await builtin.page.waitForTimeout(600); assert((await builtin.page.locator(SK_DRAWER).count()) === 0 && !(await builtin.page.locator("main").innerText()).includes("这个技能不存在。"), "a built-in's link opened a drawer or said it is missing"); notes.push("built-in: nothing"); } finally { await builtin.close(); }
  const missing = await asOpen(ctx, "skill link missing", "#/assistant/skills/s3000000-0000-4000-8000-0000000000ff", SK_CARD);
  try { await missing.page.getByText("这个技能不存在。").first().waitFor({ timeout: 8000 }); assert((await missing.page.locator(SK_DRAWER).count()) === 0, "a missing skill opened a drawer"); notes.push("missing: said"); } finally { await missing.close(); }
  return `the new and the old (#skills/<id>) address open the draft's drawer with its sentence and 保存为技能, closing goes back to /assistant/skills; ${notes.slice(2).join(", ")}`;
}

async function skillsKeyboard(ctx) {
  const view = await asOpen(ctx, "skills keyboard", "#/assistant/skills", SK_CARD);
  try {
    const { page } = view;
    // 新建 → type → save, with the keyboard alone
    await page.locator("[data-testid=skill-new]").focus(); await page.keyboard.press("Enter");
    await page.locator(SK_DRAWER).waitFor({ timeout: 8000 });
    await page.waitForFunction(() => document.activeElement?.closest("[data-testid=skill-drawer]"), null, { timeout: 5000 });
    await asTabTo(page, "#skill-name"); await page.keyboard.type("键盘技能");
    await asTabTo(page, "#skill-description"); await page.keyboard.type("只用键盘建的");
    await asTabTo(page, "#skill-body"); await page.keyboard.type("第一步");
    await asTabTo(page, "#skill-template");
    await asTabTo(page, "[data-testid=skill-tool-list] button[role=checkbox]"); await page.keyboard.press("Space");
    await asTabTo(page, "[data-testid=skill-save]"); await page.keyboard.press("Enter");
    const [w] = await asWritesAfter(view, 1, "keyboard save");
    assert(asBody(w) === JSON.stringify({ name: "键盘技能", description: "只用键盘建的", body: "第一步", allowed_tools: ["get_market_data"], output_template: null, enabled: true }), `the keyboard-made skill sent ${asBody(w)}`);
    await page.locator(SK_DRAWER).waitFor({ state: "detached", timeout: 8000 });
    await skCard(page, "键盘技能").waitFor({ timeout: 8000 });
    // the card's 「…」 menu opens with Enter, Esc closes it and the focus is back on the button
    const menu = skCard(page, "周日复盘").locator("[data-testid=skill-menu]");
    await menu.focus(); await page.keyboard.press("Enter");
    await page.getByRole("menuitem", { name: "导出" }).waitFor({ timeout: 5000 });
    await page.keyboard.press("Escape");
    await page.getByRole("menuitem", { name: "导出" }).waitFor({ state: "detached", timeout: 5000 });
    await focusOn(page, menu, "the focus did not come back to 「…」");
    // an editor opened with Enter: Esc closes it and the focus is back on 编辑
    const edit = skCard(page, "周日复盘").locator("[data-testid=skill-edit]");
    await edit.focus(); await page.keyboard.press("Enter"); await page.locator(SK_DRAWER).waitFor({ timeout: 8000 });
    await page.keyboard.press("Escape"); await page.locator(SK_DRAWER).waitFor({ state: "detached", timeout: 8000 });
    await page.waitForFunction(() => document.activeElement?.getAttribute("data-testid") === "skill-edit", null, { timeout: 3000 });
    assert(asWrites(view).length === 1, "Esc saved something");
    return "新建 opened and saved from the keyboard (fields, a tool with Space, Enter on 保存); 「…」 opens with Enter and Esc returns the focus; the editor closes with Esc and the focus returns to 编辑";
  } finally { await view.close(); }
}

const MEM_ITEM = "[data-testid=memory-item]";
const memItem = (page, text) => page.locator(MEM_ITEM, { hasText: text }).first();
const REC_READS = /\/recall$/;
async function memoryOps(ctx) {
  const done = [];
  const B = AS.memory;
  // 1. 添加: the old bodies (the text's blanks become one space; 全局 is bot_id null); a blank text cannot be added at all
  for (const [k, scope, kind, text] of [["globalPref", "全局（所有 bot）", "偏好", "  金额   都用  亿美元 "], ["botInstruction", "本 bot · AppleBot", "长期指令", "只谈 AAPL"], ["aboutMe", "全局（所有 bot）", "关于我", "我在上海"]]) {
    const view = await asOpen(ctx, `memory add ${k}`, "#/assistant/memory", MEM_ITEM);
    try {
      const { page } = view;
      await asPick(page, page.locator("[data-testid=memory-add-scope]"), scope); await asPick(page, page.locator("[data-testid=memory-add-kind]"), kind);
      await page.locator("[data-testid=memory-add-text]").fill(text);
      await page.locator("[data-testid=memory-add-submit]").click();
      const [w] = await asWritesAfter(view, 1, k);
      asHere(w, "POST", /\/profile$/, k);
      assert(asBody(w) === asOld(B.add[k], "POST", /\/profile$/), `${k}: body ${asBody(w)} differs from the old ${asOld(B.add[k], "POST", /\/profile$/)}`);
      await page.waitForFunction(() => document.querySelector("[data-testid=memory-add-text]").value === "", null, { timeout: 5000 });
    } finally { await view.close(); }
  }
  {
    const view = await asOpen(ctx, "memory add blank", "#/assistant/memory", MEM_ITEM);
    try {
      const { page } = view;
      await page.locator("[data-testid=memory-add-text]").fill("   ");
      assert(await page.locator("[data-testid=memory-add-submit]").isDisabled(), "a blank text can be added");
      await page.locator("[data-testid=memory-add-text]").press("Enter");
      await asNoWrites(view, "a blank add");
      assert((await page.locator("[data-testid=memory-add-text]").getAttribute("maxlength")) === "200", "the box does not stop at 200");
    } finally { await view.close(); }
  }
  done.push("3 adds (+ blank refused)");
  // 2. 编辑: Enter saves, Esc leaves, a blank text is not saved and the box stays
  for (const [k, how, typed] of [["enter", "Enter", "  新的写法  "], ["escape", "Escape", "不会保存"], ["button", "button", "按钮保存"], ["blank", "Enter", "   "]]) {
    const view = await asOpen(ctx, `memory edit ${k}`, "#/assistant/memory", MEM_ITEM);
    try {
      const { page } = view;
      await memItem(page, "回答先给结论").locator("[data-testid=memory-edit]").click();
      const box = page.locator("[data-testid=memory-edit-input]"); await box.waitFor({ timeout: 5000 });
      assert((await box.inputValue()) === B.edit.opened.value && await box.evaluate((e) => e === document.activeElement), `${k}: the box does not open with the text, focused`);
      await box.fill(typed);
      if (how === "button") await page.locator("[data-testid=memory-save]").click(); else await box.press(how);
      if (k === "enter" || k === "button") {
        const [w] = await asWritesAfter(view, 1, k);
        asHere(w, "PATCH", /\/profile\/pf000000-0000-4000-8000-000000000002$/, k);
        assert(asBody(w) === asOld(B.edit[k], "PATCH", /\/profile\//), `${k}: body ${asBody(w)}`);
        await box.waitFor({ state: "detached", timeout: 5000 });
      } else {
        await asNoWrites(view, k);
        const open = (await page.locator("[data-testid=memory-edit-input]").count()) === 1;
        assert(open === (k === "blank"), `${k}: the box is ${open ? "still" : "no longer"} open`);
      }
    } finally { await view.close(); }
  }
  done.push("edit: Enter / 保存 save, Esc leaves, blank refused");
  // 3. 范围 (saved as chosen), 4. 确认 (only an inferred item has it), 5. 删除 (hold; an archived one too)
  for (const [k, item, to] of [["toBot", "回答先给结论", "ReportBot"], ["toGlobal", "新闻只保留", "全局"], ["botToBot", "AAPL 的服务业务", "NewsBot"]]) {
    const view = await asOpen(ctx, `memory scope ${k}`, "#/assistant/memory", MEM_ITEM);
    try {
      const { page } = view;
      await asPick(page, memItem(page, item).locator("[data-testid=memory-scope]"), to);
      const [w] = await asWritesAfter(view, 1, k);
      asHere(w, "PATCH", /\/profile\/pf000000-0000-4000-8000-00000000000\d$/, k);
      assert(asBody(w) === asOld(B.scope[k], "PATCH", /\/profile\//), `${k}: body ${asBody(w)} differs from the old ${asOld(B.scope[k], "PATCH", /\/profile\//)}`);
    } finally { await view.close(); }
  }
  {
    const view = await asOpen(ctx, "memory confirm", "#/assistant/memory", MEM_ITEM);
    try {
      const { page } = view;
      assert((await page.locator("[data-testid=memory-confirm]").count()) === B.confirm.countWithButton, `${await page.locator("[data-testid=memory-confirm]").count()} items have 确认, the old page had ${B.confirm.countWithButton}`);
      for (const el of await page.locator(MEM_ITEM).all()) assert(((await el.getAttribute("data-origin")) === "inferred") === ((await el.locator("[data-testid=memory-confirm]").count()) === 1), "确认 is not exactly on the inferred items");
      await memItem(page, "新闻只保留").locator("[data-testid=memory-confirm]").click();
      const [w] = await asWritesAfter(view, 1, "confirm");
      asHere(w, "POST", /\/profile\/pf000000-0000-4000-8000-000000000004\/confirm$/, "confirm");
      assert(w.body === null, "a confirm sends a body");
      await page.waitForFunction(() => document.querySelectorAll("[data-testid=memory-confirm]").length === 1, null, { timeout: 5000 });
    } finally { await view.close(); }
  }
  for (const [k, item, archived] of [["active", "回答先给结论", false], ["archived", "用简体中文回答", true]]) {
    const view = await asOpen(ctx, `memory delete ${k}`, "#/assistant/memory", MEM_ITEM, { motion: true });
    try {
      const { page } = view;
      if (archived) await page.locator("[data-testid=memory-archived] button").first().click();
      const row = archived ? page.locator("[data-testid=memory-archived-item]", { hasText: item }) : memItem(page, item);
      await (archived ? row.getByRole("button", { name: /^删除/ }) : row.locator("[data-testid=memory-delete]")).click();
      await dialogOf(page).waitFor({ timeout: 5000 });
      const dialog = B.del[k].dialog;
      assert((await dialogOf(page).locator('[data-slot="alert-dialog-title"]').innerText()).trim() === dialog.title && (await dialogOf(page).locator('[data-slot="alert-dialog-description"]').innerText()).trim() === dialog.description, `${k}: the question is not the old one`);
      await holdPointer(page, dialogOf(page).locator('[data-slot="hold-button"]'));
      const [w] = await asWritesAfter(view, 1, k);
      asHere(w, "DELETE", /\/profile\/pf000000-0000-4000-8000-00000000000[26]$/, k);
    } finally { await view.close(); }
  }
  done.push("scope ×3 (bot_id / null), 确认 only on inferred, delete (hold; archived too)");
  // 6. the tab is in the address; 往事 reads limit=20; 7. a search goes out when submitted, never while typing; 8. the bot filter; 9. 打开对话
  {
    const view = await asOpen(ctx, "memory recall", "#/assistant/memory", MEM_ITEM);
    try {
      const { page } = view;
      const reads = () => asReads(view, REC_READS);
      assert(reads().length === 0, "the profile tab read the past conversations");
      await page.locator("[data-testid=tab-recall]").click();
      await page.locator("[data-testid=recall-item]").first().waitFor({ timeout: 8000 });
      await page.waitForFunction(() => location.hash.endsWith("?tab=recall"), null, { timeout: 5000 });
      assert(reads().join() === `/agent-chat/recall${B.recall.enter.sent[0].query}`, `entering the tab read ${reads().join()}`);
      const box = page.locator("[data-testid=recall-query]");
      await box.pressSequentially("英伟达", { delay: 40 }); await page.waitForTimeout(700);
      assert(reads().length === 1, `typing sent ${reads().length - 1} request(s)`);
      await page.locator("[data-testid=recall-submit]").click(); await page.waitForTimeout(700);
      assert(reads().length === 2 && reads()[1] === `/agent-chat/recall${B.recall.submitButton.sent[0].query}`, `the 搜索 button: ${reads().slice(1).join()}`);
      await page.locator("[data-testid=recall-submit]").click(); await page.waitForTimeout(500);
      assert(reads().length === 2, "the same search sent again (the old page did not)");
      await box.fill("美联储"); await box.press("Enter"); await page.waitForTimeout(700);
      assert(reads().length === 3 && reads()[2] === `/agent-chat/recall${B.recall.submitEnter.sent[0].query}`, `Enter in the box: ${reads().slice(2).join()}`);
      await asPick(page, page.locator("[data-testid=recall-bot]"), "AppleBot"); await page.waitForTimeout(700);
      assert(reads().length === 4 && reads()[3] === `/agent-chat/recall${B.recall.filterWithQuery.sent[0].query}`, `the bot filter with a word: ${reads().slice(3).join()}`);
      await box.fill(""); await page.locator("[data-testid=recall-submit]").click(); await page.waitForTimeout(700);
      assert(reads()[4] === `/agent-chat/recall${B.recall.clearedWithFilter.sent[0].query}`, `a cleared word with the filter: ${reads()[4]}`);
      await asPick(page, page.locator("[data-testid=recall-bot]"), "全部 bot"); await page.waitForTimeout(700);
      assert(reads()[5] === `/agent-chat/recall${B.recall.filterCleared.sent[0].query}`, `the filter cleared: ${reads()[5]}`);
      await box.fill("无结果词"); await box.press("Enter");
      await page.locator("[data-testid=recall-empty]").waitFor({ timeout: 8000 });
      assert((await page.locator("[data-testid=recall-empty]").innerText()).includes("没有找到相关的往事。"), "the no-match sentence is missing");
      // a refresh stays on the tab
      await page.reload({ waitUntil: "load" });
      await page.locator("[data-testid=recall-item]").first().waitFor({ timeout: 15000 });
      assert((await page.locator("[data-testid=tab-recall]").getAttribute("aria-selected")) === "true", "a refresh left the 往事 tab");
    } finally { await view.close(); }
  }
  for (const [k, title, hash] of [["otherBot", "AAPL 本季服务收入", `#/chat/${BOT.applebot}`], ["defaultBot", "AAPL 服务收入与预测对比", "#/chat"], ["unowned", "可信度星级是什么", "#/chat"]]) {
    const view = await asOpen(ctx, `memory open ${k}`, "#/assistant/memory?tab=recall", "[data-testid=recall-item]");
    try {
      await view.page.locator("[data-testid=recall-item]", { hasText: title }).getByRole("button", { name: /^打开对话/ }).click();
      await waitHash(view.page, hash, 15000);
      assert(B.open[k].hash === hash, `the baseline says ${B.open[k].hash}`);
    } finally { await view.close(); }
  }
  done.push("往事: tab in the address and kept on refresh; typing sends nothing; 搜索 / Enter send once; the filter; 打开对话 ×3");
  return `9 operations: ${done.join("; ")}`;
}

/** 你的看法: the company page's card (current view, his words, the date, the folded history), the delete of one earlier version (a confirm that says it cannot be undone; one DELETE), the memory page's section with its link, and the empty states. */
async function ownerViews(ctx) {
  const view = await asOpen(ctx, "owner views company", "#/research/c/NVDA", "[data-testid=owner-view-text]", { motion: true });
  try {
    const { page } = view;
    const card = page.locator("[data-testid=owner-view]");
    assert((await page.locator("[data-testid=owner-view-text]").innerText()) === "估值太高，现在不想追", "the current view is not the active version");
    assert((await card.locator("[data-testid=owner-view-date]").innerText()).trim() === "11月8日 说的", `the date: ${await card.locator("[data-testid=owner-view-date]").innerText()}`);
    assert((await card.innerText()).includes("你的原话") && (await card.locator("[data-testid=owner-view-quote]").first().innerText()).includes("我改主意了"), "his own words are not shown under 你的原话");
    assert(await page.locator("[data-testid=owner-view-version]").count() === 0, "the history is open before it is asked for");
    await page.locator("[data-testid=owner-view-history-toggle]").click();
    const rows = await page.locator("[data-testid=owner-view-version]").evaluateAll((els) => els.map((e) => ({ status: e.getAttribute("data-status"), text: e.innerText })));
    assert(rows.length === 2 && rows[0].status === "superseded" && rows[0].text.includes("已更新") && rows[1].status === "dropped" && rows[1].text.includes("已撤回"), `history rows: ${JSON.stringify(rows)}`);
    const del = page.locator("[data-testid=owner-view-delete]").first();
    await del.click();
    const dialog = dialogOf(page);
    await dialog.waitFor({ state: "visible", timeout: 5000 });
    const said = await dialog.innerText();
    assert(said.includes("删除这条历史？") && said.includes("删除后无法恢复"), `the confirm says: ${said}`);
    await page.keyboard.press("Escape");
    await dialog.waitFor({ state: "hidden", timeout: 5000 });
    assert(count(view, "DELETE", /\/views\/[^/]+$/) === 0, "a view was deleted by pressing 删除 and cancelling");
    await del.click(); await dialog.waitFor({ state: "visible", timeout: 5000 });
    await holdPointer(page, dialog.locator("button", { hasText: "删除" }).last());
    await page.waitForFunction(() => document.querySelectorAll("[data-testid=owner-view-version]").length === 1, null, { timeout: 8000 });
    assert(count(view, "DELETE", /\/views\/[^/]+$/) === 1, "the hold did not send exactly one DELETE");
  } finally { await view.close(); }
  const memory = await asOpen(ctx, "owner views memory", "#/assistant/memory", "[data-testid=owner-view-item]");
  try {
    const { page } = memory;
    const items = await page.locator("[data-testid=owner-view-item]").evaluateAll((els) => els.map((e) => ({ symbol: e.getAttribute("data-symbol"), href: e.querySelector("[data-testid=owner-view-link]")?.getAttribute("href"), quote: !!e.querySelector("[data-testid=owner-view-quote]") })));
    assert(items.length === 3 && items.every((i) => i.quote && i.href?.endsWith(`/research/c/${i.symbol}`)), `the section: ${JSON.stringify(items)}`);
  } finally { await memory.close(); }
  const empty = await asOpen(ctx, "owner views empty", "#/assistant/memory", "[data-testid=owner-views-empty]", { state: stateNoViews() });
  try {
    assert((await empty.page.locator("[data-testid=owner-views-empty]").innerText()).includes("还没有记下对哪家公司的看法。在对话里说出你的看法，它会记下来。"), "the empty sentence is not the one in the brief");
  } finally { await empty.close(); }
  const none = await asOpen(ctx, "owner views none", "#/research/c/AAPL", "[data-testid=company-overview]");
  try {
    await none.page.waitForTimeout(500);
    assert(await none.page.locator("[data-testid=owner-view]").count() === 0, "a company with no view and no history shows a card");
  } finally { await none.close(); }
  return "NVDA: the active view, his words, 11月8日 说的, the history folded, two earlier versions (已更新, 已撤回), delete asks 删除这条历史？ / 删除后无法恢复 and sends one DELETE after a hold (none after Esc); the memory page lists 3 views with company links; empty sentence; a company with none shows no card";
}

async function memoryNotesOnce(ctx) {
  const PROFILE = AS.memory.load.paragraphs[0], SCOPE = AS.memory.load.paragraphs[1], RECALL = AS.memory.recall.load.paragraphs[0];
  const times = (text, note) => text.split(note).length - 1;
  const profile = await asOpen(ctx, "memory notes profile", "#/assistant/memory", MEM_ITEM);
  try {
    const { page } = profile;
    const text = await page.locator("main").innerText();
    assert(times(text, PROFILE) === 1 && times(text, SCOPE) === 1, `the profile tab says its sentence ${times(text, PROFILE)} times (scope sentence ${times(text, SCOPE)})`);
    assert(times(text, RECALL) === 0, "the past-conversations sentence is on the profile tab");
    assert((await page.locator("[data-testid=memory-note-profile]").innerText()).trim() === PROFILE, "the profile sentence is not the old one, word for word");
    // inferred: the mark 推断, 确认, the opinion colour; the rest: neither
    const items = await page.locator(MEM_ITEM).evaluateAll((els) => els.map((e) => ({ origin: e.getAttribute("data-origin"), badge: e.querySelector("[data-testid=memory-origin]").textContent.trim(), tone: e.querySelector("[data-testid=memory-origin] [data-slot=status-badge]").getAttribute("data-kind"), confirm: !!e.querySelector("[data-testid=memory-confirm]"), quote: !!e.querySelector("[data-testid=memory-quote]") })));
    const inferred = items.filter((i) => i.origin === "inferred");
    assert(inferred.length === 2 && inferred.every((i) => i.badge === "推断" && i.confirm && i.tone === "opinion"), `inferred items: ${JSON.stringify(inferred)}`);
    assert(items.filter((i) => i.origin !== "inferred").every((i) => !i.confirm && i.tone === "neutral" && i.badge !== "推断"), `the others: ${JSON.stringify(items.filter((i) => i.origin !== "inferred"))}`);
    assert(items.find((i) => i.origin === "manual").quote === false && items.filter((i) => i.origin !== "manual").every((i) => i.quote), "an item with no quote draws an empty quote block (or one with a quote lacks it)");
    const quote = await page.locator("[data-testid=memory-quote]").first().evaluate((e) => ({ cls: e.className, font: getComputedStyle(e).fontFamily }));
    assert(/font-quote/.test(quote.cls) && /material-fact/.test(quote.cls), `the quote is not in the fact material: ${quote.cls}`);
  } finally { await profile.close(); }
  const recall = await asOpen(ctx, "memory notes recall", "#/assistant/memory?tab=recall", "[data-testid=recall-item]");
  try {
    const text = await recall.page.locator("main").innerText();
    assert(times(text, RECALL) === 1, `the recall tab says its sentence ${times(text, RECALL)} times`);
    assert(times(text, PROFILE) === 0, "the profile sentence is on the recall tab");
    assert((await recall.page.locator("[data-testid=memory-note-recall]").innerText()).trim() === RECALL, "the recall sentence is not the old one, word for word");
    assert(text.includes(AS.memory.recall.load.paragraphs[1]), "the second recall sentence is missing");
  } finally { await recall.close(); }
  return "each tab holds its own sentence exactly once, word for word as the old page; the other tab does not; the 2 inferred items have 推断 (opinion badge) and 确认, the 4 others neither; an empty quote is not drawn; quotes are fact material";
}

async function memoryKeyboard(ctx) {
  const view = await asOpen(ctx, "memory keyboard", "#/assistant/memory", MEM_ITEM);
  try {
    const { page } = view;
    // the tabs: arrows move the focus, Enter / Space opens (the company page's tab list)
    await page.locator("[data-testid=tab-profile]").focus();
    await page.keyboard.press("ArrowRight");
    assert(await asOnly(page, "[data-testid=tab-recall]"), "ArrowRight did not move the focus to 往事");
    assert(!(await page.evaluate(() => location.hash.includes("tab=recall"))), "an arrow key opened the tab");
    await page.keyboard.press("Enter");
    await page.locator("[data-testid=recall-item]").first().waitFor({ timeout: 8000 });
    await page.waitForFunction(() => location.hash.endsWith("?tab=recall"), null, { timeout: 5000 })
      .catch(async () => { throw new Error(`[wait 1/5: the address after Enter on 往事] ?tab=recall never reached the address (it is ${await page.evaluate(() => location.hash)})`); });
    await page.keyboard.press("ArrowLeft"); await page.keyboard.press("Space");
    await page.locator(MEM_ITEM).first().waitFor({ timeout: 8000 });
    await page.waitForFunction(() => !location.hash.includes("tab="), null, { timeout: 5000 })
      .catch(async () => { throw new Error(`[wait 2/5: the address after Space on 画像] tab= never left the address (it is ${await page.evaluate(() => location.hash)})`); });
    // an item added from the keyboard: the add box, Enter
    await page.locator("[data-testid=memory-add-text]").focus(); await page.keyboard.type("键盘加的一条"); await page.keyboard.press("Enter");
    const [added] = await asWritesAfter(view, 1, "keyboard add");
    assert(asBody(added) === JSON.stringify({ kind: "preference", text: "键盘加的一条", bot_id: null }), `the keyboard add sent ${asBody(added)}`);
    // The request going out is not the add being done: the page takes the answer, reloads the list, THEN empties the box and puts the focus back in it (ProfilePanel `add`).
    // Moving on at once lets that late focus() land on the box after the keyboard has already gone to 编辑 / after the edit box has mounted, and the focus wait below never sees its box.
    // So wait for the observable end of the add: the box is empty and the new row is on the page.
    await page.waitForFunction(() => document.querySelector("[data-testid=memory-add-text]")?.value === "", null, { timeout: 5000 })
      .catch(async () => { throw new Error(`[the add being done (new wait, before wait 3/5)] the add box was never emptied after the keyboard add (it holds "${await page.locator("[data-testid=memory-add-text]").inputValue()}")`); });
    await memItem(page, "键盘加的一条").waitFor({ timeout: 5000 });
    // a row's text edited from the keyboard: 编辑 (Enter) → the box has the focus → Enter saves
    const edit = memItem(page, "回答先给结论").locator("[data-testid=memory-edit]");
    await edit.focus(); await page.keyboard.press("Enter");
    await focusOn(page, "[data-testid=memory-edit-input]", "[wait 3/5: the first edit box] Enter on 编辑 did not put the focus in the edit box");
    await page.keyboard.press("End"); await page.keyboard.type("（键盘）"); await page.keyboard.press("Enter");
    const w = await asWritesAfter(view, 2, "keyboard edit");
    assert(asBody(w[1]) === JSON.stringify({ text: "回答先给结论，再给依据；数字要带出处。（键盘）" }), `the keyboard edit sent ${asBody(w[1])}`);
    // and left with Esc
    await memItem(page, "回答先给结论").locator("[data-testid=memory-edit]").focus(); await page.keyboard.press("Enter");
    await focusOn(page, "[data-testid=memory-edit-input]", "[wait 4/5: the second edit box] Enter on 编辑 did not put the focus in the edit box");
    await page.keyboard.type("不要保存"); await page.keyboard.press("Escape");
    await page.waitForFunction(() => !document.querySelector("[data-testid=memory-edit-input]"), null, { timeout: 5000 })
      .catch(() => { throw new Error("[wait 5/5: the edit box after Esc] the edit box was still on the page 5000 ms after Esc"); });
    await page.waitForTimeout(400);
    assert(asWrites(view).length === 2, "Esc saved the edit");
    return "tabs by arrows + Enter / Space (the address follows); an item added with Enter in the box; a row edited (Enter saves) and left (Esc) from the keyboard";
  } finally { await view.close(); }
}

const NW_ROW = "[data-testid=news-row]", NW_DRAWER = "[data-testid=news-drawer]";
const nwRow = (page, id) => page.locator(NW_ROW, { has: page.locator("[data-testid=news-id]", { hasText: new RegExp(`^${id}$`) }) });
const nwMenu = async (page, id, item) => { await nwRow(page, id).locator("[data-testid=news-menu]").click(); await page.locator(`[data-testid=${item}]`).click(); };
const NW_STATE = () => stateWithNewsExtras();
/** Fill the news drawer's text fields; the three tag boxes are emptied of their first values (US, news) and filled from text, the way the old text boxes were replaced. */
async function nwFill(page, c) {
  const d = page.locator(NW_DRAWER);
  if (c.name !== undefined) await d.locator("#news-name").fill(c.name);
  if (c.id !== undefined) await d.locator("#news-id").fill(c.id);
  if (c.kind) await asPick(page, d.locator("#news-kind"), { rss: "RSS / Atom 订阅源", http_json: "HTTP JSON 接口", http_html: "HTTP HTML 列表页" }[c.kind]);
  if (c.url !== undefined) await d.locator("#news-url").fill(c.url);
  if (c.homepage !== undefined) await d.locator("#news-homepage").fill(c.homepage);
  for (const [field, id] of [["markets", "#news-markets"], ["tags", "#news-tags"], ["alternates", "#news-alternates"]]) {
    if (c[field] === undefined) continue;
    const box = d.locator(`[data-testid=news-field-${field}]`);
    while ((await box.locator('button[aria-label^="移除"]').count()) > 0) await box.locator('button[aria-label^="移除"]').first().click();
    if (c[field]) { await d.locator(id).fill(c[field]); await d.locator(id).press("Enter"); }
  }
  for (const [flag, key] of [["enabled", "enabled"], ["rea", "rea"]]) {
    if (c[flag] === undefined) continue;
    const sw = d.locator(`[data-testid=news-field-${key}]`);
    if (((await sw.getAttribute("data-state")) === "checked") !== c[flag]) await sw.click();
  }
}
const nwSave = (page) => page.locator("[data-testid=news-save]").click();

async function newsOps(ctx) {
  const B = AS.news, done = [];
  // 1. 新建 (the ID typed; a blank name is the ID) and 2. 编辑 (each source opened and saved untouched sends the old body; the ID box is locked)
  {
    const view = await asOpen(ctx, "news create", "#/assistant/news", NW_ROW);
    try {
      const { page } = view;
      await page.locator("[data-testid=news-new]").click(); await page.locator(NW_DRAWER).waitFor({ timeout: 8000 });
      await nwFill(page, { id: "new-feed", url: "https://example.test/new.xml" });
      await nwSave(page);
      const [w] = await asWritesAfter(view, 1, "create");
      asHere(w, "POST", /\/news-sources$/, "create");
      assert(asBody(w) === asOld(B.create.defaults, "POST", /\/news-sources$/), `create: body ${asBody(w)} differs from the old ${asOld(B.create.defaults, "POST", /\/news-sources$/)}`);
      await page.locator(NW_DRAWER).waitFor({ state: "detached", timeout: 8000 });
      await nwRow(page, "new-feed").waitFor({ timeout: 8000 });
    } finally { await view.close(); }
  }
  for (const id of ["wire-markets", "tech-daily", "earnings-feed", "chip-watch", "ev-weekly", "old-blog"]) {
    const view = await asOpen(ctx, `news edit ${id}`, "#/assistant/news", NW_ROW);
    try {
      const { page } = view;
      await nwMenu(page, id, "news-edit"); await page.locator(NW_DRAWER).waitFor({ timeout: 8000 });
      await page.waitForFunction(() => document.querySelector("#news-name")?.value, null, { timeout: 5000 });
      assert(await page.locator("#news-id").isDisabled(), `${id}: the ID of an existing source can be changed`);
      await nwSave(page);
      const [w] = await asWritesAfter(view, 1, id);
      asHere(w, "POST", /\/news-sources$/, id);
      assert(asBody(w) === asOld(B.edit[id], "POST", /\/news-sources$/), `${id}: body ${asBody(w)} differs from the old ${asOld(B.edit[id], "POST", /\/news-sources$/)}`);
    } finally { await view.close(); }
  }
  done.push("new + 6 untouched edits");
  // 3. 启用 / 暂停: the value that is not the current one
  for (const [k, id] of [["pause", "wire-markets"], ["enable", "old-blog"]]) {
    const view = await asOpen(ctx, `news toggle ${k}`, "#/assistant/news", NW_ROW);
    try {
      await nwRow(view.page, id).locator("[data-testid=news-switch]").click();
      const [w] = await asWritesAfter(view, 1, k);
      asHere(w, "POST", new RegExp(`/news-sources/${id}/enabled$`), k);
      assert(asBody(w) === asOld(B.toggle[k], "POST", /\/enabled$/), `${k}: body ${asBody(w)}`);
    } finally { await view.close(); }
  }
  done.push("switch both ways");
  // 4. 测试抓取: the result opens under its row, in the old words; the row's operations wait for it
  for (const id of ["wire-markets", "earnings-feed", "chip-watch", "ev-weekly", "old-blog", "tech-daily"]) {
    const view = await asOpen(ctx, `news test ${id}`, "#/assistant/news", NW_ROW);
    try {
      const { page } = view;
      await nwMenu(page, id, "news-test");
      const result = nwRow(page, id).locator("[data-testid=news-test-result]"); await result.waitFor({ timeout: 8000 });
      const [w] = await asWritesAfter(view, 1, id);
      asHere(w, "POST", new RegExp(`/news-sources/${id}/dry-run$`), id);
      assert(w.body === null, `${id}: the test sends a body`);
      const shown = (await result.innerText()).replace(/\s+/g, " ").trim();
      const old = B.test[id].shown.replace(/（(\d{4}-\d\d-\d\dT\d\d:\d\d)）/g, " $1").replace(/\s+/g, " ").replace(/ · /g, " ");
      assert(shown.replace(/\s+/g, " ") === old.replace(/\s+/g, " "), `${id}: shows "${shown}", the old row showed "${old}"`);
      const links = await result.locator("a").evaluateAll((a) => a.map((x) => [x.textContent, x.getAttribute("href"), x.target]));
      assert(JSON.stringify(links.map((l) => [l[0], l[1]])) === JSON.stringify(B.test[id].links.map((l) => [l[0], l[1]])) && links.every((l) => l[2] === "_blank"), `${id}: the sample links ${JSON.stringify(links)}`);
      assert((await nwRow(page, id).locator("[data-testid=news-test-result]").count()) === 1, `${id}: the result is not inside its row`);
    } finally { await view.close(); }
  }
  {
    const view = await asOpen(ctx, "news test busy", "#/assistant/news", NW_ROW);
    try {
      const { page } = view;
      view.mock.control.hold = (m, p) => m === "POST" && /dry-run$/.test(p);
      await nwMenu(page, "wire-markets", "news-test");
      await nwRow(page, "wire-markets").locator("[data-testid=news-probing]").waitFor({ timeout: 5000 });
      assert(await nwRow(page, "wire-markets").locator("[data-testid=news-menu]").isDisabled() && await nwRow(page, "wire-markets").locator("[data-testid=news-switch]").isDisabled(), "the row's operations are not locked while the test runs");
      assert(!(await nwRow(page, "tech-daily").locator("[data-testid=news-menu]").isDisabled()), "another row was locked too");
    } finally { await view.close(); }
  }
  done.push("6 test fetches (success, reason, code only, nothing) in the old words, links external, the row locked meanwhile");
  // 5. REA 修复: only where the source allows it; the three answers
  {
    const view = await asOpen(ctx, "news repair buttons", "#/assistant/news", NW_ROW, { state: NW_STATE() });
    try {
      const { page } = view;
      const have = [];
      for (const row of await page.locator(NW_ROW).all()) {
        const id = (await row.locator("[data-testid=news-id]").innerText()).trim();
        await row.locator("[data-testid=news-menu]").click();
        if ((await page.locator("[data-testid=news-repair]").count()) === 1) have.push(id);
        await page.keyboard.press("Escape"); await page.locator("[data-testid=news-test]").waitFor({ state: "detached", timeout: 3000 });
        const rea = (await row.locator("[data-testid=news-rea]").count()) === 1;
        assert(rea === have.includes(id), `${id}: 支持 REA 自动诊断 and the repair item disagree`);
      }
      assert(have.join() === B.repair.buttonOn.map((s) => s.replace("）", "")).join(), `REA 修复 is on ${have.join()}, the old page had it on ${B.repair.buttonOn.join()}`);
    } finally { await view.close(); }
  }
  for (const id of ["chip-watch", "ai-wire", "macro-wire"]) {
    const view = await asOpen(ctx, `news repair ${id}`, "#/assistant/news", NW_ROW, { state: NW_STATE() });
    try {
      const { page } = view;
      await nwMenu(page, id, "news-repair");
      const note = nwRow(page, id).locator("[data-testid=news-repair-note]"); await note.waitFor({ timeout: 8000 });
      const [w] = await asWritesAfter(view, 1, id);
      asHere(w, "POST", new RegExp(`/news-sources/${id}/repair$`), id);
      assert(w.body === null, `${id}: the repair sends a body`);
      const oldNote = B.repair[id].note.match(/REA (修复成功（抽样 \d+ 条有效新闻）|暂未自动修复：\S+)/)[0];
      assert((await note.innerText()).trim() === oldNote, `${id}: says "${(await note.innerText()).trim()}", the old row said "${oldNote}"`);
    } finally { await view.close(); }
  }
  done.push("REA 修复 only on the 3 repairable sources; success / code / no-code answers in the old words");
  // 6. 删除 (hold)
  {
    const view = await asOpen(ctx, "news delete", "#/assistant/news", NW_ROW, { motion: true });
    try {
      const { page } = view;
      await nwMenu(page, "ev-weekly", "news-delete");
      await dialogOf(page).waitFor({ timeout: 5000 });
      assert((await dialogOf(page).locator('[data-slot="alert-dialog-title"]').innerText()).trim() === B.del["ev-weekly"].dialog.title, "the question is not the old one");
      await holdPointer(page, dialogOf(page).locator('[data-slot="hold-button"]'));
      const [w] = await asWritesAfter(view, 1, "delete");
      asHere(w, "DELETE", /\/news-sources\/ev-weekly$/, "delete");
      await nwRow(page, "ev-weekly").waitFor({ state: "detached", timeout: 8000 });
    } finally { await view.close(); }
  }
  // 7. the push summary length
  for (const [value, label] of [["128", "短（128 tokens）"], ["512", "长（512 tokens）"], ["256", "中（256 tokens）"]]) {
    const view = await asOpen(ctx, `news push ${value}`, "#/assistant/news", NW_ROW);
    try {
      const { page } = view;
      if (value === "256") { await asPick(page, page.locator("[data-testid=news-push]"), "短（128 tokens）"); await asWritesAfter(view, 1, "push first"); view.mock.state.assistant.writes.length = 0; }
      await asPick(page, page.locator("[data-testid=news-push]"), label);
      const [w] = await asWritesAfter(view, 1, `push ${value}`);
      asHere(w, "PUT", /\/news-sources\/push-settings$/, value);
      assert(asBody(w) === asOld(B.push[value], "PUT", /push-settings$/), `${value}: body ${asBody(w)}`);
      assert((await page.locator("[data-testid=news-push]").innerText()).includes(label), "the select does not show the saved value");
    } finally { await view.close(); }
  }
  done.push("delete (hold), push length 128 / 512 / 256");
  return `7 operations: ${done.join("; ")}; every request equals the old page's`;
}

async function newsIdRule(ctx) {
  const view = await asOpen(ctx, "news id rule", "#/assistant/news", NW_ROW);
  try {
    const { page } = view;
    const d = page.locator(NW_DRAWER), id = () => d.locator("#news-id").inputValue(), err = () => d.locator("[data-testid=news-id-error]");
    await page.locator("[data-testid=news-new]").click(); await d.waitFor({ timeout: 8000 });
    // made from the name; fits the rule; follows the name until the ID is typed in; a taken one gets -2
    await d.locator("#news-name").fill("Tech Daily Brief");
    assert((await id()) === "tech-daily-brief" && /^[A-Za-z0-9._-]{2,80}$/.test(await id()), `the ID made of the name is "${await id()}"`);
    await d.locator("#news-name").fill("Markets Wire（示例）"); assert((await id()) === "markets-wire-2" || (await id()) === "markets-wire", `the ID made of 'Markets Wire（示例）' is "${await id()}"`);
    await d.locator("#news-name").fill("Tech Daily（示例）");
    assert((await id()) === "tech-daily-2", `a name whose ID is taken gave "${await id()}", not tech-daily-2`);
    // a Chinese-only name gives no ID and says so
    await d.locator("#news-name").fill("财联社电报");
    assert((await id()) === "" && (await err().innerText()).includes("请自己填一个 ID"), `a Chinese-only name: ID "${await id()}", message "${await err().count() ? await err().innerText() : ""}"`);
    // typing in the ID box ends the following
    await d.locator("#news-id").fill("my-own-id"); await d.locator("#news-name").fill("Another Name");
    assert((await id()) === "my-own-id", "the ID still followed the name after the reader typed one");
    // wrong IDs are said at once and nothing is sent
    await d.locator("#news-url").fill("https://example.test/x.xml");
    for (const bad of ["a", "bad id", "新闻源", "a/b"]) {
      await d.locator("#news-id").fill(bad);
      assert((await err().innerText()).trim() === AS.news.createRefused.idOne.alert[0], `"${bad}": the message is "${await err().count() ? await err().innerText() : ""}"`);
      await nwSave(page); await asNoWrites(view, `ID "${bad}"`, 300);
    }
    // an ID that is already a source's is refused (the old page overwrote it quietly)
    await d.locator("#news-id").fill("wire-markets");
    assert((await err().innerText()).includes("已经有这个 ID 的新闻源了"), "a taken ID is not said");
    await nwSave(page); await asNoWrites(view, "a taken ID", 400);
    // the URL rule, and 81 typed characters stop at 80 (a legal ID, as in the old page)
    await d.locator("#news-id").fill("good-id"); await d.locator("#news-url").fill("ftp://example.test/x");
    await nwSave(page);
    assert((await d.locator("[data-testid=news-url-error]").innerText()).trim() === AS.news.createRefused.urlFtp.alert[0], "the URL sentence is not the old one");
    await asNoWrites(view, "a bad URL", 300);
    await d.locator("#news-url").fill("https://example.test/x.xml");
    await d.locator("#news-id").fill("x".repeat(81));
    assert((await id()).length === 80, `81 typed characters gave ${(await id()).length}`);
    await nwSave(page);
    const [w] = await asWritesAfter(view, 1, "the legal 80-character ID");
    assert(w.body.id === "x".repeat(80), "the 80-character ID was not sent");
    // an existing source's ID box is locked
    await page.locator(NW_DRAWER).waitFor({ state: "detached", timeout: 8000 });
    await nwMenu(page, "tech-daily", "news-edit"); await d.waitFor({ timeout: 8000 });
    assert(await d.locator("#news-id").isDisabled(), "the ID of an existing source can be changed");
    return "the ID follows the name (tech-daily-brief; -2 when taken; empty with the sentence for a Chinese name) until typed in; a, 'bad id', 新闻源, a/b, an existing ID and a bad URL are said at once and send nothing; 81 characters stop at 80; an existing source's ID is locked";
  } finally { await view.close(); }
}

async function newsTagsBody(ctx) {
  const B = AS.news, notes = [];
  const create = async (k, c) => {
    const view = await asOpen(ctx, `news tags ${k}`, "#/assistant/news", NW_ROW);
    try {
      const { page } = view;
      await page.locator("[data-testid=news-new]").click(); await page.locator(NW_DRAWER).waitFor({ timeout: 8000 });
      await nwFill(page, c); await nwSave(page);
      const [w] = await asWritesAfter(view, 1, k);
      assert(asBody(w) === asOld(B.create[k], "POST", /\/news-sources$/), `${k}: body\n  ${asBody(w)}\n  differs from the old\n  ${asOld(B.create[k], "POST", /\/news-sources$/)}`);
      assert(Array.isArray(w.body.markets) && Array.isArray(w.body.tags) && Array.isArray(w.body.alternates) && w.body.markets.every((m) => m === m.toUpperCase()), `${k}: the lists are not arrays or the markets are not in capitals`);
      notes.push(k);
    } finally { await view.close(); }
  };
  // markets in capitals, split from pasted text; the three lists are arrays; homepage only when filled; language zh-CN; name blank = the ID
  await create("everything", { name: "完整源", id: "  full-source  ", kind: "http_json", url: "  https://example.test/full.json  ", homepage: " https://example.test/ ", markets: "us, cn  hk，jp、sg", tags: "macro flash,，ai、 earnings", alternates: "https://a.test/x.xml, https://b.test/y.xml，https://c.test/z", rea: false, enabled: false });
  await create("html", { id: "html.src_2", kind: "http_html", url: "HTTPS://example.test/list", markets: "", tags: "", rea: true });
  await create("defaults", { id: "new-feed", url: "https://example.test/new.xml" });
  // editing: the old language kept (en), the homepage left out when emptied, the lists replaced
  {
    const view = await asOpen(ctx, "news tags edit", "#/assistant/news", NW_ROW);
    try {
      const { page } = view;
      await nwMenu(page, "chip-watch", "news-edit"); await page.locator(NW_DRAWER).waitFor({ timeout: 8000 });
      await page.waitForFunction(() => document.querySelector("#news-name")?.value, null, { timeout: 5000 });
      await nwFill(page, { name: "芯片观察（改名）", markets: "us, tw", tags: "semis", alternates: "https://alt.test/a.xml", homepage: "", rea: false });
      await nwSave(page);
      const [w] = await asWritesAfter(view, 1, "edit");
      assert(asBody(w) === asOld(B.edit.changed, "POST", /\/news-sources$/), `edit: body ${asBody(w)} differs from the old ${asOld(B.edit.changed, "POST", /\/news-sources$/)}`);
      assert(w.body.language === "en" && !("homepage" in w.body), "edit: language is not kept or the emptied homepage is sent");
      notes.push("edit (language en kept, homepage left out)");
    } finally { await view.close(); }
  }
  // a pasted list becomes separate tags; a tag has its own remove button
  {
    const view = await asOpen(ctx, "news tags paste", "#/assistant/news", NW_ROW);
    try {
      const { page } = view;
      await page.locator("[data-testid=news-new]").click(); await page.locator(NW_DRAWER).waitFor({ timeout: 8000 });
      const box = page.locator("[data-testid=news-field-markets]");
      await box.locator("input").evaluate((el) => { const data = new DataTransfer(); data.setData("text", "cn, hk"); el.dispatchEvent(new ClipboardEvent("paste", { clipboardData: data, bubbles: true, cancelable: true })); });
      await page.waitForFunction(() => [...document.querySelectorAll("[data-testid=news-field-markets] [data-tag]")].map((e) => e.getAttribute("data-tag")).join() === "US,CN,HK", null, { timeout: 5000 });
      notes.push("paste 'cn, hk' → CN, HK");
    } finally { await view.close(); }
  }
  return `markets / tags / spare addresses typed or pasted into the tag boxes send the old arrays (markets in capitals), body for body: ${notes.join("; ")}`;
}

async function newsHealthNotColorOnly(ctx) {
  const view = await asOpen(ctx, "news health", "#/assistant/news", NW_ROW, { state: NW_STATE() });
  try {
    const { page } = view;
    const rows = await page.locator(NW_ROW).evaluateAll((els) => els.map((e) => ({ id: e.querySelector("[data-testid=news-id]").textContent.trim(), health: e.querySelector("[data-testid=news-health]").getAttribute("data-health"), text: e.querySelector("[data-testid=news-health]").textContent.trim(), dotHidden: e.querySelector("[data-testid=news-health] > span")?.getAttribute("aria-hidden"), error: e.querySelector("[data-testid=news-last-error]")?.textContent.trim() ?? null })));
    assert(rows.length === 9, `${rows.length} rows, expected 9`);
    const words = { ok: "健康", degraded: "降级", failed: "异常" };
    for (const r of rows) {
      assert(r.text.length > 0, `${r.id}: the health has no words`);
      assert(r.text === (words[r.health] ?? r.health), `${r.id}: "${r.text}" for health ${r.health}`);
      assert(r.dotHidden === "true", `${r.id}: the dot is not marked decoration`);
    }
    assert(rows.find((r) => r.id === "odd-state").text === "unknown", "a health value the page does not know is not shown as the server gave it");
    const errs = Object.fromEntries(rows.filter((r) => r.error).map((r) => [r.id, r.error]));
    assert(JSON.stringify(errs) === JSON.stringify({ "chip-watch": "最近错误 parse_changed", "ev-weekly": "最近错误 http_503", "ai-wire": "最近错误 feed_moved", "macro-wire": "最近错误 timeout" }), `the last errors: ${JSON.stringify(errs)}`);
    return "all 9 rows say their health in words (健康 / 降级 / 异常, an unknown value as given), the dot is decoration; the 4 last errors are shown as the server gave them";
  } finally { await view.close(); }
}

async function newsKeyboard(ctx) {
  const view = await asOpen(ctx, "news keyboard", "#/assistant/news", NW_ROW);
  try {
    const { page } = view;
    // a row's 「…」 menu with the keyboard: Enter opens, the arrows choose, Enter does it
    const menu = nwRow(page, "tech-daily").locator("[data-testid=news-menu]");
    await menu.focus(); await page.keyboard.press("Enter");
    await page.getByRole("menuitem", { name: "测试抓取" }).waitFor({ timeout: 5000 });
    await page.keyboard.press("ArrowDown"); 
    await page.keyboard.press("Escape"); await page.getByRole("menuitem", { name: "测试抓取" }).waitFor({ state: "detached", timeout: 5000 });
    await focusOn(page, menu, "Esc did not return the focus to 「…」");
    await page.keyboard.press("Enter"); await page.getByRole("menuitem", { name: "测试抓取" }).waitFor({ timeout: 5000 });
    await page.getByRole("menuitem", { name: "测试抓取" }).focus(); await page.keyboard.press("Enter");
    const [t] = await asWritesAfter(view, 1, "keyboard test");
    asHere(t, "POST", /\/news-sources\/tech-daily\/dry-run$/, "keyboard test");
    // the new-source drawer, every field and all three tag boxes, then 保存
    await page.locator("[data-testid=news-new]").focus(); await page.keyboard.press("Enter");
    await page.locator(NW_DRAWER).waitFor({ timeout: 8000 });
    await page.waitForFunction(() => document.activeElement?.closest("[data-testid=news-drawer]"), null, { timeout: 5000 });
    await asTabTo(page, "#news-name"); await page.keyboard.type("Keyboard Feed");
    await asTabTo(page, "#news-id");
    await asTabTo(page, "#news-kind"); await page.keyboard.press("Enter"); await page.getByRole("option", { name: "HTTP JSON 接口", exact: true }).click();
    await asTabTo(page, "#news-url"); await page.keyboard.type("https://example.test/kb.json");
    await asTabTo(page, "#news-homepage"); await page.keyboard.type("https://example.test/");
    await asTabTo(page, "#news-markets"); await page.keyboard.type("jp"); await page.keyboard.press("Enter");
    await asTabTo(page, "#news-tags"); await page.keyboard.type("kb"); await page.keyboard.press("Enter");
    await asTabTo(page, "#news-alternates"); await page.keyboard.type("https://alt.test/kb.json"); await page.keyboard.press("Enter");
    await asTabTo(page, "#news-enabled"); await page.keyboard.press("Space");
    await asTabTo(page, "[data-testid=news-save]"); await page.keyboard.press("Enter");
    const w = await asWritesAfter(view, 2, "keyboard create");
    assert(asBody(w[1]) === JSON.stringify({ id: "keyboard-feed", name: "Keyboard Feed", kind: "http_json", url: "https://example.test/kb.json", homepage: "https://example.test/", language: "zh-CN", markets: ["US", "JP"], tags: ["news", "kb"], alternates: ["https://alt.test/kb.json"], rea_repair: true, enabled: false }), `the keyboard-made source sent ${asBody(w[1])}`);
    await page.locator(NW_DRAWER).waitFor({ state: "detached", timeout: 8000 });
    await nwRow(page, "keyboard-feed").waitFor({ timeout: 8000 });
    // Esc closes a drawer and returns the focus to the button that opened it
    await page.locator("[data-testid=news-new]").focus(); await page.keyboard.press("Enter"); await page.locator(NW_DRAWER).waitFor({ timeout: 8000 });
    await page.keyboard.press("Escape"); await page.locator(NW_DRAWER).waitFor({ state: "detached", timeout: 8000 });
    await page.waitForFunction(() => document.activeElement?.getAttribute("data-testid") === "news-new", null, { timeout: 3000 });
    return "a row's 「…」 opens with Enter, Esc returns the focus, 测试抓取 runs from the menu; the new-source drawer is filled with the keyboard alone (name, kind list, URL, homepage, the three tag boxes, a switch) and saved with Enter; Esc closes a drawer and returns the focus";
  } finally { await view.close(); }
}

const KN_DOC = "[data-testid=knowledge-doc]";
const KN_STATE = () => stateWithKnowledgeCandidates();
const knDoc = (page, text) => page.locator(KN_DOC, { hasText: text }).first();
const SOURCE_LABEL = { faq: "常见问题", upload: "我的上传材料", sec: "已保存 / 已获取 SEC 摘录", analysis: "已保存 AI 分析" };
const knUploads = (view) => (view.mock.state.materialPosts ?? []).filter((p) => p.kind === "upload");
async function knFillUpload(page, c) {
  await page.locator("#knowledge-upload-symbol").fill(c.symbol);
  await page.locator("[data-testid=knowledge-upload-title]").fill(c.title);
  await page.locator("[data-testid=knowledge-upload-url]").fill(c.url);
  await page.locator("[data-testid=knowledge-upload-time]").fill(c.published);
  await page.locator("[data-testid=knowledge-upload-reason]").fill(c.reason);
  await page.locator("input[data-testid=upload-file]").setInputFiles({ name: c.file.name, mimeType: c.file.mimeType, buffer: Buffer.from(c.file.text, "utf8") });
}
async function knowledgeOps(ctx) {
  const B = AS.knowledge, done = [];
  // 1. 上传材料: the old multipart fields, with the fixed 3 stars and "medium"; the button waits for a file, title, link and reason; after it the source is 我的上传材料 and its material is loaded
  const UP = {
    markdown: { symbol: "aapl", title: "供应链报道", url: "https://example.test/report", published: "2026-11-10T09:30", reason: "一手采访", file: { name: "report.md", mimeType: "text/markdown", text: "# 报道\n正文" } },
    pdf: { symbol: "NVDA", title: "PDF 材料", url: "https://example.test/p.pdf", published: "2026-01-02T00:00", reason: "交叉验证", file: { name: "deck.pdf", mimeType: "application/pdf", text: "%PDF-1.4 fake" } },
  };
  for (const [k, c] of Object.entries(UP)) {
    const view = await asOpen(ctx, `knowledge upload ${k}`, "#/assistant/knowledge", KN_DOC);
    try {
      const { page } = view;
      const submit = page.locator("[data-testid=knowledge-upload-submit]");
      assert(await submit.isDisabled(), `${k}: 上传材料 can be pressed with nothing filled in`);
      await knFillUpload(page, c);
      assert(!(await submit.isDisabled()), `${k}: 上传材料 cannot be pressed with everything filled in`);
      await submit.click();
      await page.waitForFunction(() => document.querySelector("[data-testid=knowledge-importable]"), null, { timeout: 10000 });
      const [post] = knUploads(view);
      const old = B.upload[k].sent[0];
      assert(post && post.path === `/uploaded-evidence/${old.path.split("/").pop()}` && post.session === true, `${k}: the upload went to ${post?.path}`);
      assert(JSON.stringify(post.fields) === JSON.stringify(old.fields), `${k}: fields\n  ${JSON.stringify(post.fields)}\n  differ from the old\n  ${JSON.stringify(old.fields)}`);
      assert(post.fields.credibility_stars === "3" && post.fields.impact_severity === "medium", `${k}: the fixed stars / impact are ${post.fields.credibility_stars} / ${post.fields.impact_severity}`);
      assert(asReads(view, /\/knowledge\/importable\/upload$/).join() === `/knowledge/importable/upload${B.upload[k].sent[1].query}`, `${k}: the material read after it was ${asReads(view, /importable/).join()}`);
      assert((await page.locator("#knowledge-source").innerText()).includes("我的上传材料"), `${k}: the source did not change to 我的上传材料`);
      await asToast(page, "上传已保存；请选择材料并导入知识库");
    } finally { await view.close(); }
  }
  {
    const view = await asOpen(ctx, "knowledge upload time", "#/assistant/knowledge", KN_DOC);
    try {
      const { page } = view;
      await knFillUpload(page, { ...UP.markdown, published: "" });
      await page.locator("[data-testid=knowledge-upload-submit]").click();
      await page.getByText(B.upload.invalidTime.alert[0].replace(/重试$/, ""), { exact: false }).first().waitFor({ timeout: 5000 });
      assert(knUploads(view).length === 0, "an upload with no valid time went out");
    } finally { await view.close(); }
  }
  done.push("upload ×2 (fields, 3 stars, medium) + invalid time");
  // 2. 载入可选材料 for each source and code, 3. 导入所选 (the ids in the order ticked)
  for (const src of ["faq", "upload", "sec", "analysis"]) {
    const view = await asOpen(ctx, `knowledge load ${src}`, "#/assistant/knowledge", KN_DOC);
    try {
      const { page } = view;
      await asPick(page, page.locator("#knowledge-source"), SOURCE_LABEL[src]);
      await page.locator("#knowledge-import-symbol").fill("msft");
      await page.locator("[data-testid=knowledge-load]").click();
      await page.locator("[data-testid=knowledge-importable]").waitFor({ timeout: 8000 });
      assert(asReads(view, /\/knowledge\/importable\//).join() === `/knowledge/importable/${src}${B.importable[src].sent[0].query}`, `${src}: read ${asReads(view, /importable/).join()}`);
      assert((await page.locator("#knowledge-upload-symbol").inputValue()) === "MSFT", `${src}: the code is not shared by the two forms`);
    } finally { await view.close(); }
  }
  {
    const view = await asOpen(ctx, "knowledge import", "#/assistant/knowledge", KN_DOC);
    try {
      const { page } = view;
      await page.locator("[data-testid=knowledge-load]").click(); await page.locator("[data-testid=knowledge-importable]").waitFor({ timeout: 8000 });
      assert((await page.locator("[data-testid=knowledge-import]").isDisabled()), "导入所选 can be pressed with nothing ticked");
      const boxes = page.locator("[data-testid=knowledge-importable-item]");
      await boxes.nth(1).click(); await boxes.nth(0).click();
      assert((await page.locator("[data-testid=knowledge-import]").innerText()).includes("2"), "the import button does not count the 2 ticked");
      await page.locator("[data-testid=knowledge-import]").click();
      const [w] = await asWritesAfter(view, 1, "import");
      asHere(w, "POST", /\/knowledge\/import$/, "import");
      assert(asBody(w) === asOld(B.importOp.two, "POST", /\/knowledge\/import$/), `import body ${asBody(w)}`);
      await asToast(page, "接收 2 份材料，生成 10 个块");
      await page.waitForFunction(() => document.querySelectorAll("[data-testid=knowledge-doc]").length === 4, null, { timeout: 8000 });
      // nothing on the page promises that the import is searchable now: the status is the server's word
      const text = await page.locator("main").innerText();
      assert(!/已可检索|已生效|立即可检索|立即可用|可以检索了/.test(text), `the page promises searchability: ${text.match(/已可检索|已生效|立即可检索|立即可用|可以检索了/)}`);
      assert((await knDoc(page, "AAPL 渠道调研纪要").locator("[data-testid=knowledge-doc-status]").innerText()).trim() === "pending", "the status of a new import is not shown as the server gave it (pending)");
    } finally { await view.close(); }
  }
  done.push("4 sources × load, import in the ticked order, no promise of searchability");
  // 4. 运行索引
  {
    const view = await asOpen(ctx, "knowledge index", "#/assistant/knowledge", KN_DOC);
    try {
      await view.page.locator("[data-testid=knowledge-index]").click();
      const [w] = await asWritesAfter(view, 1, "index");
      asHere(w, "POST", /\/knowledge\/index$/, "index");
      assert(asBody(w) === asOld(B.index, "POST", /\/knowledge\/index$/), `index body ${asBody(w)}`);
      await asToast(view.page, "索引完成 3，失败 1");
    } finally { await view.close(); }
  }
  // 5. 检索测试: the kind comes from the source, 常见问题 sends no code; the two inputs are shown on the card itself
  for (const [key, src, symbol] of [["upload-AAPL", "upload", "AAPL"], ["faq-AAPL", "faq", "AAPL"], ["analysis-TSLA", "analysis", "TSLA"], ["sec-NVDA", "sec", "NVDA"]]) {
    const view = await asOpen(ctx, `knowledge retrieval ${key}`, "#/assistant/knowledge", KN_DOC);
    try {
      const { page } = view;
      await asPick(page, page.locator("#knowledge-source"), SOURCE_LABEL[src]); await page.locator("#knowledge-import-symbol").fill(symbol);
      assert((await page.locator("[data-testid=knowledge-retrieval-source]").innerText()).trim() === SOURCE_LABEL[src], `${key}: the retrieval card does not show its source`);
      assert((await page.locator("[data-testid=knowledge-retrieval-symbol]").innerText()).trim() === (src === "faq" ? "不带代码" : symbol), `${key}: the retrieval card does not show its code`);
      assert(await page.locator("[data-testid=knowledge-test]").isDisabled(), `${key}: 测试检索 can be pressed with no query`);
      assert((await page.locator("[data-testid=knowledge-query]").getAttribute("maxlength")) === "800", "the query box does not stop at 800");
      await page.locator("[data-testid=knowledge-query]").fill("服务收入");
      await page.locator("[data-testid=knowledge-test]").click();
      const [w] = await asWritesAfter(view, 1, key);
      asHere(w, "POST", /\/knowledge\/retrieval-test$/, key);
      assert(asBody(w) === asOld(B.retrieval[key], "POST", /retrieval-test$/), `${key}: body ${asBody(w)} differs from the old ${asOld(B.retrieval[key], "POST", /retrieval-test$/)}`);
      await page.locator("[data-testid=knowledge-result]").waitFor({ timeout: 8000 });
      assert((await page.locator("[data-testid=knowledge-result]").innerText()) === B.retrieval[key].pre, `${key}: the result is not the old JSON text`);
      await asToast(page, "已通过当前权限执行真实知识检索");
    } finally { await view.close(); }
  }
  done.push("index, retrieval ×4 (kind from the source; the two inputs shown on the card)");
  // 6. a document's chunks; 7. 重试; 8. 撤回 (disabled once withdrawn)
  {
    const view = await asOpen(ctx, "knowledge docs", "#/assistant/knowledge", KN_DOC, { state: KN_STATE() });
    try {
      const { page } = view;
      const rows = await page.locator(KN_DOC).evaluateAll((els) => els.map((e) => e.innerText.replace(/\s+/g, " ")));
      const docs = view.mock.state.assistant.docs;
      // P9.1: the observed time is the site's short date (2026年10月31日), the backend's own string stays in <time dateTime> and title; a document with none says 观察时间未知.
      const shortDate = (iso) => new Intl.DateTimeFormat("zh-CN", { year: "numeric", month: "short", day: "numeric", timeZone: "UTC" }).format(new Date(iso));
      docs.forEach((d, i) => { for (const part of [d.title, d.symbol || "FAQ", d.source_type, d.status, `${d.chunks} 块`, d.observed_at ? shortDate(d.observed_at) : "观察时间未知", d.owner_scope]) assert(rows[i].includes(part), `row ${i} "${rows[i]}" lacks "${part}"`); });
      for (const [i, d] of docs.entries()) if (d.observed_at) {
        const t = page.locator(KN_DOC).nth(i).locator("time");
        assert((await t.count()) === 1 && (await t.getAttribute("datetime")) === d.observed_at && (await t.getAttribute("title")) === d.observed_at, `row ${i}: the observed time is not a <time> carrying the backend's string ${d.observed_at}`);
      }
      const opener = knDoc(page, "AAPL 10-Q").locator("[data-testid=knowledge-doc-open]");
      await opener.click(); await page.locator("[data-testid=knowledge-chunk]").first().waitFor({ timeout: 8000 });
      assert(asReads(view, /\/chunks$/).join() === B.chunks.source.sent[0].path.replace(/^\/agent-chat/, ""), `the chunks read ${asReads(view, /chunks/).join()}`);
      const drawer = page.locator("[data-testid=knowledge-drawer]");
      const text = (await drawer.innerText()).replace(/\s+/g, " ");
      assert(text.includes("AAPL 10-Q（2026 财年第四季度）") && text.includes("保存的原文") && text.includes("文本块 · 3") && text.includes("1 · 第 1 节 · indexed") && text.includes("2 · 正文 · indexed"), `the drawer: ${text}`);
      assert((await drawer.locator("a").first().getAttribute("href")) === B.chunks.source.link[0][1], "the source link is not the old one");
      await page.keyboard.press("Escape"); await drawer.waitFor({ state: "detached", timeout: 5000 });
      await page.waitForFunction(() => document.activeElement?.getAttribute("data-testid") === "knowledge-doc-open" && document.activeElement.closest("[data-testid=knowledge-doc]").innerText.includes("AAPL 10-Q"), null, { timeout: 3000 });
      // an AI analysis keeps its provenance label
      await knDoc(page, "AAPL 服务业务分析").locator("[data-testid=knowledge-doc-open]").click(); await page.locator("[data-testid=knowledge-chunk]").first().waitFor({ timeout: 8000 });
      assert((await drawer.locator("[data-testid=knowledge-source-label]").innerText()).trim() === "分析文本（含 AI 派生内容）", "an AI analysis's text is not labelled 分析文本（含 AI 派生内容）");
      await page.keyboard.press("Escape"); await drawer.waitFor({ state: "detached", timeout: 5000 });
      // 重试 and 撤回
      await knDoc(page, "AAPL 10-Q").locator("[data-testid=knowledge-retry]").click();
      let w = await asWritesAfter(view, 1, "retry");
      asHere(w[0], "POST", /\/knowledge\/documents\/kd000000-0000-4000-8000-000000000001\/retry$/, "retry");
      await asToast(page, "已重新排入索引队列");
      await knDoc(page, "AAPL 10-Q").locator("[data-testid=knowledge-withdraw]").click();
      w = await asWritesAfter(view, 2, "withdraw");
      asHere(w[1], "POST", /\/knowledge\/documents\/kd000000-0000-4000-8000-000000000001\/withdraw$/, "withdraw");
      await asToast(page, "文档已软撤回");
      await page.waitForFunction(() => [...document.querySelectorAll("[data-testid=knowledge-doc]")].find((e) => e.innerText.includes("AAPL 10-Q")).querySelector("[data-testid=knowledge-withdraw]").disabled, null, { timeout: 8000 });
      assert(await knDoc(page, "旧上传：TSLA").locator("[data-testid=knowledge-withdraw]").isDisabled(), "撤回 is enabled on a withdrawn document");
      assert((await knDoc(page, "旧上传：TSLA").innerText()).includes("观察时间未知"), "a document with no observation time does not say 观察时间未知");
    } finally { await view.close(); }
  }
  // 9. 拒绝 and 10. 审核并排队索引
  {
    const view = await asOpen(ctx, "knowledge review", "#/assistant/knowledge", "[data-testid=knowledge-candidate]", { state: KN_STATE() });
    try {
      const { page } = view;
      const first = page.locator("[data-testid=knowledge-candidate]").first();
      assert((await first.locator("blockquote").getAttribute("class")).includes("font-quote"), "a candidate's quote is not in the fact material");
      await first.locator("[data-testid=knowledge-reject]").click();
      let w = await asWritesAfter(view, 1, "reject");
      asHere(w[0], "POST", /\/knowledge\/candidates\/kc000000-0000-4000-8000-000000000001\/review$/, "reject");
      assert(asBody(w[0]) === asOld(B.review.reject, "POST", /review$/), `reject body ${asBody(w[0])}`);
      await asToast(page, "候选已拒绝");
      await page.waitForFunction(() => document.querySelectorAll("[data-testid=knowledge-candidate]").length === 1, null, { timeout: 8000 });
      await page.locator("[data-testid=knowledge-approve]").click();
      w = await asWritesAfter(view, 2, "approve");
      assert(asBody(w[1]) === asOld(B.review.approve, "POST", /review$/) && w[1].body.approved === true, `approve body ${asBody(w[1])}`);
      await asToast(page, "已审核，已加入索引队列");
      await page.locator("[data-testid=knowledge-candidates-empty]").waitFor({ timeout: 8000 });
      assert((await page.locator("[data-testid=knowledge-candidates-empty]").innerText()).includes("没有待审核条目。"), "the empty sentence for candidates is missing");
    } finally { await view.close(); }
  }
  done.push("chunks (Esc closes, focus back on the row), retry, withdraw (then disabled), reject, approve");
  return `10 operations: ${done.join("; ")}; every request equals the old page's`;
}

async function knowledgeEntries(ctx) {
  const notes = [];
  const sidebarActive = (page) => page.locator('[data-slot="sidebar"] a[aria-current=page]').allInnerTexts().then((a) => a.map((s) => s.trim()));
  const landed = async (page, what) => {
    await waitHash(page, "#/assistant/knowledge", 10000);
    await page.locator("[data-testid=knowledge-page]").waitFor({ timeout: 15000 });
    assert((await sidebarActive(page)).includes("知识库"), `${what}: the sidebar does not highlight 知识库 (${JSON.stringify(await sidebarActive(page))})`);
    assert((await page.locator("[data-testid=settings-page]").count()) === 0, `${what}: the settings page is still on screen`);
  };
  // 1. the sidebar
  const side = await openAt(ctx, "knowledge entry sidebar", "#/assistant/bots", { ready: "[data-testid=bot-card]" });
  try { await side.page.locator('[data-slot="sidebar"] a', { hasText: "知识库" }).first().click(); await landed(side.page, "the sidebar"); notes.push("sidebar"); } finally { await side.close(); }
  // 2. P8.2: the settings pages no longer have the button.  None of the five has, in its own content (the sidebar's 知识库 row is outside it), a button or a link named 知识库 or one that goes to /assistant/knowledge.
  for (const section of ["models", "notifications", "appearance", "data", "account"]) {
    const settings = await openAt(ctx, `knowledge entry settings ${section}`, `#/settings/${section}`, { ready: `[data-testid=settings-${section}]` });
    try {
      const { page } = settings;
      await settle(page, { pinTranscript: false });
      const area = page.locator(`[data-testid=settings-${section}]`);
      assert((await area.count()) === 1 && (await area.locator("h1").count()) === 1, `${section}: the settings content area is not there (the check would read 0 of everything)`);
      const found = await area.evaluate((el) => ({ buttons: [...el.querySelectorAll("button, a, [role=button], [role=link]")].filter((x) => /知识库/.test(x.textContent + (x.getAttribute("aria-label") ?? ""))).length, links: el.querySelectorAll('a[href*="/assistant/knowledge"]').length }));
      assert(found.buttons === 0 && found.links === 0, `${section}: ${found.buttons} button/link named 知识库, ${found.links} link to /assistant/knowledge in the settings content`);
    } finally { await settings.close(); }
  }
  notes.push("none of the five settings pages has a way to the library in its content");
  // 3. the agent's open_page
  const agent = await openAt(ctx, "knowledge entry agent", "#/chat", { ready: "[data-testid=message]" });
  try { await dispatchAction(agent.page, { action: "open_page", page: "knowledge" }); await landed(agent.page, "open_page knowledge"); notes.push("open_page"); } finally { await agent.close(); }
  // 4. the page is a page of its own: no way back to the model settings, no eyebrow
  const page = await asOpen(ctx, "knowledge no back", "#/assistant/knowledge", KN_DOC);
  try {
    const text = await page.page.locator("main").innerText();
    assert(!text.includes("返回模型设置") && !text.includes("FinBot / Knowledge"), "the page still has 返回模型设置 or the eyebrow");
    assert((await page.page.locator("main h1").innerText()).trim() === "研究知识库", "the title is not 研究知识库");
    notes.push("no 返回模型设置");
  } finally { await page.close(); }
  return `the sidebar and the agent's open_page (knowledge) land on #/assistant/knowledge with 知识库 highlighted and no settings page under it; ${notes.slice(-2).join("; ")}`;
}

async function knowledgeKeyboard(ctx) {
  const view = await asOpen(ctx, "knowledge keyboard", "#/assistant/knowledge", KN_DOC, { state: KN_STATE() });
  try {
    const { page } = view;
    // a document's chunks: Enter on the title opens the drawer (the focus goes in), Esc closes it and the focus returns to that row
    const opener = knDoc(page, "AAPL 服务业务分析").locator("[data-testid=knowledge-doc-open]");
    await opener.focus(); await page.keyboard.press("Enter");
    await page.locator("[data-testid=knowledge-chunk]").first().waitFor({ timeout: 8000 });
    assert(await page.evaluate(() => !!document.activeElement?.closest("[data-testid=knowledge-drawer]")), "the focus did not go into the drawer");
    await page.keyboard.press("Escape"); await page.locator("[data-testid=knowledge-drawer]").waitFor({ state: "detached", timeout: 5000 });
    await page.waitForFunction(() => document.activeElement?.getAttribute("data-testid") === "knowledge-doc-open" && document.activeElement.closest("[data-testid=knowledge-doc]").innerText.includes("AAPL 服务业务分析"), null, { timeout: 3000 });
    // the retrieval test: type the query, Tab to the button, Enter
    await page.locator("[data-testid=knowledge-query]").focus(); await page.keyboard.type("服务收入");
    await asTabTo(page, "[data-testid=knowledge-test]"); await page.keyboard.press("Enter");
    const [w] = await asWritesAfter(view, 1, "keyboard retrieval");
    assert(asBody(w) === JSON.stringify({ kind: "material", keyword: "服务收入", symbol: "AAPL" }), `the keyboard retrieval sent ${asBody(w)}`);
    await page.locator("[data-testid=knowledge-result]").waitFor({ timeout: 8000 });
    // the source list opens with the keyboard and a choice is made with it
    await page.locator("#knowledge-source").focus(); await page.keyboard.press("Enter");
    await page.getByRole("option", { name: "常见问题", exact: true }).focus(); await page.keyboard.press("Enter");
    await page.waitForFunction(() => document.querySelector("[data-testid=knowledge-retrieval-symbol]").textContent.trim() === "不带代码", null, { timeout: 5000 });
    return "a document's chunks open with Enter (focus goes into the drawer) and Esc closes them with the focus back on that row; the retrieval test is typed and run from the keyboard; the source list is chosen with the keyboard and the retrieval card follows";
  } finally { await view.close(); }
}

async function assistantNoLegacy(ctx) {
  const OLD = [".personal-page", ".personal-card", ".personal-badge", ".personal-grid", ".memory-panel", ".memory-list", ".memory-layer", ".memory-layer-title", ".memory-line", ".memory-actions", ".memory-add", ".memory-edit", ".memory-scope", ".memory-search", ".memory-tabs", ".memory-quote", ".memory-archived", ".skill-group", ".skill-card", ".skill-tools", ".skill-editor", ".skill-import", ".skill-preview", ".skill-tool-list",
    ".knowledge-admin", ".knowledge-import-card", ".knowledge-controls", ".knowledge-select-list", ".knowledge-list", ".knowledge-doc-row", ".knowledge-doc-main", ".knowledge-candidate", ".knowledge-drawer-backdrop", ".knowledge-chunk", ".knowledge-status", ".knowledge-error", ".knowledge-retrieval-result",
    ".task-form", ".task-form-row", ".bot-tool", ".section-tabs", ".origin-inferred", ".secondary-action", ".primary-action", ".fine-print", ".workspace", ".workspace-heading", ".eyebrow"].join(", ");
  const SCOPE = "main, [data-testid=skill-drawer], [data-testid=skill-import-drawer], [data-testid=news-drawer], [data-testid=knowledge-drawer]";
  const count = (page) => page.evaluate(({ old, scope }) => ({
    legacy: document.querySelectorAll("[data-legacy]").length,
    old: [...document.querySelectorAll(old)].filter((el) => el.closest(scope)).map((el) => el.className).length,
    native: document.querySelectorAll(`:is(${scope}) select`).length,
    small: [...document.querySelectorAll(`:is(${scope}) *`)].filter((el) => [...el.childNodes].some((n) => n.nodeType === 3 && n.textContent.trim()) && parseFloat(getComputedStyle(el).fontSize) < 12).length,
  }), { old: OLD, scope: SCOPE });
  const check = async (page, what) => {
    const found = await count(page);
    assert(found.legacy === 0, `${what}: ${found.legacy} data-legacy element(s)`);
    assert(found.old === 0, `${what}: ${found.old} element(s) with an old class`);
    assert(found.native === 0, `${what}: ${found.native} native <select>`);
    assert(found.small === 0, `${what}: ${found.small} text element(s) under 12px`);
  };
  const seen = [];
  const run = async (label, hash, ready, steps, opts = {}) => {
    const view = await asOpen(ctx, `no legacy ${label}`, hash, ready, opts);
    try { await check(view.page, label); if (steps) await steps(view.page, (what) => check(view.page, `${label} · ${what}`)); seen.push(label); } finally { await view.close(); }
  };
  await run("技能", "#/assistant/skills", SK_CARD, async (page, again) => {
    await page.locator("[data-testid=skill-new]").click(); await page.locator(SK_DRAWER).waitFor(); await again("编辑抽屉"); await page.keyboard.press("Escape"); await page.locator(SK_DRAWER).waitFor({ state: "detached" });
    await page.locator("[data-testid=skill-import-open]").click(); await page.locator(SK_IMPORT).waitFor(); await page.locator("[data-testid=skill-import-text]").fill(IMPORT_SAMPLE); await page.locator("[data-testid=skill-import-preview]").click(); await page.locator("[data-testid=skill-preview]").waitFor(); await again("导入预览");
  });
  await run("技能 :skillId", `#/assistant/skills/${SK_ID.draft}`, `${SK_DRAWER}[data-draft=true]`);
  await run("技能（空）", "#/assistant/skills", "[data-testid=skills-empty]", null, { state: stateAssistantEmpty() });
  await run("记忆", "#/assistant/memory", MEM_ITEM, async (page, again) => { await page.locator("[data-testid=memory-archived] button").first().click(); await again("已归档展开"); await memItem(page, "回答先给结论").locator("[data-testid=memory-edit]").click(); await again("行内编辑"); });
  await run("记忆 ?tab=recall", "#/assistant/memory?tab=recall", "[data-testid=recall-item]");
  await run("记忆（空）", "#/assistant/memory", "[data-testid=memory-empty]", null, { state: stateAssistantEmpty() });
  await run("新闻源", "#/assistant/news", NW_ROW, async (page, again) => {
    await nwMenu(page, "wire-markets", "news-test"); await nwRow(page, "wire-markets").locator("[data-testid=news-test-result]").waitFor(); await again("测试结果展开");
    await page.locator("[data-testid=news-new]").click(); await page.locator(NW_DRAWER).waitFor(); await again("新建抽屉");
  });
  await run("新闻源（空）", "#/assistant/news", "[data-testid=news-empty]", null, { state: stateAssistantEmpty() });
  await run("知识库", "#/assistant/knowledge", KN_DOC, async (page, again) => { await knDoc(page, "AAPL 10-Q").locator("[data-testid=knowledge-doc-open]").click(); await page.locator("[data-testid=knowledge-chunk]").first().waitFor(); await again("分块抽屉"); }, { state: KN_STATE() });
  await run("知识库（空）", "#/assistant/knowledge", "[data-testid=knowledge-docs-empty]", null, { state: stateAssistantEmpty() });
  // the control (P9.1: injected, since no product page keeps the marker): a probe with the marker, an old class, a native <select> and 11px text is read by the same `count`, and reads 0 once removed
  const control = await asOpen(ctx, "no legacy control", "#/assistant/skills", SK_CARD);
  try { assertProbe("assistant-no-legacy", ["legacy", "old", "native", "small"], await probeControl(control.page, count, "personal-page")); } finally { await control.close(); }
  return `${seen.length} addresses / states (skills incl. :skillId and its two drawers, memory both tabs, news with a test result and the drawer, knowledge with the chunk drawer, each page empty): 0 data-legacy, 0 old classes, 0 native <select>, 0 text under 12px; the injected control probe is counted by all four counters and reads 0 once removed`;
}

// --- P8.2: the settings pages ------------------------------------------------------------------------------------------------------------
// The baseline is what the OLD settings page (HEAD d8a045e, one long page) sent and said on the same fixtures (fixtures/settings-bodies-baseline.json, recorded before any page was touched):
// the new pages must send the same requests, body for body.  Writes are read from the fake backend (`state.settings.writes`); the keys typed are obvious fakes.
const SB = JSON.parse(fs.readFileSync(new URL("./fixtures/settings-bodies-baseline.json", import.meta.url), "utf8"));
const ST_KEY1 = "fake-key-for-smoke-01", ST_KEY2 = "fake-key-for-smoke-02", ST_TOKEN = "fake-token-for-smoke-01", ST_PUSH_USER = "fake-pushover-user-01", ST_PUSH_APP = "fake-pushover-app-01";
const ST_SECTIONS = ["models", "notifications", "appearance", "data", "account"];
const ST_LABELS = { models: "模型", notifications: "通知", appearance: "外观", data: "数据", account: "账户" };
const stAll = (view) => view.mock.state.settings.writes;
/** The writes of the page without the asks for the provider's model list (those are reads in spirit and come on their own timing; settings-model-discovery counts them). */
const stWrites = (view) => stAll(view).filter((w) => w.path !== "/model-catalog/models");
/** The writes of the baseline's `sent` list (GETs are reads, not writes): method, path and the body as the old page sent it. */
const stOld = (sent) => sent.filter((r) => r.method !== "GET").map((r) => ({ method: r.method, path: r.path.replace(/^\/agent-chat/, ""), body: r.body }));
/** The fake backend's writes `from` on, against what the old page sent: same count, same order, same method, path and body (character for character). */
function stSame(view, old, what, from = 0) {
  const got = stWrites(view).slice(from).map((w) => ({ method: w.method, path: w.path, body: w.body === null ? null : JSON.stringify(w.body) }));
  assert(JSON.stringify(got) === JSON.stringify(stOld(old)), `${what}: sent ${JSON.stringify(got)}, the old page sent ${JSON.stringify(stOld(old))}`);
}
async function stWaitWrites(view, count, what) {
  const end = Date.now() + 10000;
  while (stWrites(view).length < count && Date.now() < end) await view.page.waitForTimeout(60);
  assert(stWrites(view).length >= count, `${what}: ${stWrites(view).length} of ${count} request(s) went out`);
  await view.page.waitForTimeout(150);
}
/** A settings sub page on the fake backend; `ready` is its body (the page has read what it shows). */
async function stOpen(ctx, label, section, ready, { state, width = 1440, theme = "light", motion = false, identity = "personal", locale } = {}) {
  const view = await newView(ctx.browser, { width, theme, label, unmatched, motion, identity, ...(locale ? { locale } : {}), ...(state ? { fixtureState: state } : {}) });
  view.consoleTexts = [];
  view.page.on("console", (m) => { view.consoleTexts.push(m.text()); });
  await view.context.addInitScript(() => { window.__downloads = []; const click = HTMLAnchorElement.prototype.click; HTMLAnchorElement.prototype.click = function () { if (this.download) { window.__downloads.push(this.download); return; } return click.call(this); }; });
  await view.page.goto(`${ctx.server.url}#/settings/${section}`, { waitUntil: "load" });
  await view.page.waitForSelector(ready, { state: "visible", timeout: 30000 });
  await settle(view.page, { pinTranscript: false });
  return view;
}
const ST_MODELS = "[data-testid=role-row]";
